BEGIN;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"5d8246cc-3aed-445d-a5a4-9f9cfaff8207": {"definition": "A pick point is the specific rated location at which a lifting force is applied to a load—either the attachment on the overhead structure a point hangs from, or the designated load-bearing node on a truss or object where a hoist, sling, or shackle connects. Manufacturers' load tables define the allowable pick points, maximum point load, and spacing for each span, because applying load away from a rated point can overstress the structure.", "plain_english": "A pick point is the exact spot where a lift connects to a load. On a truss, the maker's load chart shows where these points can go. It also shows how much each point can hold. Connecting between rated points can overload and break the truss.", "purpose_function": "It defines a known, rated attachment location so the load path is predictable and every connection stays within the structure's tested limits.", "practical_application": "A rigger picks a truss only at the pick points shown on the manufacturer's load table, staying within the rated point load and maximum spacing for the span.", "category": "Rigging point", "related_terms": ["Pick", "Bridle", "Working load limit", "Audio truss", "Chain hoist", "Shackle"], "common_mistakes": ["Attaching a hoist or sling between a truss's rated pick points instead of at a designated node, which can overstress the chord.", "Ignoring the manufacturer's load table, which sets the allowable pick points, point loads, and spacing for each truss and span.", "UNSAFE: Exceeding the rated load at a pick point, or adding points beyond the tested configuration, which can collapse the truss over people; loads must follow the manufacturer's load chart and ANSI/ESTA E1.2 truss practice."], "scenario_contexts": ["Reading a truss load chart to choose pick points for a flown line-array.", "Setting bridle apexes so each pick point on the structure stays within its rated load.", "Checking that hoist attachments land on rated truss nodes, not mid-span."]}, "08623713-aea8-4931-b59f-be9c1d3103a1": {"definition": "A pin rail is a heavy horizontal rail fitted with removable belaying pins—mounted at stage level, on a fly gallery, or along the wall of a hemp house—to which the hand (operating) lines of a rope or hemp rigging set are tied off. Each line is belayed to its own pin with a figure-eight tie, holding the flown load at its set trim.", "plain_english": "A pin rail is a strong rail fitted with removable pins. Crews tie off the ropes that fly scenery to these pins. The tie holds each load at the right height. It is used on old rope-and-hand fly systems.", "purpose_function": "It gives a rope or hemp fly system a fixed, organized place to secure each hand line, holding loads at their trim without power or counterweights.", "practical_application": "A stagehand hauls a hemp line to trim, then belays it to its pin on the pin rail with a figure-eight tie so the load stays put until the next cue.", "category": "Fly system hardware", "related_terms": ["Belaying pin", "Hemp system", "Purchase line", "Head block", "Loft block", "Batten"], "common_mistakes": ["Confusing the pin rail with the operating rail of a counterweight system; the pin rail belays hand lines on pins, not a rope lock on a purchase line.", "Tying a sloppy or incorrect hitch instead of a proper figure-eight belay, so the line can slip under load.", "UNSAFE: Belaying or releasing a loaded hemp line at the pin rail without enough trained crew or correct technique; with no counterweight the load can run away and fall, so lines must be controlled by qualified crew per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Tying off hemp lines on the pin rail after flying a drop to trim in a historic theatre.", "Teaching new crew the figure-eight belay used to secure lines on belaying pins.", "Tracing which pin holds which line before striking scenery from a rope set."]}, "f5a8a6c5-52f0-482b-89f9-b05d0754f14a": {"definition": "To 'pipe in' is to fly a pipe (batten) in—to lower it from the fly loft down toward the stage deck, its onstage or working position—as opposed to flying it out. In fly-system convention 'in' means traveling down toward the stage, where a batten is loaded, dressed, or brought into the stage picture.", "plain_english": "To pipe in means to lower a fly pipe down toward the stage. In a fly system, 'in' is the down direction. Crews pipe a batten in to load gear on it or to bring scenery into view. The pipe is a batten that hangs over the stage.", "purpose_function": "It describes lowering a batten to working or playing height so crew can load, focus, or reveal what hangs on it, and it fixes the shared meaning of 'in' as the downward direction.", "practical_application": "On the operator's call, a crew pipes a batten in to deck height to hang lights or scenery, then flies it back out once the load is secured.", "category": "Fly operation", "related_terms": ["Pipe out", "Batten", "In trim", "Low trim", "Purchase line", "Lineset"], "common_mistakes": ["Reversing the convention by thinking 'in' means up; in a fly system 'in' brings the batten down toward the stage.", "Piping a batten in without warning the crew below or checking the landing area is clear.", "UNSAFE: Bringing a pipe in on an unbalanced or out-of-weight lineset, which can run away and injure crew; the arbor and batten loads must be matched before operating per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Piping an electric in to deck height to hang and cable fixtures.", "Bringing a drop into the stage picture on a scene-change cue.", "Lowering a batten in so crew can attach scenery before flying it out."]}, "3f821ed6-0331-43bf-ab18-f2a5d9e1d0c3": {"definition": "To 'pipe out' is to fly a pipe (batten) out—to raise it up from the stage into the fly loft, its stored or masked position—as opposed to flying it in. In fly-system convention 'out' means traveling up away from the stage, clearing the batten and its load above the audience's sightlines.", "plain_english": "To pipe out means to raise a fly pipe up into the loft. In a fly system, 'out' is the up direction. Crews pipe a batten out to store it or to clear it from view. This lifts the batten and its load high above the stage.", "purpose_function": "It describes raising a batten to its stored or masked height so it clears the stage and sightlines, and it fixes the shared meaning of 'out' as the upward direction.", "practical_application": "After a piece is loaded and secured, a crew pipes the batten out to high trim to clear the stage until it is needed.", "category": "Fly operation", "related_terms": ["Pipe in", "Batten", "Out trim", "High trim", "Purchase line", "Lineset"], "common_mistakes": ["Reversing the convention by thinking 'out' means down; in a fly system 'out' takes the batten up into the loft.", "Piping a batten out past its safe travel so the arbor or load strikes the grid or other scenery.", "UNSAFE: Flying a pipe out on an unbalanced or out-of-weight lineset, which can run away; the arbor and batten loads must be matched before operating per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Piping a border out to high trim so it masks the loft but hangs clear above the set.", "Raising a loaded electric out of view between scenes.", "Flying a drop out to storage after a scene change."]}, "16e449e5-92a2-49f6-b8c1-6567cfe76ee9": {"definition": "The purchase line (operating line) is the rope the operator handles to raise and lower a counterweight lineset; it runs from the top of the arbor up over the head block, down through the rope lock at the operating rail, and around the tension (idler) block at the base, forming an endless loop. Pulling the purchase line moves the arbor and its balanced batten together.", "plain_english": "The purchase line is the rope an operator pulls to move a counterweight set. It runs in a loop from the top of the weight carriage, over a pulley, and back down. A rope lock grips it to hold the load in place. Pulling it raises or lowers the pipe.", "purpose_function": "It gives the operator a continuous hand line to drive the arbor and batten up and down, and a surface for the rope lock to grip and hold the balanced load at trim.", "practical_application": "An operator releases the rope lock and hauls the purchase line hand over hand to move a lineset to trim, then sets the rope lock to hold it.", "category": "Counterweight Rigging", "related_terms": ["Arbor", "Rope lock", "Head block", "Tension block", "Counterweight system", "Lift line"], "common_mistakes": ["Confusing the purchase line, the operator's rope, with the lift lines, the steel cables that actually carry the batten's load.", "Relying on the rope lock alone to hold an unbalanced load; the rope lock is not a brake for out-of-weight sets.", "UNSAFE: Operating the purchase line on an out-of-weight lineset, which can run away and pull the operator or drop the load; the arbor and batten must be balanced before the rope lock is released, per ANSI/ESTA E1.4-1."], "scenario_contexts": ["Hauling the purchase line to fly a lighting electric to trim.", "Setting the rope lock on the purchase line to hold a balanced batten in place.", "Inspecting the purchase line for wear where it passes through the rope lock."]}, "2b35965a-9b10-4255-a764-909fe0beb429": {"definition": "A service platform is a fixed or built-up elevated walking-working surface that gives crew safe standing access to overhead or hard-to-reach equipment such as loudspeakers, lighting, projectors, and rigging for setup, focus, and maintenance. As a working surface it is guarded and used in accordance with walking-working-surface and fall-protection requirements (OSHA 29 CFR 1910 Subpart D).", "plain_english": "A service platform is a fixed raised deck you stand on to reach gear up high. Crews use it to set up and fix lights, speakers, and rigging safely. It has guardrails so no one falls.", "purpose_function": "It provides a stable, guarded place to work at height so equipment can be reached and maintained without ladders or improvised access.", "practical_application": "A technician climbs to the service platform to focus a lighting fixture, swap a lamp, or inspect a rigging point, clipping in where fall protection is required.", "category": "Venue Structure", "related_terms": ["Catwalk", "Ship ladder", "Side gallery", "Guardrail", "Fall protection", "Gridiron"], "common_mistakes": ["UNSAFE: Overloading a service platform beyond its rated capacity by piling on gear or crowding on too many crew.", "UNSAFE: Removing or leaning over guardrails, or working from a platform with missing rails, instead of using proper fall protection.", "Confusing a fixed service platform with a temporary personnel lift or scaffold, which carry their own separate rules."], "scenario_contexts": ["Reaching a flown loudspeaker cluster from a permanent service platform to replace a driver.", "Standing on a ceiling-slot service platform to focus front-of-house lighting.", "Accessing a chain hoist or rigging point for inspection from a fixed platform near the grid."]}, "99bd09e8-5a36-4554-a437-8bc787892804": {"definition": "Shackles are U- or bow-shaped rigging connectors closed by a removable pin, used to join slings, wire rope, chain, and fittings to loads and anchor points. The two common forms are the anchor (bow) shackle, whose wider bow accepts multiple or angled sling legs, and the chain (dee) shackle, for a single in-line pull; their design, marking, rated capacity, and use are governed by ASME B30.26.", "plain_english": "Shackles are metal loops closed by a pin that link rigging parts to a load. Think of a strong link you can open and close. The wide 'bow' type takes several sling legs; the narrow 'dee' type takes a straight pull.", "purpose_function": "They give a strong, removable connection between rigging parts so slings and hardware can be attached to and detached from loads and anchor points.", "practical_application": "A rigger picks a shackle whose working load limit exceeds the calculated leg load, seats the pin fully, and orients the bow so multiple legs pull on the bow, not the pin.", "category": "Rigging Hardware", "related_terms": ["Working load limit", "Wire rope sling", "Master link", "Design factor", "Chain hoist", "Load path"], "common_mistakes": ["UNSAFE: Replacing a lost shackle pin with a bolt or any non-matching pin; only the manufacturer's rated pin makes the shackle whole.", "UNSAFE: Using a screw-pin shackle where the pin can roll or unscrew under movement; a bolt-type (safety) shackle is required for long-term or dynamic connections.", "UNSAFE: Side-loading a shackle or exceeding its working load limit without applying the manufacturer's rated capacity reductions.", "Using an unmarked shackle whose rating and grade cannot be verified, or misreading the stamped capacity."], "scenario_contexts": ["Connecting a wire-rope sling to a beam clamp when hanging a truss.", "Joining multiple bridle legs into a master link at a rigging point.", "Inspecting shackles before a show for markings, wear, deformation, and a free, fully seated pin."]}, "70905e3f-3aca-465f-ba97-cf06882e350d": {"definition": "A ship ladder (ship stair) is a steep stairway with a slope between 50 and 70 degrees from horizontal, fitted with treads, open risers, and stair rails, used where a conventional stair is too shallow-angled to fit but a vertical ladder would be unsuitable. In OSHA's walking-working-surface rules it is a defined stair type (29 CFR 1910.21) with construction requirements in 1910.25(e).", "plain_english": "A ship ladder is a very steep set of stairs, like the stairs on a boat. It sits between a normal staircase and a straight-up ladder. Crews climb it to reach catwalks, galleries, or the grid. It has handrails, and you usually face it going down.", "purpose_function": "It gives code-compliant foot access between levels in tight spaces where a standard stair will not fit, while being safer to climb than a fixed vertical ladder.", "practical_application": "A technician uses a ship ladder to reach a lighting catwalk, fly gallery, or grid, keeping three points of contact and often facing the treads when descending.", "category": "Venue Structure", "related_terms": ["Catwalk", "Fly gallery", "Side gallery", "Service platform", "Gridiron", "Fall protection"], "common_mistakes": ["UNSAFE: Carrying tools or gear by hand while climbing instead of using a hoist line or tool bag, which breaks three points of contact.", "UNSAFE: Descending a steep ship ladder facing outward as if it were a normal stair; the steep slope usually means facing the treads.", "Confusing a ship ladder (a defined stair at 50-70 degrees) with a fixed ladder (steeper, near vertical) or an ordinary stair."], "scenario_contexts": ["Climbing a ship ladder from a fly gallery up to the gridiron.", "Reaching an overhead followspot or lighting position by ship ladder.", "Accessing a mezzanine amplifier or dimmer room where floor space is limited."]}, "ae2858a8-21a9-4b14-93f5-599efe217f0e": {"definition": "Show trim is the finalized vertical height (trim) at which a flown element such as a batten, truss, electric, drop, or loudspeaker is set for the running of the performance, as distinct from a lower working (load) trim used during setup. It is the recorded in-show position a piece returns to on its cue.", "plain_english": "Show trim is the exact height a flown piece hangs at during the performance. It is different from the height crews use while loading it. The team records it so the piece lands in the same spot every show.", "purpose_function": "It fixes and documents the correct performance height of each flown item so scenery, lighting, and speakers sit at the intended, repeatable position every night.", "practical_application": "A flyperson or automation operator sets each line set to its recorded show trim during preset and returns it there on cue, checking sightlines and clearances.", "category": "Trim and travel", "related_terms": ["Trim", "High trim", "Dead", "Batten", "Line set", "Sightline"], "common_mistakes": ["Confusing show trim (the performance height) with work or load trim (the low height used to load and access a batten).", "Failing to record or mark show trims, so pieces are re-set by eye and end up at inconsistent heights.", "UNSAFE: Flying a piece to its show trim without checking clearances and the fall zone below, risking collisions or a dropped load."], "scenario_contexts": ["Marking and recording each line set's show trim during technical rehearsals.", "Restoring a lighting truss to its show trim on a cue after it was lowered to refocus.", "Programming show trims into a motorized rigging console so battens fly to repeatable heights."]}, "f802f043-848e-4fc7-8407-63ef6d1efe52": {"definition": "A side gallery is a raised walkway or platform running along a side wall of the stage house, above stage level, giving access to the fly system and overhead services; when it carries the fly operating (pin) rail it serves as the fly gallery from which line sets are worked. Some houses also have a higher loading gallery for adding counterweight to arbors.", "plain_english": "A side gallery is a raised walkway along the side wall above the stage. Crew stand on it to work the ropes and pulleys that fly scenery. It keeps them off the stage floor and close to the rigging.", "purpose_function": "It provides elevated side access along the stage house so crew can operate the fly system and reach overhead equipment without working from the stage floor.", "practical_application": "A fly operator works line sets from the side gallery's pin or operating rail, while riggers use it to reach loft blocks and overhead cable runs.", "category": "Venue Structure", "related_terms": ["Fly gallery", "Loading gallery", "Pin rail", "Gridiron", "Catwalk", "Counterweight system"], "common_mistakes": ["Confusing the side (fly) gallery, where lines are operated, with the higher loading gallery, where counterweight is added to arbors.", "UNSAFE: Storing loose tools or hardware at a gallery edge or knocking them off, creating a dropped-object hazard to people below.", "Assuming every venue has side galleries; many modern or smaller houses operate the fly system from stage level instead."], "scenario_contexts": ["Operating counterweight line sets from the pin rail on the side gallery.", "Reaching loft blocks and cable runs along the stage-house wall for maintenance.", "Spotting a flown piece or passing a line from the side gallery during a scene change."]}, "60c3d71e-718a-45ec-bb36-fefbcb5f85eb": {"definition": "Slack is the amount of looseness or non-tension in a line, rope, chain, or sling before it takes up load. In rigging practice slack is taken up slowly and the load raised smoothly, because suddenly loading slack shock-loads the rigging and can generate forces well above the static load; ASME B30.9 and OSHA prohibit shock loading of slings.", "plain_english": "Slack is the loose, un-tight part of a rope, chain, or sling. If a load drops onto slack, it jerks the rigging with a force far bigger than the load's weight. So crews take up slack slowly and lift smoothly, never with a sudden snap.", "purpose_function": "Recognising and controlling slack lets riggers apply load gradually and avoid shock loading, protecting slings, hardware, and structure from sudden peak forces.", "practical_application": "Before a lift a rigger removes excess slack, confirms all legs will share the load, then hoists slowly so the rigging comes under tension smoothly rather than snapping tight.", "category": "Loads and Forces", "related_terms": ["Shock load", "Working load limit", "Sling", "Dynamic load", "Design factor", "Chain hoist"], "common_mistakes": ["UNSAFE: Letting a hoist or line snatch up slack so the load starts with a jerk, shock-loading the rigging above its rated capacity.", "UNSAFE: Leaving slack in one leg of a multi-leg bridle so the remaining legs carry the whole load.", "Thinking a little slack is harmless; even a short free drop before a sling tensions can multiply the force on the hardware."], "scenario_contexts": ["Taking up slack in chain-hoist load chains evenly before flying a truss grid.", "Removing slack from bridle legs so both legs share the point load.", "Lowering a batten smoothly to avoid slapping slack into the lift lines at the bottom of travel."]}, "f707fc47-6f86-4576-88e5-42aedd8a14e8": {"definition": "Span is the horizontal distance between two points of support of a beam, truss, or bridle. It is a primary factor in load capacity: for a given truss or beam the allowable uniformly distributed and point loads decrease as the span between supports increases, so span must be checked against the manufacturer's load table or an engineered calculation.", "plain_english": "Span is the gap between the two points that hold up a beam or truss. The wider the gap, the less weight the truss can safely carry. So crews always check the load chart for that exact span before hanging gear.", "purpose_function": "Span defines how far a structural member reaches unsupported, which sets its bending stress and deflection and therefore how much load it may safely carry between supports.", "practical_application": "A rigger measures the span between hang points, then reads the truss manufacturer's load table for that span to find the maximum allowable load and deflection.", "category": "Loads and Forces", "related_terms": ["Truss", "Working load limit", "Deflection", "Point load", "Uniformly distributed load", "Bridle"], "common_mistakes": ["UNSAFE: Applying a truss's best-case (short-span) rating at a longer span, overloading it because capacity falls as span grows.", "UNSAFE: Adding hang points or loads without re-checking the span against the load table, or ignoring deflection limits.", "Confusing span (distance between supports) with the total length of the truss, which may overhang past the supports."], "scenario_contexts": ["Reading a truss manufacturer's load table to find the safe load for a given span.", "Deciding where to place chain hoists to keep each truss span within its rated capacity.", "Calculating a bridle so the span and leg angles keep forces within the hardware limits."]}, "9fe076cf-b690-42df-a430-e23796082f5a": {"definition": "A span set (spanset) is the trade name for a synthetic round sling: an endless loop of load-bearing polyester (or nylon) yarns enclosed in a protective woven tubular jacket. Riggers wrap it around trusses, motors, and other loads for suspension or lifting; it spreads force over a soft, wide contact area and is rated to a working load limit that varies with the hitch (vertical, choke, or basket) per ASME B30.9.", "plain_english": "A span set is a strong fabric loop used to hang heavy gear. Many polyester threads inside a soft cover carry the weight. Riggers wrap it around a truss or motor. It grips without denting the metal. Each one has a safe weight limit you must never pass.", "purpose_function": "It gives a soft, high-strength, non-marring point for suspending or lifting loads, spreading the force so it will not crush aluminum truss while carrying rated loads safely.", "practical_application": "A rigger chokes or baskets a span set around a truss chord or beam, connects it to a shackle and hoist, and checks its tag and condition before trusting it with any load.", "category": "Lifting slings", "related_terms": ["Shackle", "Working load limit", "Basket hitch", "Choke hitch", "Truss", "Chain hoist"], "common_mistakes": ["Assuming a span set has one fixed capacity; its working load limit changes with the hitch used, so a basket hitch and a choke hitch carry different rated loads.", "UNSAFE: Running a span set over a sharp edge or truss corner without edge protection; the fibers can be cut under load, so soft edge protectors or corner blocks must be used.", "UNSAFE: Keeping a cut, frayed, heat-damaged, or untagged span set in service; a damaged round sling must be removed from service and destroyed, because its inner yarns carry the entire load per ASME B30.9.", "Confusing a span set with steel wire rope; a span set is soft synthetic fiber and must be protected from cuts, heat, and chemicals that would not harm steel."], "scenario_contexts": ["Wrapping a span set in a basket hitch around a venue beam to hang a chain hoist for a line-array.", "Choking a span set around a truss chord to attach a shackle and dead-hang a point.", "Inspecting span sets on load-in and pulling any with cut jackets or missing capacity tags.", "Choosing the correct span set length and rating so the hitch angle keeps forces within the working load limit."]}, "ece4ec59-3de8-4948-b581-9432fdd1ee7c": {"definition": "A stage catwalk is a permanently installed elevated walkway that gives crew safe overhead access to lighting, rigging, and equipment positions without ladders or lifts. Fitted with guardrails and toe boards, catwalks run above the stage or auditorium and act as both circulation routes and mounting positions for instruments and speakers.", "plain_english": "A stage catwalk is a high, railed walkway built into a venue. Crew walk along it to reach lights and rigging over the stage or seats. It saves them from using tall ladders. It has rails and a low kickboard so people and tools do not fall off.", "purpose_function": "It gives technicians safe, quick, repeatable access to overhead equipment for hanging, focusing, and maintenance, replacing riskier ladders and lifts and providing fixed mounting positions for lights and speakers.", "practical_application": "A lighting technician walks the catwalk to focus front-of-house spotlights, clipping instruments to its pipe rail and staying inside the guardrails while working at height.", "category": "Access structures", "related_terms": ["Gridiron", "Technical gallery", "Fly gallery", "Lighting bridge", "Fly tower", "Fall protection"], "common_mistakes": ["Confusing a catwalk with a fly gallery; a catwalk is a general access walkway, while a fly gallery is a specific working platform for operating the fly system.", "UNSAFE: Overloading a catwalk or its lighting pipe beyond the rated capacity; catwalks and their pipes have load limits, and exceeding them can overstress the structure.", "UNSAFE: Leaning over or climbing the guardrails, or leaving tools loose near the edge; per OSHA walking-working-surface rules, guardrails and toe boards stop people and objects falling and must not be defeated.", "Assuming any raised walkway is a catwalk; catwalks are engineered, guarded structures, not scaffold planks or unrated surfaces."], "scenario_contexts": ["Focusing front-of-house lighting from an auditorium catwalk during a technical rehearsal.", "Reaching overhead speaker rigging from a catwalk to adjust a flown array.", "Running and dressing cable along a catwalk to feed instruments hung on its rail.", "Inspecting overhead rigging points by walking the stage-house catwalks."]}, "803add8f-179e-434e-96bf-eb36955bd210": {"definition": "A stage tower (fly tower or stage house) is the tall part of a theatre building rising above the stage, built high enough to fly scenery, drapery, lighting, and equipment up out of the audience's sightlines. It contains the gridiron, fly system, galleries, and battens, and its height governs how much can be raised completely out of view.", "plain_english": "A stage tower is the tall box built above the stage. It is high enough to lift scenery and lights up out of sight. Inside it are the pulleys, ropes, and pipes used to fly things. The taller it is, the more can be hidden overhead.", "purpose_function": "It provides the vertical space and structure needed to raise, store, and lower flown scenery and equipment, so pieces can appear and vanish cleanly and be kept ready above the stage.", "practical_application": "A rigger works within the stage tower on the grid and galleries to hang linesets and trim battens, using its height to fly full drops and scenery clear of the acting area.", "category": "Venue structure", "related_terms": ["Gridiron", "Fly system", "Fly gallery", "Batten", "Proscenium", "Stage catwalk"], "common_mistakes": ["Confusing the stage tower with the whole backstage area; the term refers to the tall flying space above the stage, not the wings or floor-level backstage.", "Assuming any scenery can be fully hidden regardless of height; a piece flies fully out of view only when the tower is tall enough, so a low tower limits what can be flown.", "UNSAFE: Treating the grid and galleries in the stage tower as casual storage or walkways without fall protection; work at height there requires guarded access and safe rigging practice."], "scenario_contexts": ["Checking a stage tower's height to confirm a backdrop can fly fully out of the audience's sightlines.", "Planning lineset positions on the gridiron inside the stage tower.", "Comparing a venue with a full stage tower that allows counterweight flying against a low ceiling that does not."]}, "986dea96-816e-42f9-9f2e-43a06ccaa0df": {"definition": "Steel cable, in entertainment rigging, is wire rope: many steel wires laid into strands that are laid around a core, used as lift lines, bridles, safeties, and suspension members. Stage work commonly uses 7x19 galvanized aircraft cable (GAC), terminated with swaged fittings over thimbles, and every assembly carries a working load limit set by its construction, diameter, and end terminations.", "plain_english": "Steel cable is rope made of many thin steel wires twisted together. It is strong and flexible, so riggers use it to hang and lift heavy gear. The ends are finished with special sleeves, not knots. Each cable has a safe weight limit set by its size and fittings.", "purpose_function": "It gives a strong, flexible, fire-resistant load-bearing line for suspending and lifting equipment where fiber rope or slings will not do, carrying rated loads when correctly sized and terminated.", "practical_application": "A rigger makes up steel cable lift lines or safeties with swaged sleeves and thimbles, confirms the diameter and rating, and inspects for broken wires, kinks, and corrosion before use.", "category": "Wire rope", "related_terms": ["Wire rope", "Aircraft cable", "Swage fitting", "Thimble", "Working load limit", "Bridle"], "common_mistakes": ["UNSAFE: Tying knots in steel cable or bending it sharply; knots and tight bends drastically cut its strength, so wire rope must be terminated with proper swaged or approved fittings over thimbles.", "UNSAFE: Keeping wire rope in service with broken wires, kinks, birdcaging, or corrosion; damaged wire rope must be removed from service per ASME B30 inspection criteria because it can fail under load.", "Confusing a cable's breaking strength with its working load limit; the working load limit is far lower, found by dividing breaking strength by a design (safety) factor.", "Assuming all steel cable is interchangeable; construction (such as 7x19), diameter, and end terminations all set the rated capacity."], "scenario_contexts": ["Making up 7x19 galvanized aircraft cable lift lines with swaged thimble eyes for a rigging point.", "Fitting steel safety cables (safeties) to overhead lighting fixtures as a secondary support.", "Inspecting wire rope for broken wires and kinks during a pre-show rigging check.", "Selecting cable diameter and termination so the assembly's working load limit exceeds the suspended load."]}, "f2949bc3-52a7-42fb-8e10-b2f13d0768f6": {"definition": "A technical gallery is a raised, railed working platform running along the side or rear of a stage house or auditorium that gives crew access to and mounting positions for technical equipment such as lighting, rigging, and the fly system. Closely related to the fly gallery and working gallery, it serves as an elevated walkway and operating position above stage level.", "plain_english": "A technical gallery is a high, railed walkway along the side of the stage. Crew stand on it to reach and operate lights and rigging. It works like a balcony built for the technical team. It keeps them safely off ladders while working up high.", "purpose_function": "It gives safe elevated access and fixed positions for mounting and operating technical equipment, letting crew reach overhead systems from a guarded platform instead of ladders or lifts.", "practical_application": "A technician uses a technical gallery to reach side lighting positions, work fly-system fittings, or run and dress cable, staying within its guardrails while working above the stage.", "category": "Access structures", "related_terms": ["Fly gallery", "Loading gallery", "Stage catwalk", "Gridiron", "Fly tower", "Fly system"], "common_mistakes": ["Confusing a technical gallery with the loading gallery; the loading gallery is specifically where counterweight is added to arbors, while a technical gallery is a broader access and equipment platform.", "Assuming a gallery is just a viewing balcony; a technical gallery is a working platform with equipment positions and load limits, not audience seating.", "UNSAFE: Overloading a gallery or leaning tools and gear over its rail; galleries have rated capacities and guardrails that must not be defeated, per safe working-at-height practice."], "scenario_contexts": ["Operating side-lighting booms and their cable from a technical gallery during a show.", "Reaching fly-system fittings and spot lines from a working gallery in the stage house.", "Routing and tying off cable along a technical gallery to feed equipment hung nearby."]}, "0a749458-3ec6-4c63-8f9b-6b8eef7d7c5f": {"definition": "A tension block is a floor-mounted sheave block at the bottom of a counterweight fly system that guides the operating (hand) line and keeps it under tension through its full travel. Often called a floor block, it turns the operating line at the base of its run and, when spring-loaded or adjustable, holds constant tension so the line tracks correctly in the rope lock and head block.", "plain_english": "A tension block is a pulley near the floor of a stage flying system. It guides the hand rope that crew pull to raise and lower pipes. It keeps that rope pulled tight so it cannot go slack or jump its groove. It sits at the bottom, opposite the big pulley up top.", "purpose_function": "It keeps the operating line taut and correctly aligned at the bottom of its loop, so the rope runs smoothly in its grooves and the rope lock grips reliably instead of the line going slack and slipping.", "practical_application": "A rigger checks the tension block at the base of a lineset to confirm the operating line is guided and tensioned, adjusting a spring or take-up block if the hand line has gone slack.", "category": "Fly system hardware", "related_terms": ["Head block", "Loft block", "Operating line", "Rope lock", "Counterweight system", "Arbor"], "common_mistakes": ["Confusing the tension block with the head block; the head block is the large multi-sheave block at the top that carries the load, while the tension block is the floor block that tensions the operating line at the bottom.", "Assuming the tension block carries the flown load; it guides and tensions the operating (hand) line, not the lift lines bearing the batten's weight.", "UNSAFE: Operating a lineset with a slack, misaligned, or damaged tension block; a poorly tensioned operating line can jump its groove or keep the rope lock from holding, so it must be maintained and inspected."], "scenario_contexts": ["Adjusting a spring-loaded tension block to take slack out of an operating line.", "Tracing an operating line from the rope lock down to the tension block during a fly-system inspection.", "Diagnosing a hand line that jumps or binds by checking the tension block's alignment and sheave."]}, "3736c340-ca09-4a37-8149-3b3e1244cf4c": {"definition": "In flying and hoist systems, travel is the total vertical distance a batten, arbor, or hoist load block can move between its lowest and highest positions. For a counterweight set it is limited by the arbor's run in its guides; for a chain hoist or winch it is set by the usable length of load chain or wire rope, and it is always less than the full grid or beam height.", "plain_english": "Travel is how far a flown pipe or load can move up and down. It runs from the lowest point to the highest point. A hoist can lift a load only as far as its chain or rope allows.", "purpose_function": "It defines the working range of a lineset or hoist, so riggers can plan trims and confirm a load can reach the needed height without running out of movement.", "practical_application": "A rigger checks available travel before a hang, making sure the hoist's chain or the arbor's run is long enough to fly the load from the deck up to its high trim.", "category": "Trim and travel", "related_terms": ["Trim height", "High trim", "Low trim", "Counterweight arbor", "Chain motor", "Batten"], "common_mistakes": ["Confusing travel with trim height: travel is the full range of movement, while trim height is a single set position within that range.", "Assuming a batten can travel the full grid height; the arbor's run or the chain length always stops it short of the head block or beam.", "UNSAFE: Running a hoist or arbor past the end of its travel, which can two-block a hoist or drive an arbor into the head block and shock-load or fail the rigging."], "scenario_contexts": ["Checking that a chain motor has enough travel to fly a truss from the deck to trim height.", "Confirming an arbor has enough travel to reach a batten's plotted high trim before a hang.", "Planning a moving-scenery cue so the piece stays within the lineset's available travel."]}, "33be6f56-f2aa-464d-bdc3-55df6a9ab4a8": {"definition": "Trim height is the elevation at which a flown batten and its load are set to hang for a given moment, measured from the stage floor to the pipe. Each lineset is plotted with named trims (for example a high/out trim and a low/in trim), and the batten is 'in trim' when it sits level end to end at its designated height.", "plain_english": "Trim height is how high above the stage a flown pipe is set to hang. Each pipe has marked heights for different moments in a show. When the pipe sits level at the right height, it is in trim.", "purpose_function": "It gives every flown piece a repeatable, recorded position, so scenery, lighting, and drapes return to the same height each performance and stay clear of sightlines and other gear.", "practical_application": "An operator flies a batten until its trim marks line up at the plotted trim height, confirms it hangs level, and records the height on the line-set schedule.", "category": "Trim and travel", "related_terms": ["High trim", "Low trim", "In trim", "Travel", "Batten", "Counterweight system"], "common_mistakes": ["Confusing trim height, which is a single set position, with travel, which is the full range a batten can move.", "Recording a trim height but ignoring level, so the batten reaches the right height while hanging tilted to one side.", "UNSAFE: Setting a trim height without checking clearances, letting a piece collide with other scenery, the grid, or people when it is flown in or out."], "scenario_contexts": ["Setting and recording high and low trim heights for each lineset during a technical rehearsal.", "Adjusting one lift line so a batten reaches its plotted trim height and hangs level.", "Reading a line-set schedule to fly an electric to its trim height before focus begins."]}, "dcc232ef-c9f0-4f3b-866a-9af993c06f04": {"definition": "A vertical ladder is a fixed ladder installed at or close to 90 degrees to the floor and permanently attached to a structure to give climbing access to grids, catwalks, loft galleries, or roof steel. Under OSHA it is a form of fixed ladder; its construction, cages or wells, and required fall protection are governed by OSHA 29 CFR 1910.23 and 1910.28 (and 1926.1053 in construction) and by ANSI-ASC A14.3 for fixed ladders.", "plain_english": "A vertical ladder is a ladder fixed straight up and down to a building. Crews climb it to reach grids, catwalks, and high steel. Because the climb is straight up, a fall can be serious, so fall rules apply.", "purpose_function": "It provides permanent, space-saving climbing access to overhead work areas such as grids and catwalks that stairs cannot easily reach.", "practical_application": "A technician climbs a vertical ladder to reach a lighting grid or catwalk, keeping three points of contact and using the required cage or ladder-safety / fall-arrest system on tall runs.", "category": "Access and fall protection", "related_terms": ["Fixed ladder", "Fall protection", "Personal fall arrest system", "Catwalk", "Gridiron", "Three points of contact"], "common_mistakes": ["UNSAFE: Climbing a tall vertical ladder without the required fall protection; OSHA requires a ladder safety system or personal fall arrest system on fixed ladders that extend more than 24 feet (7.3 m) above a lower level.", "UNSAFE: Carrying tools or gear by hand while climbing instead of hoisting them separately, which breaks three points of contact and risks a fall.", "UNSAFE: Continuing to use a ladder with corroded, cracked, or missing rungs, rails, or cage parts instead of taking it out of service and reporting it.", "Assuming a cage by itself arrests a fall; under OSHA a cage is no substitute for a ladder safety or fall arrest system on new tall fixed ladders."], "scenario_contexts": ["Climbing a fixed vertical ladder to access a lighting grid or loft gallery.", "Inspecting a venue's roof-access vertical ladder and its fall-protection system before a load-in.", "Reaching a followspot position or catwalk by a permanent vertical ladder."]}, "9cd84fdc-cd18-412c-a557-f5ff6c3cee96": {"definition": "Wire rope is a flexible steel rope made of many individual wires laid helically into strands, which are in turn laid around a central core (fiber, a wire strand, or an independent wire-rope core). In rigging it is used for slings, lift lines, bridles, and safety cables; its selection, use, and inspection are covered by ASME B30.9 and OSHA 29 CFR 1910.184, which require a minimum design factor of 5 for wire-rope slings.", "plain_english": "Wire rope is a strong steel cable. Thin steel wires are twisted into strands. The strands are then twisted around a center core. Riggers use it to lift and hang loads, since it is far stronger than fiber rope of the same size.", "purpose_function": "It carries heavy suspended and lifted loads with high strength and controlled flexibility, serving as slings, lift lines, bridles, and safety cables throughout rigging.", "practical_application": "A rigger selects a wire-rope sling by its rated capacity and hitch, then inspects it for broken wires, kinks, birdcaging, and corrosion before every use, removing it from service if it meets the rejection criteria.", "category": "Rigging hardware", "related_terms": ["Working load limit", "Lift line", "Wire rope clip", "Bridle", "Design factor", "Swaged fitting"], "common_mistakes": ["UNSAFE: Continuing to use wire rope with broken wires, kinks, birdcaging, or corrosion; a sling must be removed from service when it meets the rejection criteria in ASME B30.9 and OSHA 29 CFR 1910.184.", "UNSAFE: Loading wire rope past its rated capacity, or forgetting that bending it over a small-diameter pin or a sharp edge sharply reduces its strength.", "UNSAFE: Installing wire rope clips wrongly, such as putting the saddle on the dead (short) end, which cuts the connection's holding strength.", "Confusing rope diameter with strength, or assuming all constructions are equal; strength depends on grade, construction, and core, not size alone."], "scenario_contexts": ["Selecting and inspecting a wire-rope sling to hang a lighting truss or loudspeaker array.", "Building a bridle from wire rope to spread a rigging point across two beams.", "Fitting an aircraft-cable wire-rope safety on a fixture as a secondary attachment."]}, "1130a527-c892-4d08-8fac-b69295f702ee": {"definition": "An Aviom-style system is a personal monitor-mixing system in which each performer has an individual personal mixer that receives many discrete audio channels over a low-latency digital audio network and builds and adjusts their own headphone or in-ear mix locally. The name comes from Aviom, whose A-Net personal-mixing products popularized the approach, and is now used generically for any similar per-musician monitoring system.", "plain_english": "It is a monitor system that gives each player a small personal mixer. Every musician sets the volume of each part in their own headphones. So the drummer and the cellist can each hear a different blend. It is common for players in a pit or on a crowded stage.", "purpose_function": "It lets every musician in an ensemble control their own monitor blend independently instead of sharing one mix, which improves comfort and timing, especially in a cramped pit where wedge monitors are impractical.", "practical_application": "A pit technician sends the ensemble's channels into the network, sets a personal mixer at each station, and helps players dial in their own headphone mixes during setup and sound check.", "category": "Personal monitoring", "related_terms": ["In-ear monitors", "Personal mixer", "Monitor mix", "Foldback", "Click track", "Digital audio network"], "common_mistakes": ["Thinking an Aviom-style system feeds the main PA or front-of-house mix; it only feeds the performers' personal monitors and does not change what the audience hears.", "Assuming every musician must share one mix; the whole point of the system is that each player builds an independent blend at their own mixer.", "UNSAFE: Setting headphone or in-ear levels dangerously loud to hear over the pit; prolonged high levels risk permanent hearing damage, so set the quietest workable level and follow recognized hearing-exposure limits."], "scenario_contexts": ["Giving each player in a musical-theatre pit their own headphone blend of the band, click, and conductor.", "Replacing shared wedge monitors in a tight orchestra pit where floor space is limited.", "Letting a percussionist boost the click while a string player boosts the woodwinds in the same show.", "Networking many monitor channels to per-seat personal mixers during a load-in and sound check."]}, "751d675c-1920-4cd2-9c97-d9cada0fcce6": {"definition": "Backline position is the placement of the backline—the on-stage rhythm-section gear such as guitar and bass amplifiers, keyboards, and the drum kit—within an ensemble layout, conventionally along the upstage (rear) edge of the performance area behind the front-line singers and lead players.", "plain_english": "Backline is the big gear at the back of a band: guitar and bass amps, keyboards, and the drums. Its position is simply where that gear sits on stage. It usually goes at the back, behind the singers and front players. This keeps loud amps away from the front microphones.", "purpose_function": "Placing the backline at the rear keeps loud amplifiers and the drum kit behind the vocalists and front microphones, which reduces spill into those mics and leaves the downstage area clear for performers who face the audience.", "practical_application": "During setup a technician marks the backline positions on the deck, spikes the drum riser and amp spots, and angles amps so their sound reaches the players without blasting into the vocal mics.", "category": "Stage layout", "related_terms": ["Bandstand", "Drum riser", "Stage plot", "Monitor mix", "Downstage", "Upstage"], "common_mistakes": ["Confusing the backline with the front line; the backline is the amps and drums placed at the rear, not the singers and lead instruments at the front.", "Placing loud amplifiers right beside vocal microphones, so amp sound spills into the mics and muddies the mix.", "Assuming backline position never affects sound; where amps and drums sit changes stage levels, monitor bleed, and sightlines to the conductor or band leader."], "scenario_contexts": ["Setting amp and drum-kit spots at the rear of a stage before a show.", "Reading a stage plot to see where each backline item belongs.", "Moving a bass amp back to reduce its spill into nearby vocal microphones.", "Fitting the backline into a shallow pit or thrust so players still see the conductor."]}, "bf2e366b-e594-4106-a438-705619ceb346": {"definition": "A backstage band—also called an offstage band or banda—is a group of instrumentalists positioned out of the audience's sight, behind the set, in the wings, or in a separate room, so their music sounds distant or as though coming from within the drama. Because they cannot see the pit conductor directly, they are usually kept together by a relay conductor, a monitor feed, or a video relay of the main conductor.", "plain_english": "A backstage band plays where the audience cannot see it. It hides behind the scenery, in the wings, or in another room. This makes the music sound far away, as if it comes from the story. The players follow the conductor through a video screen or a helper conductor.", "purpose_function": "It creates the effect of music coming from another place—an offstage march, a distant fanfare, or a hidden ensemble—so the composer can separate that sound from the main pit orchestra both musically and in space.", "practical_application": "A technician sets up the offstage players with a monitor feed and a video screen of the conductor, plus a light so they can read, and confirms cues and timing with stage management before the show.", "category": "Offstage ensemble", "related_terms": ["Orchestra pit", "Conductor monitor", "Video relay", "Wings", "Offstage microphone", "Monitor feed"], "common_mistakes": ["Thinking a backstage band can just follow the pit by ear; without a video relay or relay conductor, the offstage players and the pit easily drift apart.", "Forgetting the offstage players still need light, music stands, and a clear cue path even though the audience never sees them.", "Confusing a backstage band with the main pit orchestra; the backstage band is a separate, hidden group used for special effects."], "scenario_contexts": ["Placing a brass group in the wings for an offstage fanfare in an opera.", "Feeding conductor video and audio to musicians in a room behind the stage.", "Coordinating an offstage march so it lines up with the pit orchestra.", "Hiding a small band behind the set so music seems to come from another room."]}, "1dff4c19-0283-42e5-a323-c4a53443da29": {"definition": "A bandstand is a raised platform or open, often roofed structure on which a band or ensemble performs. It originated as an outdoor park pavilion shaped to project the band's sound toward a surrounding audience, and the term extends to any raised stage area assigned to a band.", "plain_english": "A bandstand is a raised stage built for a band to play on. Many are open, roofed structures in parks. The raised floor and roof help the music carry out to listeners. The word can also mean any raised spot set aside for a band.", "purpose_function": "It raises and often shelters the players so the audience can see and hear them, and its shape, especially the roof and back wall, helps reflect and project the sound outward to people spread around it.", "practical_application": "A technician working an outdoor bandstand plans power, weather cover for gear, and speaker placement, because the open structure gives little natural amplification for modern amplified acts.", "category": "Performance structure", "related_terms": ["Bandshell", "Acoustic shell", "Riser", "Backline position", "Chair layout", "Stage"], "common_mistakes": ["Confusing a bandstand with a bandshell; a bandshell is a large curved shell built to project sound, while a bandstand is a smaller raised, often roofed platform.", "Assuming a bandstand amplifies modern electric acts on its own; its shaping helps acoustic sound carry but rarely replaces a real sound system.", "Treating any stage as a bandstand; the term means specifically a raised platform or structure dedicated to a band."], "scenario_contexts": ["Setting up an acoustic band on an outdoor park bandstand for a summer concert.", "Planning power and weather protection for gear on an open bandstand.", "Placing a small ensemble on a raised bandstand so a standing crowd can see them.", "Adding a modest sound system to a bandstand that cannot project a modern act on its own."]}, "0476a58b-3203-4135-bb37-76ea3fc92b19": {"definition": "The brass section is the family of lip-vibrated wind instruments in an ensemble—typically French horns, trumpets, trombones, and tuba—treated both as an orchestration unit and as a seating block. In the standard orchestra it is conventionally placed across the rear of the ensemble, behind the woodwinds, because of its high sound-power output.", "plain_english": "The brass section is the group of brass instruments in an orchestra or band. It usually means the horns, trumpets, trombones, and tuba. Players buzz their lips into a metal mouthpiece to make the sound. Brass is loud, so it usually sits at the back.", "purpose_function": "Grouping the brass together lets a composer write for them as a powerful block of sound, and lets the ensemble seat these loud instruments at the rear where their output projects over the other sections without covering nearby players.", "practical_application": "When placing microphones or planning a pit, a technician treats the brass as one loud block at the back, spacing and sometimes screening it so it does not overpower the strings, woodwinds, or vocal mics.", "category": "Orchestral section", "related_terms": ["Woodwind section", "String section", "Percussion section", "Orchestra pit", "Chair layout", "Acoustic shield"], "common_mistakes": ["Defining brass by metal alone; the saxophone is made of brass but plays as a woodwind because it uses a reed, while brass instruments are defined by the buzzing-lips mouthpiece.", "Forgetting the French horn is part of the brass section, since it often bridges the brass and woodwind sound.", "Placing brass too close to open microphones or quieter sections, so its high output overpowers the mix."], "scenario_contexts": ["Seating trumpets, horns, trombones, and tuba across the back of an orchestra.", "Adding acoustic shields in front of the brass to protect players' hearing in a tight pit.", "Micing the brass as a block for a recording or a broadcast.", "Balancing a loud brass section against the strings during a rehearsal."]}, "a6fb6de6-d1fc-473e-9885-4bd3e5ad16a8": {"definition": "The cello section is the group of violoncellists in a string ensemble, one of the standard string subsections. Its players are seated together—commonly to the conductor's right in modern layouts, in front of or beside the double basses—and supply the tenor-to-bass range of the string choir, often carrying the bass line with the basses.", "plain_english": "The cello section is the group of cello players in an orchestra. Cellos are the large string instruments held between the knees. They cover the lower notes of the string sound. They often sit to the conductor's right, near the double basses.", "purpose_function": "Grouping the cellos gives a composer a unified tenor-bass string voice and lets the ensemble seat them together for blend, so they can play the bass line or inner harmonies as one section and lock in with the double basses.", "practical_application": "In laying out a pit or stage, a technician allows floor space and chair spacing for the cello section near the basses, and for close micing treats the cellos as one group aimed toward the audience or conductor.", "category": "Orchestral section", "related_terms": ["String section", "Double bass section", "Viola section", "First violins", "Chair layout", "Orchestra pit"], "common_mistakes": ["Confusing the cello section with the double basses; cellos are smaller, play higher, and are held between the knees, while the basses are taller and are played standing or on high stools.", "Assuming cellos always sit in one fixed spot; seating differs between orchestras and conductors, so the cello block may be to the right, center, or left.", "Forgetting cellos need more floor space than violins because the instrument rests on the floor on an endpin."], "scenario_contexts": ["Allocating chair and floor space for the cellos when planning a pit layout.", "Seating the cello section next to the double basses so the bass line locks together.", "Micing the cellos as a group for a recording session.", "Adjusting the cello position when a conductor prefers a different string seating."]}, "7eb8c52f-731a-4d70-9f60-f26ef055b1ba": {"definition": "Chair layout is the planned arrangement of the players' chairs, and usually their music stands, within a pit, on a stage, or on risers. It fixes each seat's position, spacing, and orientation so every musician can see the conductor, has room to play, and fits within the available floor area.", "plain_english": "Chair layout is the plan for where every player's chair and stand go. It sets how the seats are spaced and which way they face. A good layout lets each player see the conductor and have room to play. It also has to fit the space, which matters most in a small pit.", "purpose_function": "It fits a whole ensemble into a limited space while keeping clear sightlines to the conductor, enough room for bows and instruments, and safe paths in and out, so rehearsals and performances run smoothly.", "practical_application": "A technician draws or follows a chair layout to place chairs, stands, and stand lights before players arrive, checking spacing per player and leaving aisles for access and safe exit.", "category": "Stage layout", "related_terms": ["Orchestra pit", "Cello section", "Brass section", "Choir position", "Sightline", "Music stand"], "common_mistakes": ["Packing chairs too tightly to save space, so players cannot bow, blow, or see the conductor.", "Giving every player the same space; wind, brass, and percussion players usually need more room than string players.", "UNSAFE: Blocking aisles and exits with chairs, stands, and cases, which can trap players in an emergency; keep clear egress paths as required by fire and life-safety codes."], "scenario_contexts": ["Drawing a seating plan to fit an orchestra into a fixed pit.", "Spacing chairs and stands so every player can see the conductor.", "Leaving clear aisles so players can enter, exit, and evacuate safely.", "Adjusting the layout when a larger section or extra players are added."]}, "6559052b-ce37-420e-a1e3-102e548774d8": {"definition": "A choir is an organized group of singers who perform together, usually divided into sections by voice type—such as soprano, alto, tenor, and bass—to sing in harmony. The word is also used in orchestration for a family of like instruments, as in the 'brass choir' or 'string choir,' and for a division of organ pipes.", "plain_english": "A choir is a group of people who sing together. They are usually split into parts by voice, like high and low voices. Together those parts make harmony. The word can also describe a family of like instruments, such as the brass choir.", "purpose_function": "A choir combines many voices into balanced sections so a group can sing rich, multi-part harmony fuller and louder than any single singer, whether on its own or together with an orchestra.", "practical_application": "A technician setting up for a choir plans riser placement, spacing, and often area or overhead microphones, because a choir is a spread-out, blended sound source rather than a row of solo singers.", "category": "Vocal ensemble", "related_terms": ["Choir position", "Choir riser", "Chorus", "Vocal section", "Area microphone", "Conductor"], "common_mistakes": ["Confusing a choir with a small vocal group or a set of soloists; a choir has multiple singers per part who blend into sections.", "Micing a choir like solo singers with one mic each; choirs are usually captured with a few area or overhead mics that blend each section.", "Forgetting the word 'choir' can also mean an instrument family or a group of organ pipes, not only singers."], "scenario_contexts": ["Setting up risers and area microphones for a choir behind an orchestra.", "Balancing a choir against a full orchestra during a rehearsal.", "Placing a choir so every singer can see the conductor.", "Reading a score that calls for a brass choir rather than singers."]}, "907fe7e1-a458-407d-9942-155a764849e6": {"definition": "Choir position is the placement of a chorus within a performance layout, most often on raised risers or a dedicated choir terrace directly behind and above the orchestra. The location is chosen so the singers can see the conductor and so their sound projects forward over the instrumental sections to the audience.", "plain_english": "Choir position is where the singers stand or sit in the layout. A choir usually goes on risers behind and above the orchestra. The height lets their voices carry over the instruments to the audience. It also lets every singer see the conductor.", "purpose_function": "Raising and placing the choir behind the orchestra lets the voices clear the instruments and reach the audience, keeps the singers in the conductor's sightline, and helps balance a large group of voices against a full orchestra.", "practical_application": "A technician sets choir risers behind and above the orchestra, checks that the whole choir can see the conductor, and places area microphones to capture the raised, blended voices.", "category": "Stage layout", "related_terms": ["Choir", "Choir riser", "Orchestra pit", "Sightline", "Area microphone", "Acoustic shell"], "common_mistakes": ["Placing the choir in front of or level with the orchestra, so the instruments cover the voices.", "Raising the choir so high or so far back that singers lose a clear view of the conductor.", "Micing a raised choir from too far below; area mics should aim at the rows to capture the blended sound evenly."], "scenario_contexts": ["Setting choir risers behind an orchestra for a choral-orchestral work.", "Checking that every choir row has a clear sightline to the conductor.", "Positioning the choir so its sound projects over the orchestra to the hall.", "Placing area microphones to capture a raised choir evenly."]}, "240917f7-1e6e-4f26-808e-8cc13fe25abc": {"definition": "A choir riser (choral riser) is a portable, tiered stepped platform on which a choir or chorus stands in graduated rows so that each row is elevated above the one in front. The stepped tiers project the singers' sound toward the audience and give every chorister a clear line of sight to the conductor, and standard units accept a clamp-on back guard rail at the rear edge for fall protection.", "plain_english": "A choir riser is a set of low steps that a choir stands on to sing. Each row stands higher than the one in front. This lets the audience hear everyone. It also lets singers see the conductor. A rail can clip on the back edge so no one falls off.", "purpose_function": "It elevates each successive row of singers so their voices carry over the people in front and every chorister keeps a clear view of the conductor, while a rear guard rail protects singers on the raised back tiers from falling.", "practical_application": "Stage crew set out and level choir risers before a concert, arrange them straight or in a curve, lock the folding cross-braces, and fit the clamp-on back rail on the top tier before singers step up.", "category": "Ensemble staging", "related_terms": ["Choral terrace", "Conductor sightline", "Conductor podium", "Stage riser", "Guard rail"], "common_mistakes": ["UNSAFE: Using the raised back tiers without fitting the clamp-on back rail, leaving singers on an exposed edge with nothing to stop a backward fall.", "UNSAFE: Failing to lock the folding cross-braces, so the riser can shift or collapse under the weight of a full row.", "Overloading a riser past its rated capacity by packing rows too tightly.", "Confusing a portable choir riser with a fixed choral terrace built into the room's architecture."], "scenario_contexts": ["Staging a chorus behind the orchestra for a large choral work such as a requiem or Handel's Messiah.", "A touring choir bringing portable risers to a venue with no built-in tiered seating.", "A school concert where students stand on risers so parents can see and hear every row."]}, "63a67bd4-6d20-4141-a949-9301b82dd6c2": {"definition": "A choir riser (choral riser) is a portable, tiered stepped platform on which a choir or chorus stands in graduated rows so that each row is elevated above the one in front. The stepped tiers project the singers' sound toward the audience and give every chorister a clear line of sight to the conductor, and standard units accept a clamp-on back guard rail at the rear edge for fall protection.", "plain_english": "Choir risers are sets of low steps that a choir stands on to sing. Each row stands higher than the one in front. This lets the audience hear everyone. It also lets singers see the conductor. A rail can clip on the back edge so no one falls off.", "purpose_function": "They elevate each successive row of singers so their voices carry over the people in front and every chorister keeps a clear view of the conductor, while a rear guard rail protects singers on the raised back tiers from falling.", "practical_application": "Stage crew set out and level choir risers before a concert, arrange them straight or in a curve, lock the folding cross-braces, and fit the clamp-on back rail on the top tier before singers step up.", "category": "Ensemble staging", "related_terms": ["Choral terrace", "Conductor sightline", "Conductor podium", "Stage riser", "Guard rail"], "common_mistakes": ["UNSAFE: Using the raised back tiers without fitting the clamp-on back rail, leaving singers on an exposed edge with nothing to stop a backward fall.", "UNSAFE: Failing to lock the folding cross-braces, so the risers can shift or collapse under the weight of a full row.", "Overloading risers past their rated capacity by packing rows too tightly.", "Confusing portable choir risers with a fixed choral terrace built into the room's architecture."], "scenario_contexts": ["Staging a chorus behind the orchestra for a large choral work such as a requiem or Handel's Messiah.", "A touring choir bringing portable risers to a venue with no built-in tiered seating.", "A school concert where students stand on risers so parents can see and hear every row."]}, "30d7d57a-d761-479f-94bf-4dc0669511ca": {"definition": "A choral terrace is a permanent, raked block of stepped seating built into a concert hall or theatre behind or above the orchestra platform, on which a chorus stands or sits during choral works. Unlike portable choir risers it is part of the room's architecture, designed into the hall's sightlines and acoustics, and is often released as behind-orchestra audience seating for concerts that use no chorus.", "plain_english": "A choral terrace is a set of built-in stepped seats behind the stage. A choir stands there for big pieces that need singers. When no choir is needed, the audience can sit there instead. It is part of the building, not something you carry in.", "purpose_function": "It gives a chorus a fixed, elevated place behind the orchestra with good sightlines to the conductor and strong sound projection into the hall, and doubles as audience seating when no choir is performing.", "practical_application": "A hall's crew stages a large chorus on the choral terrace behind the players, while the box office may release those seats to the public for concerts that use no choir.", "category": "Ensemble staging", "related_terms": ["Choir riser", "Conductor sightline", "Conductor position", "Orchestra platform", "Concert hall acoustics"], "common_mistakes": ["Assuming a choral terrace is portable like choir risers; it is a fixed structure built into the hall.", "Forgetting the terrace sits behind or above the orchestra, so its balance and sightlines differ from front-stage seating.", "Releasing terrace seats to the audience without checking whether the programme needs the chorus there."], "scenario_contexts": ["Programming a symphony with chorus, where the singers occupy the terrace behind the orchestra.", "Selling the terrace as premium behind-orchestra seating for an orchestral-only concert.", "Placing the organ console and a choir together on the terrace for a sacred choral work."]}, "1306f121-da52-4fed-9060-f6c4595dff8a": {"definition": "A conductor camera is a video camera aimed at the conductor whose live image is relayed to monitors, so that performers who cannot see the podium directly — an offstage or backstage chorus, a separated banda, or pit players under an overhang — can follow the beat and stay synchronized. It is a core element of relay conducting used wherever direct sightlines to the conductor are broken.", "plain_english": "A conductor camera points at the conductor and sends a live video to screens. Performers who cannot see the conductor watch a screen instead. This keeps singers or players who are backstage or in the pit in time with the beat.", "purpose_function": "It captures the conductor's beat and gestures and feeds them to remote monitors, letting musicians and singers with no direct view of the podium stay in tempo with the main ensemble.", "practical_application": "AV crew mount a low-latency camera on the conductor and route its feed to monitors backstage, in the pit, and in dressing rooms so offstage forces can follow the beat.", "category": "Conductor communications", "related_terms": ["Conductor monitor", "Conductor position", "Conductor sightline", "Conductor talkback", "Latency"], "common_mistakes": ["Using a camera and video chain with visible latency, so the beat on the monitor lags the real gesture and performers drag.", "Framing the shot too tightly or too loosely, hiding the baton tip and hands that carry the beat.", "Assuming one camera position suits every performer, when offstage and pit players need clear, well-lit images."], "scenario_contexts": ["An opera with an offstage banda that must play in time with the pit orchestra.", "A large chorus placed behind the orchestra or in a gallery with no direct view of the conductor.", "A distributed recording or broadcast where musicians in separate rooms follow the same beat."]}, "c12ed523-4134-4c98-bf8a-3fcbeb7f9fd7": {"definition": "A conductor monitor is a video display that shows the live image of the conductor, fed from a conductor camera, to performers who lack a direct sightline to the podium — such as an offstage chorus, backstage instrumentalists, or pit players — so they can watch and follow the beat. It is the display end of a conductor-camera relay system.", "plain_english": "A conductor monitor is a screen that shows the conductor to performers. A camera pointed at the conductor feeds it. Singers or players who cannot see the podium watch this screen to stay in time.", "purpose_function": "It displays the conductor's beat to musicians and singers who cannot see the podium directly, giving them a reliable visual reference to stay synchronized with the main ensemble.", "practical_application": "Crew place conductor monitors where offstage or pit performers can read them clearly, checking brightness, angle, and that the feed matches the live beat with minimal delay.", "category": "Conductor communications", "related_terms": ["Conductor camera", "Conductor sightline", "Conductor talkback", "Conductor position", "Latency"], "common_mistakes": ["Placing the monitor where glare or a poor angle stops performers from reading the beat.", "Confusing a conductor monitor, which carries video of the beat, with an audio foldback speaker.", "Ignoring feed delay, so the image lags the conductor and the section drags."], "scenario_contexts": ["A backstage chorus watching a monitor to enter on cue with the pit orchestra.", "Pit musicians under a stage overhang using a monitor when the podium is hard to see.", "Offstage brass following a monitor to align a fanfare with the orchestra."]}, "d01b40a6-ba14-499d-9668-bc3b43aeeca9": {"definition": "A conductor's podium (rostrum) is the low raised platform on which a conductor stands to lead an ensemble, elevating them so players and singers can see the beat and gestures and so the conductor can see over the front desks. Purpose-built rostra provide a non-slip surface and, on taller or opera models, a handrail and an integral music stand and light.", "plain_english": "A conductor podium is a low platform the conductor stands on. Standing higher lets the whole group see the conductor's hands. It also lets the conductor see over the front players. Bigger ones have a rail and a non-slip top so the conductor does not slip or fall.", "purpose_function": "It raises the conductor above the players so the beat and gestures are visible to the whole ensemble, and gives the conductor a clear view over the front stands to the back of the group.", "practical_application": "Stage crew position and level the podium at the conductor's spot before rehearsal, check it is stable and non-slip, and fit the music stand, light, or handrail the conductor requires.", "category": "Conductor station", "related_terms": ["Conductor position", "Conductor sightline", "Conductor monitor", "Orchestra pit", "Music stand"], "common_mistakes": ["UNSAFE: Using a wobbly rostrum, or one without a non-slip surface, risking a fall while the conductor works with their back to the audience.", "Placing the podium too far back so the conductor cannot see the back desks or the stage action.", "Confusing the podium, which is the platform, with the conductor position, which is the location the conductor stands in."], "scenario_contexts": ["Setting the conductor's rostrum at the pit rail so they can see both the singers on stage and the pit players.", "Raising an opera rostrum so a conductor in a deep pit stays visible to performers on stage.", "Levelling a portable podium on a raked stage for an orchestral concert."]}, "b77da9df-654d-4764-85af-7a1ccae8ee62": {"definition": "The conductor position is the location from which the conductor leads — typically front-centre of a concert platform, or at the pit rail nearest the stage in an opera or musical — chosen so the whole ensemble can see the conductor and the conductor can see both the players and the stage action or soloists. In a pit it is set at the rail against the stage, usually on a rostrum, to bridge stage and pit.", "plain_english": "The conductor position is the exact spot where the conductor stands to lead. It is usually front and centre of the players. In a pit it sits right against the stage. From there the conductor can see the group and the stage at the same time.", "purpose_function": "It locates the conductor where two-way sightlines are best — the whole ensemble can see the beat, and the conductor can watch both the players and the singers or soloists on stage.", "practical_application": "When laying out a pit or platform, crew fix the conductor position first, at the stage rail on a rostrum, then arrange the players' desks and the podium's monitor and light around it.", "category": "Conductor station", "related_terms": ["Conductor podium", "Conductor sightline", "Orchestra pit", "Pit rail", "Conductor camera"], "common_mistakes": ["Placing the conductor position too deep in the pit, breaking sightlines to the stage and to singers.", "Confusing the conductor position, which is the location, with the podium, which is the platform placed there.", "Laying out player desks before fixing the conductor position, then finding sightlines are blocked."], "scenario_contexts": ["Setting the conductor at the pit rail for an opera so singers upstage can be led and cued.", "Placing the conductor front-centre of a concert platform for a symphony.", "Adjusting the position for a piano concerto when the soloist and lid sit between conductor and players."]}, "bea304b8-594e-4f1f-8e1f-9690e2f0e57e": {"definition": "A conductor sightline is an unobstructed line of sight between the conductor and a performer, in both directions, that lets the conductor's beat and cues be seen and lets the conductor read the players and the stage. Ensemble and pit layouts, podium height, and stand placement are all arranged to preserve these two-way sightlines, and a conductor camera and monitor are used where a direct sightline is impossible.", "plain_english": "A conductor sightline is a clear view between the conductor and a performer. Both must be able to see each other. If a wall, a stand, or the stage blocks the view, the beat gets missed. When no clear view is possible, a camera and a screen stand in for it.", "purpose_function": "It ensures the beat, entries, and cues pass reliably between conductor and performers by keeping their mutual view clear, which is the basic requirement for an ensemble to stay together.", "practical_application": "When planning a pit or stage layout, a technician checks sightlines from every desk to the podium, raises the podium or moves stands to clear blocked views, and adds a conductor camera where the line cannot be cleared.", "category": "Sightlines", "related_terms": ["Conductor position", "Conductor podium", "Conductor camera", "Conductor monitor", "Pit rail"], "common_mistakes": ["Checking only the conductor's view of the players and forgetting the players must also see the conductor.", "Assuming risers or a pit overhang will not block the line until players lose the beat during the show.", "Reaching for a conductor camera before first fixing a sightline that could simply be cleared."], "scenario_contexts": ["Positioning percussion at the back of a deep pit and checking they can still see the beat.", "Setting choir riser height so every row keeps a clear line to the podium.", "Deciding an offstage banda needs a conductor camera because no direct sightline exists."]}, "19dd7d1c-6135-4fe0-b15a-c2b199da89fa": {"definition": "Conductor talkback is a communications link, usually a microphone at the podium feeding a paging or intercom system, that lets the conductor speak to performers, control positions, or backstage staff — for example a backstage chorus, an offstage band, a recording control room, or the stage manager. It carries the conductor's voice where the conductor cannot be heard or seen directly, and is used chiefly in rehearsal and recording.", "plain_english": "Conductor talkback is a microphone and speaker link at the podium. It lets the conductor talk to people who are not in the room. That can be a backstage choir, an offstage band, or the recording booth. It is used mostly in rehearsals to give directions.", "purpose_function": "It gives the conductor a voice channel to remote performers and staff, so directions, counts, and stops can reach people who are offstage, in another room, or in the control room.", "practical_application": "In a recording session or complex staging, crew set a talkback mic at the podium and route it to headphones or speakers backstage and in the control room so the conductor can address everyone between takes.", "category": "Conductor communications", "related_terms": ["Conductor camera", "Conductor monitor", "Intercom", "Control room", "Cue light"], "common_mistakes": ["Leaving the talkback mic live during a take or performance, so the conductor's voice is captured or heard in the house.", "Confusing conductor talkback, which is voice communication, with the conductor monitor, which carries video of the beat.", "Routing talkback only to the control room and forgetting the offstage performers who also need it."], "scenario_contexts": ["A film-scoring or classical recording session where the conductor talks to the booth between takes.", "A staged work where the conductor cues a backstage chorus by voice as well as by camera.", "A rehearsal where the conductor stops and gives notes to offstage players over the paging system."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"2f8741ba-f27a-4e8a-b387-7d189ac5aa35": {"definition": "A conductor video system is a closed-circuit video installation in which one or more cameras trained on the conductor feed monitor screens placed where performers cannot see the pit directly, such as on stage, in the wings, in the chorus, or with an offstage band. It lets those musicians and singers follow the conductor's beat and cues in real time, keeping remote forces synchronized with the pit.", "plain_english": "A conductor video system is a set of cameras and screens in a theatre. A camera points at the conductor. Screens show the beat to singers and players who cannot see the pit. This keeps everyone in time together.", "purpose_function": "It exists to extend the conductor's beat and cues to performers who have no direct sightline to the pit, so singers on stage, choruses, and offstage players can stay locked to the same tempo.", "practical_application": "A technician mounts a camera facing the conductor's rostrum, runs the feed to monitors at the front of the stage and in the wings, and checks the picture is clear and low-latency before a run.", "category": "Pit monitoring & video", "related_terms": ["Cue monitor", "Conductor's rostrum", "Foldback monitor", "Orchestra pit", "Offstage band"], "common_mistakes": ["Assuming the conductor video system replaces the audio foldback feed; performers usually need both a clear video of the beat and a monitor mix of the music.", "Placing the conductor monitor where it is washed out by stage light or hidden from the singers, so the beat cannot actually be read from acting positions.", "Ignoring latency in the video chain; a delayed or laggy picture pushes remote performers behind the pit and drifts the ensemble out of time."], "scenario_contexts": ["Setting up a camera on the conductor and monitors on stage so singers can follow the beat in a large opera house.", "Feeding a conductor video monitor to an offstage brass band that must play in time with the pit.", "Adding wing monitors for a chorus that enters from a position with no view of the orchestra pit."]}, "e7268b77-120b-400b-893d-049ef6a6e66c": {"definition": "The conductor's rostrum (conductor's podium) is the raised platform on which the conductor stands to direct the ensemble, giving added height so the beat and gestures are visible to the players and, in the theatre, to singers on stage. In an orchestra pit it is placed at the front, typically against the pit rail facing the stage, positioning the conductor between the players and the performers they accompany.", "plain_english": "A conductor's rostrum is the raised platform the conductor stands on. It lifts them up so the players and singers can see their beat clearly. In a pit it sits at the front, near the low wall.", "purpose_function": "It raises the conductor above seated players so the beat, cues, and expressive gestures can be seen across the whole ensemble and, in a pit, by the performers on the stage above.", "practical_application": "Pit crew position and level the rostrum at the front of the pit, add a music stand and light, and confirm it is stable and clear of edges before the conductor takes it.", "category": "Pit layout & furniture", "related_terms": ["Conductor video system", "Orchestra pit", "Pit rail", "First violins", "Concertmaster"], "common_mistakes": ["Confusing the rostrum with the conductor's music stand; the rostrum is the platform stood on, while the stand holds the score.", "Assuming any raised box will do; the rostrum height and size must suit the sightlines to both the players and the stage, or some performers lose the beat.", "UNSAFE: Leaving a raised rostrum with unguarded edges near the pit rail or an open pit edge; raised standing platforms and pit perimeters are a fall hazard and must be guarded and kept clear per OSHA 29 CFR 1910 walking-working-surface and guarding requirements."], "scenario_contexts": ["Setting the conductor's rostrum at the front of the pit against the pit rail before a musical opens.", "Adjusting rostrum height so the conductor can see both the string players and the singers on stage.", "Adding a stand light and securing cables around the rostrum so the conductor has a safe, stable footing."]}, "028cbca3-5099-41b7-82c6-c511d5feeaa1": {"definition": "A cue monitor is a screen placed backstage, on stage, or in dressing and pit areas that displays a live camera feed—commonly of the conductor or the stage—so that performers and crew can take their entrances and cues when they cannot see the source directly. It is the display end of a closed-circuit relay used to coordinate people spread across a venue.", "plain_english": "A cue monitor is a small screen placed backstage or on stage. It shows a live camera view, often of the conductor or the stage. Performers and crew watch it to know when to come in.", "purpose_function": "It gives performers and crew a reliable visual reference for their cues when they have no direct line of sight to the conductor or stage, helping entrances and scene changes land on time.", "practical_application": "A technician places cue monitors in the wings, dressing rooms, and pit access, feeds them from the stage or conductor camera, and checks each screen shows a clear, current picture before the show.", "category": "Pit monitoring & video", "related_terms": ["Conductor video system", "Foldback monitor", "Prompt corner", "Orchestra pit", "Stage manager"], "common_mistakes": ["Treating the cue monitor as decoration and not checking it before curtain; a dark or frozen screen leaves performers with no cue.", "Feeding the wrong camera to a monitor, so a performer watches the stage when they needed the conductor's beat, or vice versa.", "Placing the monitor where glare or a bad angle makes it unreadable from the actual standing position."], "scenario_contexts": ["Watching a wing cue monitor for the conductor's downbeat before a sung entrance.", "Placing a cue monitor in a dressing room so performers can track the show and time their calls.", "Feeding a stage camera to a cue monitor at the pit access so late-entering players see the action."]}, "05371aa9-9b72-405d-97c7-c72710893867": {"definition": "The double-bass section is the group of double bass (contrabass) players in an orchestra or pit ensemble, the lowest-pitched member of the bowed string family, sounding an octave below the written notes. It supplies the bass foundation of the string body, frequently doubling the cellos an octave lower, and is usually seated together at one side or the rear of the strings.", "plain_english": "The double-bass section is the group of players on the biggest string instrument. Double basses play the lowest notes. They give the orchestra its deep bass, much like the low end in a song.", "purpose_function": "It anchors the harmony and rhythm of the ensemble with the lowest string tone, giving weight and depth beneath the cellos and the rest of the orchestra.", "practical_application": "In a pit the section is placed together where the large instruments fit and can be heard, and a technician may add discreet amplification or a monitor so the bass carries without crowding the pit.", "category": "String section", "related_terms": ["First violins", "Cello section", "Harp position", "Orchestra pit", "Concertmaster"], "common_mistakes": ["Assuming the double bass sounds at written pitch; it is a transposing-by-octave instrument that sounds an octave lower than notated.", "Confusing the orchestral double-bass section with the bass guitar or the tuba; the section refers specifically to the bowed contrabass players.", "Cramming the basses into a low pit corner where their large bodies are boxed in, so the low end is lost from the ensemble balance."], "scenario_contexts": ["Seating the double-bass section along the back or side of the strings in a concert layout.", "Fitting the double basses into a shallow orchestra pit where space for the large instruments is tight.", "Reinforcing the double-bass section with a monitor or gentle amplification so the bass line carries in a musical."]}, "869fb340-2d53-46c5-b0d6-c74c01b90ca3": {"definition": "The first violins (violin I) are the section of the orchestra's violinists that plays the upper, usually principal, melodic line of the string writing, distinct from the second violins who take a lower or inner part. The section is led by its principal, the concertmaster, and is conventionally seated at the front to the conductor's left, nearest the audience.", "plain_english": "The first violins are the top group of violin players. They usually play the main tune. Their leader sits closest to the conductor and is called the concertmaster.", "purpose_function": "It carries the highest and most prominent string line, giving the orchestra its leading melodic voice, with the concertmaster setting bowing and leading the whole string body.", "practical_application": "In a pit or on a concert platform the first violins are placed front-left near the conductor, and the concertmaster's desk is given a clear sightline and a stand light for tuning and leading.", "category": "String section", "related_terms": ["Concertmaster", "Double-bass section", "Harp position", "Conductor's rostrum", "Orchestra pit"], "common_mistakes": ["Thinking first violins play a harder or 'better' instrument than the seconds; both play the violin, and the split is by musical part, not by instrument.", "Confusing the concertmaster (leader of the first violins) with the conductor; the concertmaster leads the strings but does not conduct the ensemble.", "Assuming the seating is fixed; some conductors use antiphonal seating that splits first and second violins to opposite sides of the podium."], "scenario_contexts": ["Seating the first violins front-left of the conductor with the concertmaster at the leading desk.", "Fitting the first violins into a tight pit while keeping the concertmaster's sightline to the conductor clear.", "Discussing bowings and the leading melodic line with the first violins during a rehearsal."]}, "d8440b70-cf63-4f4c-ba89-33b39d3a8af6": {"definition": "A foldback monitor is a loudspeaker (or in-ear feed) that sends performers a dedicated mix of the program sound—'folding back' part of the audio toward the stage or pit—so they can hear themselves and other parts they would otherwise miss. In an orchestra pit it feeds players a balance of the singers, click, or other sections needed to stay together with the stage.", "plain_english": "A foldback monitor is a speaker aimed back at the performers. It sends them a mix of the sound so they can hear themselves and others. This helps them stay in tune and in time.", "purpose_function": "It exists to give performers their own hearing mix on stage or in the pit, since the audience-facing loudspeakers and the room do not deliver a usable balance back to where they play.", "practical_application": "A sound technician sets up foldback speakers or in-ears for the pit and stage, builds each monitor mix, and rings out the system to hold gain below feedback while keeping levels safe for hearing.", "category": "Pit monitoring & video", "related_terms": ["Cue monitor", "Conductor video system", "Orchestra pit", "In-ear monitor", "Foldback"], "common_mistakes": ["Confusing foldback (the performers' own monitor mix) with the front-of-house mix the audience hears; they are separate feeds with different balances.", "Chasing 'more me' by pushing every foldback send up, which drives the whole stage louder and closer to feedback.", "UNSAFE: Running foldback or in-ear monitors at excessive levels for long sessions; sustained high sound pressure causes noise-induced hearing loss, so keep exposure within OSHA 29 CFR 1910.95 limits and use hearing protection or level limiting."], "scenario_contexts": ["Feeding a foldback monitor to pit players so they can hear the singers over the pit's own volume.", "Sending a click or cue track to foldback or in-ears so the band locks to timecode.", "Ringing out a foldback wedge to raise gain-before-feedback before a musical's first preview."]}, "7ce54f24-95a5-4354-8e53-bd0d455f337b": {"definition": "A guitar station is the dedicated pit or backstage position set up for a guitarist, gathering the instruments and the gear needed to play and route them—commonly a stand for several guitars, an amplifier or amp modeler, a direct (DI) box, a music stand and light, and a monitor. In a musical-theatre pit it lets one player switch quickly between instruments while feeding a clean signal to the sound system.", "plain_english": "A guitar station is the guitar player's spot in the pit. It holds their guitars, an amp, a music stand, and a monitor. It also holds a direct box, also called a DI box. This small box sends the guitar signal cleanly to the mixer. Everything the player needs sits in one place.", "purpose_function": "It organizes one player's instruments and signal gear in a compact spot so fast instrument changes, tuning, and a clean feed to the mixer all happen without disrupting the crowded pit.", "practical_application": "A technician lays out the guitar station with a guitar stand, DI or amp feed, monitor, and stand light, then labels and dresses the cables so the player can swap instruments mid-show safely.", "category": "Pit layout & furniture", "related_terms": ["Foldback monitor", "Orchestra pit", "Direct box", "Double-bass section", "Cue monitor"], "common_mistakes": ["Leaving cables loose around the guitar station in a dark pit, creating a trip hazard during fast instrument changes.", "Sending the guitar through a loud stage amp in a tight pit instead of a DI or modeler, spilling into other mics and unbalancing the pit.", "Not providing a stand light or monitor at the station, so the player cannot read the part or hear their cue."], "scenario_contexts": ["Building a guitar station in a musical-theatre pit for a player doubling on electric, acoustic, and mandolin.", "Routing a guitar station through a DI to the mixer to keep pit stage volume under control.", "Adding a foldback monitor and stand light to a guitar station before technical rehearsals."]}, "64da3efe-8871-4bc0-8f5d-4212cea29408": {"definition": "The harp position is the placement of the harp (or harps) within the orchestral or pit seating plan. Because the harp is large, physically awkward, and relatively quiet, it is conventionally placed toward the front or side of the ensemble—often near the first violins or at the left edge—where it has room, can project, and the player retains a clear sightline to the conductor.", "plain_english": "The harp position is where the harp sits in the orchestra. The harp is large and fairly quiet. It is usually placed at the front or side so it can be heard and has enough room.", "purpose_function": "It sets the harp where its soft sound can carry and its bulky frame fits, while keeping the player able to see the conductor, so the instrument is both audible and coordinated with the ensemble.", "practical_application": "When planning a pit or platform, staff allot the harp a spot with floor space and a sightline to the conductor, and may add a small riser or monitor so the quiet instrument is heard.", "category": "Instrument placement", "related_terms": ["First violins", "Double-bass section", "Orchestra pit", "Conductor's rostrum", "Concertmaster"], "common_mistakes": ["Tucking the harp deep in a back corner where its quiet tone is lost and the player cannot see the conductor.", "Underestimating the floor space and access a harp needs, so it blocks a walkway or another player in a tight pit.", "Assuming a fixed spot for the harp; its placement varies with the piece and hall, and it is often moved for balance."], "scenario_contexts": ["Allotting the harp a front-side position with a clear view of the conductor in a concert seating plan.", "Finding floor space and a load-in path for a harp in a shallow, crowded orchestra pit.", "Adding a low riser or monitor at the harp position so its quiet sound carries into the balance."]}, "4b841b54-aea6-4c63-90a2-ad765ce568fb": {"definition": "A raised platform section within an orchestra pit or on stage that seats the horn players above the general playing level. It lifts the horns so their sound projects clear of the musicians seated in front; for the French horn, whose bell faces to the rear, the elevation helps the tone radiate over the players behind while keeping the section in the conductor's sightline.", "plain_english": "A raised platform that the horn players sit on. Lifting them up helps their sound carry over the players in front. It also keeps them in clear view of the conductor.", "purpose_function": "It elevates the horn players so their tone clears the musicians in front and projects into the house, and so the section keeps a clear sightline to the conductor.", "practical_application": "A pit crew sets and levels the horn riser during load-in, confirms it is stable and within its load rating, and runs any cabling and stand lighting to it before the players take their seats.", "category": "Pit Staging", "related_terms": ["Horn section", "Keyboard riser", "Pit riser", "Sightline", "Music stand layout", "Conductor monitor"], "common_mistakes": ["Assuming any riser height will do; too low fails to clear the players in front, while too high can break the section's sightline to the conductor.", "Confusing the horn riser for the general pit floor level when planning spacing and clearances.", "UNSAFE: Loading or standing on a riser without checking its rated capacity, level footing and edge guarding, risking a collapse or a fall."], "scenario_contexts": ["Placing French horns on a riser in a deep pit so their sound projects over the strings in front.", "Setting a brass horn section on a riser in a musical-theatre pit for balance and sightlines.", "Adjusting riser height during a tech rehearsal to fix a blocked view of the conductor."]}, "3efdfbe2-cf3a-43bc-b86b-fabd6d1f473f": {"definition": "The group of horn players in an ensemble treated as a single unit for seating, blend and balance. In the symphony orchestra it is specifically the French horns, positioned within the brass; in popular, jazz and musical-theatre ensembles the term usually covers the combined brass and (often) saxophone players who function as one block.", "plain_english": "The group of horn players who sit and play together as one team. In a classical orchestra it means the French horns. In pop or theatre bands it usually means the brass and saxophone players.", "purpose_function": "Grouping the horns together helps them lock in tuning, blend and phrasing, and lets the conductor and mixer treat them as one balanced block.", "practical_application": "When laying out a pit, a technician seats the horn section together, allows room for bells, mutes and mute changes, and places shared monitors or microphones for the group.", "category": "Ensemble Layout", "related_terms": ["Horn riser", "Brass section", "Instrument doubling area", "Music stand layout", "Section seating", "Keyboard position"], "common_mistakes": ["Assuming 'horns' always means the whole brass; in orchestral scores 'horns' means the French horns specifically.", "Splitting the section across the pit, which harms blend and makes tuning and balance harder.", "Forgetting to leave clearance for horn bells, mutes and mute changes when spacing the seats."], "scenario_contexts": ["Seating four French horns together in an opera pit within the brass group.", "Placing a trumpet, trombone and saxophone horn section on a shared riser in a musical.", "Miking the horn section as one group for a live-recorded show."]}, "118f3a3d-e02a-4e6a-90df-f5bb9dbbac9d": {"definition": "The floor space allotted to a doubling player - one who plays more than one instrument in a show - so the extra instruments can be stood, laid out and switched between quickly and safely during the performance. It is common at reed and keyboard chairs, where one player may cover flute, clarinet, saxophone or several keyboards within a single number.", "plain_english": "Extra space set aside for a player who plays several instruments in one show. It lets them keep spare instruments close and swap between them fast, without knocking anything over.", "purpose_function": "It gives a doubling player room to place, reach and switch instruments quickly and safely, so the fast changes written in the score happen without delay or damage.", "practical_application": "When planning a tight pit, a technician adds extra width and instrument stands at reed chairs so a doubler can move between, say, flute and clarinet mid-number.", "category": "Ensemble Layout", "related_terms": ["Instrument parking", "Reed chair", "Music stand layout", "Keyboard station", "Woodwind doubling", "Pit layout"], "common_mistakes": ["Treating a doubling chair like a single-instrument chair, leaving no room for the spare instruments.", "Placing instrument stands where they block the player's exit or a shared aisle.", "UNSAFE: Crowding instrument stands into walkways or over cabling, creating a trip and fall hazard in a confined pit."], "scenario_contexts": ["Setting up a reed chair that must cover flute, clarinet and alto sax in one show.", "Adding a doubling area beside a keyboardist who also plays accordion.", "Reworking pit spacing so a doubler can reach a second instrument without standing up."]}, "8f96150b-8cd1-40fd-879f-97d4c9f6bf2f": {"definition": "A designated area, or set of stands and racks, where instruments not in current use are stored safely and within reach during a rehearsal or performance. It keeps spare and doubling instruments off the floor and out of walkways, yet ready to pick up on cue.", "plain_english": "A set spot where players keep instruments they are not using right now. It keeps them safe, off the floor and out of the way, but still easy to grab when needed.", "purpose_function": "It protects instruments from being knocked or stepped on and keeps aisles clear, while keeping each instrument within quick reach for its next entry.", "practical_application": "A stage technician supplies instrument stands and marks a parking spot so brass players and doublers can set instruments down safely between numbers.", "category": "Ensemble Layout", "related_terms": ["Instrument doubling area", "Music stand layout", "Pit layout", "Reed chair", "Instrument stand", "Keyboard station"], "common_mistakes": ["Laying instruments flat on the floor instead of on stands, where they get stepped on or kicked over.", "UNSAFE: Parking instruments or cases in aisles and exits, blocking the crew's escape route from the pit.", "Placing parking spots out of easy reach, forcing rushed, unsafe grabs during fast changes."], "scenario_contexts": ["Providing trombone and trumpet stands for a brass section between big numbers.", "Marking a parking zone for a doubler's spare clarinet and flute.", "Keeping a guitarist's second instrument on a stand within arm's reach."]}, "be8286c5-9d12-4d39-8930-4c86cb597671": {"definition": "The placement of a keyboard player - piano, synthesizer or electronic keyboard - within the pit or ensemble layout, chosen for sightline to the conductor, reach to nearby players, and space for the instrument, bench, pedals and cabling. In many pit orchestras the keyboard chair anchors the rhythm and is sometimes the position from which the show is conducted.", "plain_english": "Where the keyboard player sits in the pit or band. The spot is chosen so they can see the conductor, reach nearby players, and fit the keyboard, bench and cables.", "purpose_function": "A well-chosen keyboard position gives the player clear sightlines and enough space, and places a central instrument where it best supports the rest of the ensemble.", "practical_application": "A technician fixes the keyboard position early in load-in, since its size, power and cabling shape where every other player can sit.", "category": "Ensemble Layout", "related_terms": ["Keyboard riser", "Keyboard station", "Music stand layout", "Conductor monitor", "Sightline", "Pit layout"], "common_mistakes": ["Placing the keyboard where the player cannot see the conductor or a conductor monitor.", "Forgetting the space that a bench, pedals and cabling need, leaving the position too tight to play.", "UNSAFE: Running keyboard power and audio cables across walkways without covers, creating trip hazards."], "scenario_contexts": ["Deciding where the main keyboard sits in a musical-theatre pit.", "Positioning a keyboard so it can double as the conducting station in a small band.", "Moving the keyboard to keep the player in sightline of the conductor's monitor."]}, "96fda02c-4199-4026-8c8b-c8edb7376cd8": {"definition": "A raised platform that supports a keyboard player together with the instrument or stacked instruments, bench, pedals, and often the amplifier, monitor and cabling. It lifts the player for sightlines to the conductor and, in a crowded pit, defines and levels the keyboard's footprint.", "plain_english": "A raised platform built for the keyboard player and their gear. It lifts them up for a clear view and gives the keyboard a firm, level base.", "purpose_function": "It provides a stable, level base for the keyboard setup and raises the player for sightlines to the conductor and for reach to nearby musicians.", "practical_application": "A crew levels and secures the keyboard riser and routes power and audio to it before the keyboard, stand and monitor are placed on top.", "category": "Pit Staging", "related_terms": ["Keyboard position", "Keyboard station", "Horn riser", "Music stand layout", "Pit riser", "Sightline"], "common_mistakes": ["Building the riser too small for the bench, pedals and a second keyboard, leaving no safe footing.", "UNSAFE: Loading a riser above its rated capacity or leaving an open edge unguarded, risking a collapse or a fall.", "Failing to secure or lock the riser decks, so they shift or rock while the player works."], "scenario_contexts": ["Raising a keyboardist in a deep pit so they can see the conductor.", "Setting a level riser to carry two stacked keyboards and an amplifier.", "Adding a keyboard riser on stage for a visible band in a concert-style musical."]}, "2133f4a9-5152-4771-ab2c-fcce6b4e7e76": {"definition": "The complete work setup for one keyboard player: the keyboard or stacked keyboards and their stands, bench, pedals, music stand and stand light, monitor, and the power and audio connections serving them. It is the self-contained unit that is placed and cabled as one within the pit or ensemble layout.", "plain_english": "Everything one keyboard player needs, set up as one unit. That means the keyboards, stand, bench, pedals, music light, monitor and cables, all in one spot.", "purpose_function": "Treating the keyboard as a single station lets a crew plan its space, power and cabling as one block and set it up and strike it quickly.", "practical_application": "A technician wires and tests the whole keyboard station - keyboards, monitor, music light and power - as one unit before the show.", "category": "Ensemble Layout", "related_terms": ["Keyboard position", "Keyboard riser", "Music stand layout", "Instrument doubling area", "Conductor monitor", "Pit layout"], "common_mistakes": ["Planning only for the keyboard and forgetting the bench, pedals, monitor and cabling the station needs.", "Leaving the station's cabling untested until the player arrives, so faults surface during the show.", "UNSAFE: Overloading one outlet or daisy-chaining power strips at the station, risking overheating and fire."], "scenario_contexts": ["Building a two-tier keyboard station for a player covering piano and synth parts.", "Striking a keyboard station quickly during a shared venue's turnaround.", "Testing the whole station's power and audio during pit setup."]}, "f05af245-6f45-4671-ac11-aad415e42cbb": {"definition": "The planned arrangement of players' music stands and their stand lights across a pit or ensemble, set so every player can read the part, keep the conductor in view over or beside the stand, and still have room to play and to change instruments. It also governs stand height and angle so that stand-light spill does not reach the stage or the audience.", "plain_english": "How the players' music stands are arranged across the pit. Good layout lets each player read the music, see the conductor, and still have room to play.", "purpose_function": "It ensures every player can read the music and keep the conductor in view, while controlling stand-light spill and leaving room to play and to move.", "practical_application": "During setup a technician places and angles each stand and its light, checking sightlines to the conductor and that no light spills onto the stage.", "category": "Ensemble Layout", "related_terms": ["Music stand light", "Sightline", "Conductor monitor", "Keyboard position", "Horn section", "Instrument doubling area"], "common_mistakes": ["Setting stands too high, blocking a player's view of the conductor.", "Angling stand lights so they spill onto the stage or into the audience's eyes.", "Crowding stands so players cannot turn pages or reach a doubling instrument."], "scenario_contexts": ["Arranging stands in a shallow pit so every player can see the conductor.", "Adjusting stand-light angles to stop spill onto the stage.", "Laying out stands at a reed chair to leave room for doubling instruments."]}, "dc16f8c2-dcff-423b-b630-0e23fba8bb29": {"definition": "A small, remotely controlled signal lamp used to cue a musician or group of musicians silently. Operated from the stage manager's or conductor's position, it gives a visual standby-and-go cue - commonly light on for 'stand by' and off for 'go' - so offstage players or a pit ensemble start, stop, or synchronise a passage without an audible call.", "plain_english": "A cue light is a small lamp that tells musicians when to play. Someone switches it on to say 'get ready' and off to say 'go.' Players get their cue with no spoken words.", "purpose_function": "It delivers precise entrance and stop cues to players who cannot see the conductor or hear a verbal call, keeping silent, tightly timed coordination during a performance.", "practical_application": "A technician runs cue-light lines to offstage music positions and to the conductor, then the stage manager or conductor works the lamps from a cue-light box to trigger entrances.", "category": "Cue Systems", "related_terms": ["Cue monitor", "Conductor monitor", "Offstage musician position", "Pit communication", "Show relay"], "common_mistakes": ["Confusing the standby and go states - treating 'light on' as the go cue when it is the warning", "Assuming a cue light replaces the conductor; it only supplements the beat for players who cannot see it", "Running cue-light lines without testing before the show, so a dead lamp is discovered mid-cue"], "scenario_contexts": ["Cueing an offstage brass banda to enter on time in an opera", "Signalling a pit band to start a number when the conductor is not visible", "Giving a silent 'go' to musicians during a blackout"]}, "c26e678b-c162-43fd-b38d-50b04b91a91c": {"definition": "A dedicated access route and doorway by which musicians reach their playing position - the orchestra pit, a stage riser, or an offstage location - kept separate from audience and cast circulation and forming part of the venue's means of egress.", "plain_english": "A musician entrance is the doorway and path players use to reach their seats. It usually leads to the pit or stage. It is kept clear so players can get in and out safely.", "purpose_function": "It gives players a safe, direct way to and from their positions without crossing the stage or audience, and it doubles as an emergency exit route from the pit.", "practical_application": "Crews keep the musician entrance and its corridor clear of cases and cable, and confirm the pit has the required number of exits before the ensemble loads in.", "category": "Access & Circulation", "related_terms": ["Pit entrance", "Pit tunnel", "Pit crossover", "Offstage musician position", "Pit"], "common_mistakes": ["UNSAFE: Blocking the musician entrance or pit exit with cases, cable, or chairs, obstructing the means of egress", "Assuming one entrance is enough for a large pit when codes may require two remote exits", "Routing musicians across the stage or through the house because a dedicated entrance was not planned"], "scenario_contexts": ["Loading an orchestra into the pit before doors open", "Planning two remote pit exits to meet egress requirements", "Keeping the pit access corridor clear during a performance"]}, "8131b531-f88d-4510-b12c-6d9796c7d1d9": {"definition": "A playing location placed out of the audience's sight - in the wings, backstage, a gallery, or an adjacent room - where instrumentalists or singers perform effects such as an offstage banda, distant fanfares, or echo passages, usually coordinated with the conductor by cue light, monitor, or video.", "plain_english": "An offstage musician position is a hidden spot where players perform out of view. It creates far-off or echo sounds, like a trumpet call from behind the set. The players follow the conductor on a screen or by a cue light.", "purpose_function": "It lets a score's offstage or distant-sound effects be produced live while keeping the players hidden, and it needs cueing aids because those players cannot see the conductor directly.", "practical_application": "A technician sets up a conductor video feed, a foldback monitor, and cue lights at the offstage position so the players stay in time with the pit.", "category": "Ensemble Positions", "related_terms": ["Backstage band", "Onstage band", "Conductor monitor", "Musician cue light", "Show relay"], "common_mistakes": ["Placing offstage players with no conductor video or cue light, so they drift out of time", "Forgetting sound bleed - an offstage position too close to open mics is heard in the main mix at the wrong level", "Assuming 'offstage' means amplified; the effect is usually acoustic and depends on placement and distance"], "scenario_contexts": ["Positioning an offstage brass banda for an opera fanfare", "Placing a distant chorus in the wings for an echo effect", "Setting a conductor monitor for players hidden behind scenery"]}, "a624f688-a28c-4fc8-9b22-e423be53a71e": {"definition": "An instrumental ensemble positioned on the stage itself, in view of the audience and often part of the staging, as distinct from a hidden pit orchestra - common in musicals, cabaret, and concerts where the band is a visible element of the show.", "plain_english": "An onstage band is a group of players placed on the stage where the audience can see them. It is common in musicals and concerts. This differs from a pit orchestra, which is hidden below the front of the stage.", "purpose_function": "It makes the musicians a visible part of the performance and keeps sightlines to the band simple, while requiring stage space, monitoring, and mic plans that a hidden pit would not.", "practical_application": "A technician allocates stage risers, foldback monitors, and mic and DI lines for the band, and manages spill between the band and vocal microphones.", "category": "Ensemble Positions", "related_terms": ["Backstage band", "Pit band", "Bandstand", "Backline position", "Orchestra riser"], "common_mistakes": ["Confusing an onstage band with a pit band; the pit sits below and in front of the stage", "Underbudgeting stage monitors, so an onstage band cannot hear itself over the mains", "Ignoring mic spill from a loud onstage band into nearby vocal microphones"], "scenario_contexts": ["Placing a musical-theatre band visibly upstage on risers", "Setting monitors and DI lines for a concert band on stage", "Managing spill between an onstage horn section and vocal mics"]}, "8eef5e7a-f019-4b41-a4b0-cb324ad17090": {"definition": "A large instrumental ensemble organised into families - strings, woodwinds, brass, and percussion, with harp, keyboard, and others as scored - led by a conductor; the symphony orchestra is its standard form, typically seated with strings nearest the audience and the louder winds and percussion behind.", "plain_english": "An orchestra is a large group of instruments led by a conductor. It has four main families: strings, woodwinds, brass, and percussion. The strings usually sit at the front and the loud brass and drums sit at the back.", "purpose_function": "It brings many instruments together under one conductor to perform written music with a wide range of tone and volume, its grouped seating balancing the sections for the listener.", "practical_application": "Technicians plan chairs, stands, risers, lighting, and microphones around the orchestra's section layout and its total headcount.", "category": "Ensemble", "related_terms": ["Orchestra layout", "String section", "Brass section", "Woodwind section", "Percussion section", "Conductor position"], "common_mistakes": ["Assuming every orchestra is the same size; forces range from a small chamber group to a large symphonic one", "Confusing the orchestra (the ensemble) with the orchestra pit (the space it plays in)", "Treating section seating as fixed when conductors vary the plan"], "scenario_contexts": ["Planning stage or pit space for a full symphony orchestra", "Estimating chair and stand counts from the scored instrumentation", "Laying out microphones by orchestral section"]}, "39780347-dce5-4f7d-8b85-74bb22bdc2ea": {"definition": "A personal-monitoring distribution that feeds each pit or ensemble musician a headphone mix - commonly a click track, cue or musical-director talkback, and a blend of the performance - often via networked personal mixers so players can set their own balance in a loud or spread-out pit.", "plain_english": "An orchestra headphone system sends sound to each player's headphones. It usually carries a click track, cues, and a mix of the music. Many systems let each player set their own headphone balance.", "purpose_function": "It gives players a reliable click and cue feed and a personal balance where hearing across the ensemble is hard, keeping timing tight with the stage and any backing tracks.", "practical_application": "A technician distributes personal mixers or headphone amps to each seat, patches the click and cue sources, and sets safe listening levels for the players.", "category": "Monitor Systems", "related_terms": ["Personal mixer", "Aviom-style system", "Click track", "Foldback monitor", "Conductor talkback"], "common_mistakes": ["UNSAFE: Setting headphone levels too high across long shows, risking noise-induced hearing loss", "Feeding only a click with no music, leaving players unable to hear their own ensemble", "Assuming one shared mix suits everyone instead of using personal mixers"], "scenario_contexts": ["Distributing click and cues to a pit playing to backing tracks", "Giving each player a personal headphone mix via networked mixers", "Feeding the conductor's count-in to the ensemble by headphone"]}, "b6fd690b-eb18-48b5-a449-95f60d6fa32d": {"definition": "The planned seating arrangement of an orchestra's players and sections - the placement of strings, winds, brass, percussion, and soloists relative to the conductor - chosen for balance, ensemble sightlines, and the acoustics of the room; common plans include the 'American' seating and the antiphonal split-violin arrangement.", "plain_english": "Orchestra layout is how the players and sections are arranged. It sets where the strings, winds, brass, and drums sit around the conductor. A good layout helps the sections balance and hear each other.", "purpose_function": "It positions sections so they blend and stay together, gives players clear sightlines to the conductor, and shapes how the sound reaches the audience.", "practical_application": "A technician marks chair and stand positions, plans risers for rear sections, and places microphones to suit the chosen layout.", "category": "Ensemble Layout", "related_terms": ["Orchestra", "Chair layout", "Music stand layout", "Orchestra riser", "Conductor position", "String section"], "common_mistakes": ["Treating one seating plan as universal; conductors and repertoire change the layout", "Ignoring sightlines, so rear players cannot see the conductor's beat", "Placing loud brass or percussion where they cover the strings"], "scenario_contexts": ["Marking chair positions for a symphony on stage", "Choosing antiphonal (split) violins for a Classical program", "Adding risers so rear sections are seen and heard"]}, "8a0c54b5-a222-4ccc-9e21-39d3b5f08338": {"definition": "One of the preset elevations of an orchestra-pit lift, at which the platform is lowered to orchestra-playing depth below the stage to form the pit; it sits below stage level and below the raised 'house/seating' and 'stage' presets used to convert the platform into extra seating rows or a stage extension.", "plain_english": "Orchestra level is the low setting of a pit lift. At this height the platform drops below the stage to make the orchestra pit. Higher settings raise it to add seats or extend the stage.", "purpose_function": "It sets the lift to the depth where the orchestra plays below and in front of the stage - one of several stored positions that let the same platform serve as pit, added seating, or stage.", "practical_application": "An operator selects the orchestra-level preset to lower the pit platform for the musicians, checking the lift path and edge protection before moving it.", "category": "Stage Machinery", "related_terms": ["Pit lift", "Pit level", "Pit", "Pit rail", "Pit floor"], "common_mistakes": ["UNSAFE: Standing, or leaving people or gear, on or beside the platform while it travels between levels", "UNSAFE: Leaving the open pit edge unguarded by a rail or net when the platform is at orchestra level", "Confusing orchestra level with stage level; the platform sits well below the stage at orchestra level"], "scenario_contexts": ["Lowering the pit platform to orchestra level before the players enter", "Raising the lift from orchestra level to seating level to add rows", "Checking edge protection with the lift set at orchestra level"]}, "dcaef1cc-33fa-4e32-986d-015889220616": {"definition": "The distribution of stage-manager announcements, and usually a performance/show-relay feed, to the orchestra or pit over dedicated loudspeakers or the players' monitors, so musicians hear calls such as 'places' and can follow the stage action; it is normally one-way and page-only, with no talkback from the pit.", "plain_english": "Orchestra paging sends the stage manager's calls to the pit. Players hear notices like 'places' over a speaker or their monitors. It is one-way, so the pit cannot talk back on it.", "purpose_function": "It keeps the orchestra informed of calls and timing from the stage manager and often relays the on-stage sound to the pit, coordinating the ensemble with the rest of the production.", "practical_application": "A technician runs a paging speaker or monitor feed to the pit, sets its level so calls are clear but do not bleed into open microphones, and checks it during preshow.", "category": "Communication Systems", "related_terms": ["Show relay", "Stage relay", "Pit talkback", "Pit communication", "Conductor monitor"], "common_mistakes": ["Confusing one-way paging with two-way talkback; the pit usually cannot answer on the paging line", "Setting paging so loud it bleeds into pit microphones and into the mix", "Assuming paging carries the show relay; the performance feed may be a separate signal"], "scenario_contexts": ["Calling 'places' to the pit before the overture", "Relaying stage-manager cues to musicians during a scene change", "Feeding the on-stage performance to the pit's monitor speakers"]}, "8766de7b-0100-4323-a10e-c4816bfda10f": {"definition": "An orchestra riser is a raised, load-rated platform, or a modular platform section, on which a whole instrument section, or individual orchestral players, are seated or set up above the main stage floor. Elevating rear players improves their sightline to the conductor and lets their sound project over the musicians seated in front rather than being blocked by them.", "plain_english": "An orchestra riser is a low platform that lifts part of the band off the floor. Players at the back sit higher than players in front. This helps them see the conductor. It also lets their sound travel over the people ahead of them.", "purpose_function": "It raises rear or specific sections of the ensemble so they can see the conductor and be seen, and so their sound clears the players in front; it also organizes the stage into defined tiers.", "practical_application": "A stage technician positions, levels, and locks risers to the stage plot, checks each unit's rated load, and sets step heights so every row of players sits high enough for clear sightlines.", "category": "Staging platform", "related_terms": ["Orchestra risers", "Percussion riser", "Pit", "Choral riser", "Sightlines", "Stage platform"], "common_mistakes": ["Treating a riser's stated load as a per-point rating; concentrated loads such as a timpani or a heavy player cluster must stay within the platform's rated capacity.", "UNSAFE: Leaving raised riser edges, steps, and gaps unguarded; a player stepping off an elevated edge can fall, so edges must be protected and units locked together per the manufacturer's technical data.", "Assuming any concert needs risers; whether to raise a section depends on sightlines, projection, and the venue, not on habit."], "scenario_contexts": ["Setting up a stage so brass and percussion at the back are raised for sightlines and projection.", "Reading a stage plot that calls for risers behind the strings before a concert.", "Adjusting riser height so rear players can see the conductor over the musicians in front."]}, "993d11be-36ba-42e7-a37f-bf18a8082e07": {"definition": "Orchestra risers are the modular platform units, typically assembled in stepped tiers, used to elevate players or whole sections of an orchestra above the stage floor. Arranged low at the front and higher at the back, they give rear players a clear sightline to the conductor and let each section's sound project over those seated in front.", "plain_english": "Orchestra risers are a set of platforms that raise parts of the band to different heights. The back rows sit up higher than the front. This helps everyone see the conductor. It also helps the sound reach the room.", "purpose_function": "They divide the stage into raised tiers so every section can see the conductor and project sound clearly, and so the ensemble's layout stays organized and repeatable.", "practical_application": "Crews assemble, level, and lock riser units to a stage plan, verify load ratings and guarded edges, and reconfigure or roll them off between pieces or scene changes.", "category": "Staging platform", "related_terms": ["Orchestra riser", "Percussion riser", "Pit", "Choral riser", "Sightlines", "Stage platform"], "common_mistakes": ["Assuming risers can be stacked or spanned freely; each configuration must follow the manufacturer's technical limits for height, load, and bracing.", "UNSAFE: Rolling or moving occupied or unlocked risers; units must be locked together and edges guarded before players step onto them to prevent falls or collapse.", "Confusing seated orchestra risers with stepped choral risers; the two differ in deck size, step height, and rated load."], "scenario_contexts": ["Building a tiered stage layout with several riser units for a large ensemble.", "Storing and rolling modular risers on and off stage between acts.", "Specifying riser load ratings and step heights for a new concert hall."]}, "9b1c90f2-a87f-4fbc-80e4-b286cf366888": {"definition": "A percussion riser is a sturdy, load-rated platform placed at the rear of an ensemble to elevate the percussion section and its instruments. Because percussion instruments such as timpani, mallet instruments, and drums are heavy and spread out, the riser is sized and rated to carry that concentrated load while lifting the players and instruments into sightline and projection.", "plain_english": "A percussion riser is a strong platform for the drums and mallet instruments. It lifts them up so they can be seen and heard from the back. It must be built to hold heavy gear like timpani.", "purpose_function": "It raises the heavy, wide-spread percussion setup so it is visible and projects over the ensemble, and gives a stable, rated deck to support the instruments and players safely.", "practical_application": "A technician confirms the riser's rated load, positions and locks it at the rear, and lays out timpani, mallet instruments, and auxiliary percussion on it according to the stage plan.", "category": "Staging platform", "related_terms": ["Percussion section", "Orchestra riser", "Percussion station", "Pit", "Timpani", "Auxiliary percussion"], "common_mistakes": ["Assuming any riser can hold percussion; timpani, marimbas, and drums are heavy, so the deck and frame must be rated for the concentrated load.", "UNSAFE: Overloading a riser or leaving its edges and gaps unguarded; a rolling timpani or a player stepping off a raised edge can fall, so keep within the rated load and protect edges per the manufacturer's technical data.", "Confusing a percussion riser with a stepped choral riser; percussion risers are usually larger, sturdier decks sized for spread-out setups, not tiered seating."], "scenario_contexts": ["Positioning timpani and mallet instruments on a raised, load-rated deck at the rear of the orchestra.", "Rolling a percussion riser into place and locking its casters before a rehearsal.", "Checking a riser's rated load before moving heavy percussion onto it."]}, "f082381a-2ae2-4b1b-882e-2cca2465e0f5": {"definition": "The percussion section is the family of instruments, and the players who perform them, that produce sound by being struck, shaken, or scraped, including timpani, snare and bass drums, cymbals, tuned mallet instruments, and auxiliary percussion. In an orchestra it is normally placed at the rear, often on risers, and its players frequently cover several instruments within a single work.", "plain_english": "The percussion section is the group of players who hit, shake, or strike instruments. This includes drums, cymbals, timpani, and bells. They usually sit at the back of the group.", "purpose_function": "It supplies rhythm, accent, color, and tuned or untuned impact to the ensemble, and its rear placement and spread layout let one or more players cover a wide range of instruments.", "practical_application": "When planning a stage, a technician allocates rear space and risers for the section and provides room and access for players to move between instruments during a piece.", "category": "Ensemble section", "related_terms": ["Percussion riser", "Percussion station", "Timpani", "Orchestra riser", "Mallet instruments", "Auxiliary percussion"], "common_mistakes": ["Thinking percussion means only drums; the section also covers timpani, mallet instruments, cymbals, and many auxiliary instruments.", "Assuming timpani are just another percussion instrument played by anyone; timpani are usually a specialist role, often listed separately from the rest of the section.", "Placing the section without room to move; percussionists often play several instruments and need space for quick, quiet changes."], "scenario_contexts": ["Laying out timpani, snare, bass drum, cymbals, and mallets at the back of the orchestra.", "Reading a score to see how many percussionists a piece needs.", "Planning stage space so percussionists can move between their instruments."]}, "7907f50d-0fde-44c3-857e-fbe887e5ee27": {"definition": "A percussion station is the arranged cluster of instruments, stands, and accessories assigned to a single percussionist for a given work, laid out so that one player can reach and move between them efficiently. Multi-percussion parts are set up around such stations, with the number and contents of each station determined by the score and the players available.", "plain_english": "A percussion station is one player's own set of instruments laid out together. The player stands in the middle and reaches each one. It is planned so they can switch fast during a piece.", "purpose_function": "It groups one player's required instruments into a reachable, ordered setup so fast, accurate instrument changes are possible during performance.", "practical_application": "A percussionist and the stage crew map each station on a floor plan, then place instruments, trap tables, and stands so every change in the part can be made quickly and quietly.", "category": "Player setup", "related_terms": ["Percussion section", "Percussion riser", "Trap table", "Multi-percussion", "Timpani", "Mallet instruments"], "common_mistakes": ["Treating a station as a fixed, standard layout; each station is arranged per player and per piece for the fastest reach between instruments.", "Forgetting cable, trap-table, and music-stand space when planning a station, which crowds the player and slows instrument changes."], "scenario_contexts": ["Arranging one player's cluster of instruments for a multi-percussion part.", "Marking a floor plan for each percussionist's station before load-in.", "Setting up trap tables and stands around a single percussion station."]}, "3d330bd6-fee7-4583-ad5e-730aeb9463e5": {"definition": "A personal mixer is a performer-operated device, part of a personal monitor mixing system, that lets an individual musician build and control their own monitor or in-ear mix from the input channels or stems distributed to it, usually over a digital network. Each player adjusts the level, and often the pan and tone, of the available sources independently of the front-of-house and monitor engineers.", "plain_english": "A personal mixer is a small box each player uses to build their own headphone mix. They choose what to make louder or softer, like having their own volume knobs. Each person hears what they need without asking the sound crew.", "purpose_function": "It gives each performer direct control of their own monitor mix, taking many individual monitor requests off the engineer and letting players hear exactly what they need.", "practical_application": "On stage or in a pit, a musician selects channels on their personal mixer and sets levels for their in-ears or wedge, while the tech patches and labels the stems feeding each unit on the network.", "category": "Monitoring equipment", "related_terms": ["In-ear monitor", "Monitor mix", "Stage monitor", "Foldback", "Monitor engineer", "Personal monitoring system"], "common_mistakes": ["Thinking a personal mixer changes the main front-of-house sound; it only shapes that one performer's own monitor or in-ear mix.", "UNSAFE: Setting in-ear levels too loud on a personal mixer; sustained high levels risk hearing damage, so set levels conservatively and follow safe-listening exposure guidance.", "Confusing a personal mixer with a full monitor console; it controls only the channels the system sends to it, not every source."], "scenario_contexts": ["A pit musician dialing in their own in-ear mix before a musical.", "A drummer boosting the click and bass in their personal mix without affecting the house.", "A sound tech patching stems to each player's personal mixer on a networked monitor system."]}, "37d451d8-c12c-4e30-9fb1-73e3a6173d06": {"definition": "The pit, or orchestra pit, is the lowered performance area located immediately in front of and partly beneath the stage, where accompanying musicians perform for opera, ballet, and musical theatre. Recessing the players keeps them below the audience's sightline to the stage while still allowing the conductor to see the performers; many pits sit on a lift so the floor can be raised to stage or house level.", "plain_english": "The pit is a lowered space in front of the stage where the band plays. It keeps players low so the crowd can still see the show. The conductor can watch the singers and actors. The open edge can cause a fall, so it needs a rail or a cover.", "purpose_function": "It houses the accompanying musicians out of the audience's sightline to the stage while keeping the conductor and stage in view of each other; on a lift it can also convert between orchestra pit, extra stage, and extra seating.", "practical_application": "Technicians set the pit floor height on its lift, arrange players, stands, and lighting within the available area and depth, and fit edge protection such as a removable rail, net, or filler.", "category": "Performance space", "related_terms": ["Pit band", "Pit lift", "Pit ambient microphone", "Orchestra riser", "Conductor monitor", "Sightlines"], "common_mistakes": ["UNSAFE: Leaving the open pit edge unguarded; the drop from the stage or house floor into the pit is a fall hazard, so use a removable pit rail, a pit net, or a pit filler when musicians are not in place, per applicable building and workplace codes.", "UNSAFE: Operating a powered pit lift with people or gear near the moving edge; pit elevators can crush or drop loads, so clear and signal the area and follow the lift manufacturer's technical procedures.", "Assuming every pit is the same size; pit depth, area, and rail height vary by venue and code, which limits how many players fit.", "Thinking the pit exists only for sound isolation; its main job is to hide players from sightlines while keeping the conductor visible to the stage."], "scenario_contexts": ["Placing the orchestra in the pit for an opera or musical so they stay below the audience's sightline.", "Lowering a pit lift to set the floor for the orchestra, then raising it for a scene change.", "Fitting a removable rail or net along the pit edge to protect against falls.", "Measuring pit area and depth to see how many players and stands will fit."]}, "ad4643d5-63ea-48d8-add5-469992811570": {"definition": "A pit ambient microphone is a microphone, or pair of microphones, placed to capture the overall blended sound of an orchestra pit rather than any single instrument. Its signal is used to reinforce, fold back, monitor, or record the ensemble as a whole, for example feeding the pit sound to backstage and dressing-room monitors or to the archival or broadcast mix.", "plain_english": "A pit ambient microphone hangs in the pit to catch the whole band's sound at once. It picks up the blended mix, not just one player. Crews use it to send that sound to speakers or to backstage.", "purpose_function": "It provides a single blended pickup of the whole pit for foldback, monitoring, recording, or reinforcement, so the ensemble's overall sound can be sent where close mics cannot cover.", "practical_application": "A sound technician hangs or stands an ambient mic over the pit, sets its placement and level for an even blend, and routes it to backstage foldback, the recording feed, or the reinforcement mix.", "category": "Pit microphone", "related_terms": ["Pit", "Foldback", "Area microphone", "Sound reinforcement", "Pit band", "Ambient microphone"], "common_mistakes": ["Expecting an ambient pit mic to give a clean solo sound; it captures the whole blended pit, not one instrument.", "Placing the mic too close to one section, which unbalances the blend it is meant to capture.", "Confusing the ambient pit feed with the main reinforcement mix; it is often used for backstage foldback, monitoring, or recording, not as the primary house sound."], "scenario_contexts": ["Hanging a mic over the pit to capture the full ensemble for the reinforcement mix.", "Feeding the ambient pit sound to backstage monitors so performers can hear the band.", "Recording an archival mix of the pit using an ambient microphone."]}, "a0ec9700-1c4b-4fbc-8a25-cc660d99cdbe": {"definition": "A pit band is the instrumental ensemble, usually smaller and more mixed in makeup than a symphony orchestra, that performs from the orchestra pit (or an offstage or remote location) to accompany a musical-theatre production. In modern practice it is commonly close-miked and mixed into the show's sound-reinforcement system, and its players may rely on monitors and a conductor video feed.", "plain_english": "A pit band is the small group of players that plays for a stage musical. They sit in the pit and back up the singers on stage. It is smaller than a full symphony and is often mic'd up.", "purpose_function": "It provides the live musical accompaniment for a stage musical from the pit, sized and instrumented for the show and the space rather than for the concert repertoire.", "practical_application": "A sound crew mics and mixes each pit-band instrument into the reinforcement system and provides the players with monitors and, where sightlines are blocked, a video feed of the conductor.", "category": "Ensemble type", "related_terms": ["Pit", "Pit ambient microphone", "Personal mixer", "Conductor monitor", "Sound reinforcement", "Foldback"], "common_mistakes": ["Calling every pit ensemble an orchestra; a pit band is usually a smaller, mixed group for musical theatre, not a full symphony orchestra.", "Assuming the pit band is always acoustic; in musical theatre it is often close-miked and mixed into the reinforcement system.", "Forgetting the pit band needs monitors or a conductor video feed when players cannot all see the podium."], "scenario_contexts": ["A small ensemble playing from the pit to accompany a musical.", "Close-miking each pit-band instrument and mixing it into the house system.", "Giving the pit band a conductor video feed when sightlines to the podium are blocked."]}, "c6be861e-0e9f-4210-b2dd-401daccfa45a": {"definition": "The designated mounting location for a video camera serving the orchestra pit, most commonly the conductor camera aimed at the podium so a relay feed can be shown to onstage performers, backstage monitors, and remote players, or a stage-relay camera placed to show the stage action to a conductor sunk beneath the apron. The chosen position must give an unobstructed, low-latency view of its subject while staying clear of sightlines, players, and instruments.", "plain_english": "It is the spot where a video camera is placed for the pit. Often it points at the conductor. Screens then show the conductor to singers and backstage crew. The camera needs a clear view and must stay out of the way.", "purpose_function": "It fixes where a camera sits so the conductor and performers can see one another on monitors, even when the pit is sunk below the stage and out of direct line of sight.", "practical_application": "A technician mounts and aims the conductor camera at this position, then routes its feed to stage-lip and backstage monitors so singers can follow the beat.", "category": "Video relay", "related_terms": ["Conductor monitor", "Video relay", "Orchestra pit", "Sightlines", "Pit communication", "Conductor"], "common_mistakes": ["Placing the camera where a music stand, player, or lighting fixture blocks the conductor, so the relayed image is partly hidden from performers.", "Confusing the conductor camera, which sends the pit to performers, with a stage-relay camera, which sends the stage to the conductor; they face opposite ways and serve different viewers.", "Ignoring latency in the video chain, so the beat on the monitor lags the live gesture and singers drift from the orchestra."], "scenario_contexts": ["Setting a conductor camera in the pit so onstage singers can watch the beat on a stage-lip monitor.", "Adding a stage-relay camera position so a conductor sunk under the apron can see upstage action.", "Repositioning the pit camera during tech when a scenic piece blocks the original angle."]}, "b6deb5ef-b9a8-4917-a6ef-1078205fc413": {"definition": "The collective set of signalling and monitoring links between the orchestra pit and the rest of a production—typically production intercom (headset comms), the conductor video relay, cue lights, paging or program-audio feeds, and foldback—used to keep the pit coordinated with the stage manager, the stage, and the control positions. It exists because the pit is acoustically and visually separated from the performers and operators it must stay synchronized with.", "plain_english": "This is all the ways the pit stays in touch with the rest of the show. It includes headset intercom, cue lights, and video of the conductor. The pit is set apart from the stage, so these links keep everyone together.", "purpose_function": "It keeps the conductor and pit players coordinated with the stage manager, cast, and technicians, despite the pit being physically separated and often sunk below the stage.", "practical_application": "A technician plans and patches the pit's intercom, cue lights, and conductor-relay feeds so the stage manager can cue the conductor and the pit can hear program and click.", "category": "Pit communications", "related_terms": ["Production intercom", "Cue light", "Conductor monitor", "Pit communication station", "Pit foldback", "Stage manager"], "common_mistakes": ["Treating pit communication as only headset intercom; it also covers cue lights, conductor video, paging, and foldback feeds.", "Forgetting the conductor rarely wears a headset, so cue lights and video are the main links to the podium, not voice comms.", "Under-providing outlets, so the pit players and conductor cannot all be reached during fast cue sequences."], "scenario_contexts": ["Cueing the conductor to start an entr'acte using a pit cue light run from the prompt corner.", "Feeding vocal program and a click track into the pit so players can lock to the singers.", "Coordinating a scene-change downbeat between the stage manager and conductor over comms."]}, "613e7ad8-057c-4f94-80f7-a85d6bb7288e": {"definition": "A fixed intercom outlet and user station—typically a wall or panel-mounted speaker station, or a beltpack connection point—installed in the orchestra pit as part of the production intercom system, giving the conductor or pit personnel a talk-and-listen position on the comms network. It is the pit's physical access point to headset or speaker communication with the stage manager and other stations.", "plain_english": "This is an intercom point built into the pit. Someone in the pit plugs in a headset or uses a small speaker panel here. It lets them talk to and hear the stage manager and crew.", "purpose_function": "It gives the pit a dedicated place to join the intercom network, so pit staff can talk to and hear the rest of the production team.", "practical_application": "A technician installs and tests this station, connecting a beltpack or speaker station on the correct channel so the pit can reach the stage manager during the show.", "category": "Pit communications", "related_terms": ["Production intercom", "Pit communication", "Beltpack", "Cue light", "Conductor monitor", "Stage manager"], "common_mistakes": ["Assigning the pit station to the wrong intercom channel, so it cannot reach the stage manager during the show.", "Placing the station where a loud speaker-station announcement bleeds into open microphones in the pit.", "Providing only one station, leaving distant players or the conductor without a reachable position."], "scenario_contexts": ["Plugging a headset beltpack into the pit station to join the stage manager's cue channel.", "Using a panel speaker station in the pit for pre-show coordination without a headset.", "Testing the pit station's talk and listen during a comms check before a performance."]}, "2d401a2b-fa03-4b64-b23d-146fdb097430": {"definition": "A crossover is a concealed passage that lets performers and crew move between stage-left and stage-right without being seen by the audience; a pit crossover is such a route associated with the orchestra pit—commonly an understage passage running beneath the pit or forestage, or a means of crossing at the pit that links the two sides of the front of the stage. It preserves the illusion by keeping crossing traffic out of the audience's view.", "plain_english": "A crossover is a hidden path from one side of the stage to the other. A pit crossover is that path near or under the orchestra pit. People use it to cross unseen, so the audience never spots them.", "purpose_function": "It lets actors, musicians, and crew reach the far side without walking across the stage or through the house, keeping both the illusion and the traffic flow intact.", "practical_application": "A stage manager routes a quick costume-change cross through the understage pit crossover so an actor can enter from the opposite wing on time.", "category": "Pit circulation", "related_terms": ["Crossover", "Understage", "Orchestra pit", "Pit entrance", "Wings", "Forestage"], "common_mistakes": ["Assuming the only crossover is upstage; a pit or understage crossover may be the faster low route beneath the forestage.", "Blocking the crossover with stored scenery or cases, forcing crosses across the stage or through the house.", "UNSAFE: Running a crossover route past an open, lowered pit without guarding or lighting the edge; walking paths beside a fall hazard must be guarded and marked per OSHA and building-code guard requirements."], "scenario_contexts": ["Sending an actor from stage-right to stage-left through the understage pit crossover during a blackout.", "Moving a musician to a riser on the far side of the pit before a number.", "Planning crew traffic so the pit crossover stays clear during quick changes."]}, "ba0e27e6-584c-47d0-bf31-f3c70432b62d": {"definition": "The controlled access point or points through which musicians and staff enter and leave the orchestra pit—most often an understage door or corridor connecting the pit to backstage and dressing areas, and sometimes a door or steps from the auditorium. Because the pit is a sunken, enclosed workspace, its entrance also serves as a required means of egress for the people working in it.", "plain_english": "This is the way in and out of the orchestra pit. Usually it is a door or corridor from under the stage. It is also an escape route, so it must stay clear at all times.", "purpose_function": "It gives players and staff a safe, discreet route into the sunken pit, ideally out of the audience's view, and serves as their exit in an emergency.", "practical_application": "A technician keeps the pit entrance and its corridor unobstructed and lit, so musicians can enter before the house opens and evacuate quickly if needed.", "category": "Pit access", "related_terms": ["Orchestra pit", "Understage", "Pit crossover", "Means of egress", "Pit rail", "Backstage"], "common_mistakes": ["UNSAFE: Blocking or locking the pit entrance with cases, cabling, or stored gear; it is a required exit path and must stay clear and usable per OSHA means-of-egress and building-code egress rules.", "Routing musicians in through the house when an understage entrance exists, disturbing the audience and sightlines.", "Providing a single narrow entrance for a large pit, slowing both entry and emergency exit."], "scenario_contexts": ["Bringing the orchestra into the pit through the understage corridor before the house opens.", "Keeping the pit entrance clear as a marked exit throughout a performance.", "Carrying a large instrument such as a harp in through the pit entrance route."]}, "48db82aa-5957-4a0e-8c12-2e07da020d6b": {"definition": "A pit extension is any enlargement of the usable orchestra-pit area beyond its basic footprint—typically by extending the pit forward under the stage-apron overhang, by taking in space from the auditorium (removing front seating rows), or by adding pit-lift sections—so that a larger ensemble can be accommodated. The added area increases playing space but can also change headroom, the pit-to-stage balance, and sightlines.", "plain_english": "This means making the orchestra pit bigger. It can reach forward under the stage edge or take over the front seats. A bigger pit fits a larger group of musicians.", "purpose_function": "It creates room for a larger orchestra than the standard pit holds, letting a venue stage works that call for big instrumental forces.", "practical_application": "For a large-orchestra show, staff extend the pit—removing front seats or adding lift sections—and re-lay the pit floor, chairs, and lighting to seat the extra players.", "category": "Pit configuration", "related_terms": ["Orchestra pit", "Pit lift", "Pit floor", "Pit filler", "Apron", "Pit level"], "common_mistakes": ["Confusing a pit extension, which makes the pit larger for players, with a pit filler or forestage, which covers the pit to gain stage or seating.", "Extending the pit under the stage overhang and forgetting that the low headroom traps sound and cramps the players there.", "UNSAFE: Removing front-row seats into an open, lowered pit without installing proper edge guarding; an exposed pit edge in the seating area is a fall hazard that must be guarded per building-code guard and OSHA fall-protection rules."], "scenario_contexts": ["Removing two rows of front seats to extend the pit for a large romantic-era orchestra.", "Using the understage overhang as pit-extension space for percussion and harp.", "Reconfiguring pit-lift sections to enlarge the playing area for a bigger ensemble."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"80907a1c-db55-4087-b7df-89916681faf6": {"definition": "The pit floor is the walking and playing surface at the bottom of the orchestra pit, on which musicians, chairs, stands, and instruments are set; where the pit is on a lift, the pit floor is the top surface of the lift platform. Its material and construction—often wood over an air gap or resilient framing—affect both player comfort and the acoustic reflection and support of low-frequency instruments.", "plain_english": "This is the floor at the bottom of the orchestra pit. Musicians, chairs, and stands sit on it. How it is built changes how the sound bounces and how the pit feels to play in.", "purpose_function": "It provides a level, stable, and acoustically suitable surface for the seated orchestra; on a lift it is also the moving deck that sets the pit's height.", "practical_application": "A technician checks the pit floor is level, sound, and clear before load-in, then lays cable and marks chair positions on it for the ensemble.", "category": "Pit structure", "related_terms": ["Orchestra pit", "Pit lift", "Pit level", "Pit rail", "Pit extension", "Riser"], "common_mistakes": ["Assuming the pit floor is fixed structure when it is often a lift deck that can move; loading it beyond the lift's rating can be unsafe.", "Ignoring the floor's acoustic role, then wondering why the low strings and brass sound weak or boomy.", "UNSAFE: Standing on or loading a pit-lift floor near an unguarded edge while it is lowered; the gap between the deck and surrounding structure is a fall and entrapment hazard controlled by guarding and lift-safety practice per OSHA and manufacturer lift documentation."], "scenario_contexts": ["Leveling and clearing the pit floor before the orchestra loads in.", "Taping chair and stand positions on the pit floor from the seating plan.", "Checking the pit-lift floor's load rating before placing a piano and percussion."]}, "a2d97d53-7a35-47b4-a7cf-0dba18aaf2ca": {"definition": "Pit foldback is the monitor audio fed to the orchestra pit—program elements the players and conductor need to hear, such as onstage vocals, a click track, cue tracks, or other sections—delivered over pit monitor loudspeakers or in-ear systems. It exists because pit players often cannot hear the singers or a click acoustically over their own instruments and the room.", "plain_english": "Foldback is sound sent back to performers so they can hear what they need. Pit foldback feeds the musicians things like the singers or a click track. Without it, players cannot hear the singers over their own instruments.", "purpose_function": "It lets pit musicians and the conductor stay locked with the singers and any click or backing track, by feeding those sources into the pit at a usable level.", "practical_application": "A sound technician sets up pit foldback—small monitors or in-ears carrying vocals and click—and rings out levels so players hear the cast without feedback into the pit mics.", "category": "Pit monitoring", "related_terms": ["Foldback", "Stage monitor", "Click track", "Pit communication", "In-ear monitor", "Conductor monitor"], "common_mistakes": ["Confusing pit foldback, which feeds sound to the players, with front-of-house, which feeds the audience; they are separate mixes with different content.", "Running pit foldback so loud it spills into the pit microphones and the house, causing feedback or muddy sound.", "UNSAFE: Setting pit monitor or in-ear levels dangerously high to beat instrument bleed; sustained loud monitoring risks hearing damage and should follow safe exposure limits per OSHA and NIOSH hearing-conservation guidance."], "scenario_contexts": ["Feeding lead-vocal mics into pit monitors so the band can follow the singer.", "Sending a click track to pit in-ears to keep a number tight with automation.", "Adding a section-fill monitor so distant players can hear the woodwinds."]}, "48fd6a38-0195-402b-a241-97a69bec6c29": {"definition": "Pit level is the elevation of the orchestra-pit floor relative to the stage and the auditorium; on a pit lift it names one of the platform's preset stopping positions—typically a lowered 'pit' (playing) level below both stage and front-row seating, as opposed to stage level or seating level, to which the lift can raise the floor. The chosen pit level sets sightlines to the conductor, the acoustic coupling of pit to house, and the depth at which the players sit.", "plain_english": "Pit level is how high or low the pit floor sits. A pit lift can stop at set heights. The low pit position drops the players below the stage. Higher positions match the stage or the front seats.", "purpose_function": "It defines the height the pit floor is set to, which controls how much of the orchestra the audience sees, how the sound blends into the room, and how the conductor lines up with the stage.", "practical_application": "An operator raises or lowers the pit lift to the called pit level for each configuration, confirming the floor is locked and level before players or scenery go on it.", "category": "Pit configuration", "related_terms": ["Pit lift", "Pit floor", "Pit rail", "Pit extension", "Forestage", "Sightlines"], "common_mistakes": ["Confusing pit level, meaning the pit floor's height, with sound level or loudness; here 'level' means elevation, not volume.", "Setting the pit too low or too high for the show, hurting the conductor's sightlines or the balance between pit and stage.", "UNSAFE: Moving or leaving a pit lift between levels with people or an unguarded edge exposed; pit-lift moves and any open pit edge must be guarded, interlocked, and controlled per OSHA fall protection, building-code guarding, and manufacturer lift-safety documentation."], "scenario_contexts": ["Lowering the pit lift to playing level and locking it before the orchestra takes their seats.", "Raising the pit to stage level to form a forestage for a play.", "Raising the pit to seating level to add front rows for a full-house event."]}, "b9c8fbc1-5b72-4e7d-9904-4f7dbcec8c13": {"definition": "A powered platform filling all or part of the orchestra pit opening that raises and lowers the pit floor to preset heights—typically house/seating level, stage level, and a lowered playing or loading level—so the same space can serve as extra seating rows, a forestage or thrust, a sunken orchestra pit, or a get-in for heavy equipment. It is stage machinery whose travel, edge guarding, load rating, and controls are governed by building codes and rigging and lift safety practice.", "plain_english": "A pit lift is a large powered platform under the orchestra pit. It moves the pit floor up and down. Set high, it adds seats or stage. Set low, it becomes the pit. Its open edges can drop several feet, so guarding matters.", "purpose_function": "It lets one space switch role between audience seating, forestage, and orchestra pit, so a venue can reconfigure the front of house quickly for different productions without rebuilding.", "practical_application": "A technician operates or spots the lift as it carries the pit to playing level, keeping people, instruments, and cables clear of the edges and shear points during travel.", "category": "Stage machinery", "related_terms": ["Orchestra pit", "Pit floor", "Pit level", "Pit extension", "Orchestra level", "Pit crossover"], "common_mistakes": ["UNSAFE: Standing or working at the open edge of a raised or moving lift without edge guarding or fall protection, where a fall to the pit floor below can cause serious injury.", "UNSAFE: Leaving people, instruments, or cables in the gap between the moving platform and the fixed floor, creating a crush or shear hazard as the lift travels.", "Overloading the platform beyond its rated capacity or loading it unevenly, ignoring the manufacturer's stated limits.", "Assuming the lift only makes an orchestra pit; it also forms extra seating rows, a forestage, or a loading level at other heights."], "scenario_contexts": ["Raising the pit to stage level to form a forestage or thrust for a play that needs no orchestra.", "Lowering the pit to playing level before a musical so the orchestra sits below the audience sightline.", "Setting the pit to house level to add rows of audience seats for a sold-out event.", "Dropping the lift to stage-floor or basement level to load a piano or heavy gear into the pit."]}, "78052ab0-ce04-4174-bfd2-93e92e5ee67e": {"definition": "A loudspeaker installed in or serving the orchestra pit, used to deliver foldback to the musicians and conductor—program (vocal) audio, click track, cues, or backing tracks—or to reproduce sound effects and pre-recorded music from the pit position. It is selected and placed to give even coverage in the confined, reflective pit while minimising spill into open pit microphones and onto the stage.", "plain_english": "This is a speaker placed in the orchestra pit. It feeds sound to the players and conductor. That can be the singers' voices, a click, or cues. It must be clear for them without leaking into the pit mics.", "purpose_function": "It gives pit musicians the reference audio they need—voices, click, and cues—so they can stay locked with the singers on stage even though the pit is a separate, enclosed space.", "practical_application": "A technician mounts and aims pit loudspeakers for each player group, then sets their level so the foldback is clear without bleeding into nearby microphones.", "category": "Pit monitoring", "related_terms": ["Pit monitor", "Pit foldback", "Pit monitor system", "Pit microphone", "Foldback monitor", "Personal monitor"], "common_mistakes": ["Running the pit loudspeaker so loud that it bleeds into open pit microphones, causing a muddy mix or feedback.", "Aiming one speaker at the whole pit instead of covering each player group, so some musicians cannot hear the foldback.", "UNSAFE: Setting sustained foldback levels high enough to risk musicians' hearing over a long run, rather than managing exposure to recognised noise limits."], "scenario_contexts": ["Feeding a click track and vocal program into the pit so the band locks to the singers.", "Playing a pre-recorded overture or effect from a pit loudspeaker during a scene.", "Adding a small foldback speaker for a percussionist who cannot hear the vocals."]}, "296f2ff4-5916-42c9-9346-84814287a3cc": {"definition": "A microphone used to capture instruments in the orchestra pit for sound reinforcement, broadcast, or recording—ranging from close mics on individual instruments or sections to overhead or area mics that pick up a group. Selection and placement balance adequate gain-before-feedback and separation against natural tone in an enclosed, densely packed space.", "plain_english": "This is a microphone that picks up the instruments in the pit. Some sit close to one instrument. Others hang above a group. The goal is a clear, natural sound without feedback in the tight pit.", "purpose_function": "It turns pit instrument sound into a signal so the mix engineer can reinforce, broadcast, or record the orchestra, which is often too quiet or too enclosed to reach the audience unaided.", "practical_application": "A technician selects, rigs, and cables pit microphones—close mics, section mics, or overheads—then checks each channel for level, tone, and spill before the show.", "category": "Pit microphone", "related_terms": ["Pit ambient microphone", "Pit microphone position", "Pit microphone system", "Pit mixer", "Orchestra pit", "Pit loudspeaker"], "common_mistakes": ["Using too many close mics in the pit, so spill between channels muddies the mix and invites feedback.", "Confusing a pit microphone with a pit loudspeaker; one captures sound, the other plays it back.", "Ignoring the reflective pit surfaces, so mics pick up harsh reflections instead of clean instrument tone."], "scenario_contexts": ["Close-miking a harp or celesta in the pit so it can be heard over the full ensemble.", "Hanging overhead microphones above the string section for a broadcast feed.", "Adding a microphone to a quiet instrument the audience cannot hear from the sunken pit."]}, "b53da82b-c85c-45c6-92e8-3ebed70943a0": {"definition": "The specific placement—location, height, distance, and angle—chosen for a microphone in the orchestra pit relative to its target instrument or section, balancing pickup and tone against spill from neighbours, feedback risk, and the constraints of a crowded, low-ceilinged space. Positions must also clear players' movements, music stands, sightlines, and pit access.", "plain_english": "This is exactly where a pit mic is placed. It covers how close, how high, and at what angle. A good position captures one instrument well. It also avoids picking up neighbours or blocking the players.", "purpose_function": "It sets how much of the intended instrument, versus spill and room reflections, a microphone captures, which drives the quality and separation of the pit sound.", "practical_application": "A technician fine-tunes each microphone's position during setup and tech, moving it for better tone and less spill while keeping it clear of players and stands.", "category": "Pit microphone", "related_terms": ["Pit microphone", "Pit microphone system", "Pit ambient microphone", "Pit mixer", "Sightlines", "Orchestra pit"], "common_mistakes": ["Placing a mic too far from its instrument, so it picks up more spill and room than the intended sound.", "Setting a stand where it blocks a player's bowing, a sightline to the conductor, or the pit walkway.", "Forgetting that a moved instrument or shared stand shifts the effective position between rehearsals."], "scenario_contexts": ["Lowering a mic closer to the woodwinds to reduce brass spill in the same area.", "Repositioning a boom during tech because it fouls a player's music stand.", "Choosing a height for an overhead that clears the pit net yet still covers the section."]}, "f09b1a61-442b-4822-b50c-3901f6b46e0b": {"definition": "The complete, coordinated set of microphones, mounts, stands, cabling, splits, and any preamps or processing used to capture the orchestra pit—planned as a whole so channel count, placement, and routing suit the production's reinforcement, broadcast, and recording needs. It is designed around the pit's size, instrumentation, and access limits.", "plain_english": "This is the whole kit for miking the pit. It includes the microphones, their stands, and all the cabling and inputs. It is planned together so every instrument that needs a mic gets one.", "purpose_function": "It gives an organised, repeatable way to capture every required pit source, so the mix engineer has the channels and routing needed for the show, run after run.", "practical_application": "A technician plans, patches, and labels the pit microphone system from an input list, then verifies every channel reaches the console correctly before rehearsals.", "category": "Pit microphone", "related_terms": ["Pit microphone", "Pit microphone position", "Pit ambient microphone", "Pit mixer", "Orchestra pit", "Pit monitor system"], "common_mistakes": ["Running out of input channels because the system was not planned around the full instrument list.", "Mislabelling or misrouting pit channels, so the wrong instrument appears on a fader at the console.", "Ignoring cable management, leaving trip hazards and strain on connectors in the crowded pit."], "scenario_contexts": ["Building an input list and patch for a 20-piece pit before load-in.", "Splitting the pit microphone system to feed both a front-of-house console and a broadcast truck.", "Reusing a documented pit system to reset the same show quickly on tour."]}, "15a67372-227e-4e55-a429-094223ea49fe": {"definition": "A mixing device dedicated to the orchestra pit—either a submixer placed in or near the pit that combines and balances pit sources before sending a reduced group of feeds to the main console, or a personal/monitor mixer that lets a player set their own foldback blend. It cuts the channel count to the main system and puts pit-specific control where it is needed.", "plain_english": "This is a mixer used just for the pit. It blends the pit's mics or feeds. Sometimes it sends a tidy group of signals to the big console. Sometimes it lets a player set their own headphone mix.", "purpose_function": "It groups or personalises pit audio close to the source, so the main console handles fewer channels and pit players can control the foldback that matters to them.", "practical_application": "A technician sets up a pit submixer or personal mixers, assigns sources, and confirms the feeds and monitor mixes before handing control to the players or the main console.", "category": "Pit mixing", "related_terms": ["Pit microphone system", "Personal mixer", "Pit monitor system", "Pit foldback", "Pit monitor", "Orchestra pit"], "common_mistakes": ["Setting a submixer's output too hot, so it clips or overloads the input on the main console.", "Leaving the mixer unlabelled, so players or engineers cannot tell which control feeds which source.", "Confusing a personal monitor mixer, which sets one player's blend, with a submix that feeds the main system."], "scenario_contexts": ["Submixing a large percussion setup down to a stereo pair for the front-of-house console.", "Giving each pit player a personal mixer to dial in their own click and vocal balance.", "Balancing keyboard and guitar feeds in the pit before sending them to the main mix."]}, "411e029e-5804-4299-bbc1-c357a55d68d0": {"definition": "A monitor in the orchestra pit that gives musicians and the conductor the audio or video reference they need—commonly a foldback loudspeaker or personal monitor carrying program (vocals), click, and cues, and sometimes a video monitor of the conductor or stage. It compensates for the pit being acoustically and visually separated from the performers it must follow.", "plain_english": "This is what the pit uses to keep in sync with the show. Most often it is a foldback speaker or headphone feed. It carries the singers, a click, and cues. Sometimes it is a screen showing the conductor or stage.", "purpose_function": "It delivers the reference the pit cannot hear or see directly, so players and the conductor stay locked with the singers and the action on stage.", "practical_application": "A technician sets up the pit monitor feed, chooses the right mix of vocals, click, and cues, and sets its level so players can follow it without spill into microphones.", "category": "Pit monitoring", "related_terms": ["Pit foldback", "Pit loudspeaker", "Pit monitor system", "Pit monitor position", "Conductor monitor", "Personal monitor"], "common_mistakes": ["Feeding the pit monitor the same mix as the audience, instead of the vocals and click the players actually need.", "UNSAFE: Running headphone or wedge monitor levels high enough to risk hearing over a long run, rather than managing exposure to recognised noise limits.", "Confusing an audio pit monitor with a video conductor monitor; they carry different information."], "scenario_contexts": ["Sending a vocal-and-click mix to the pit so the band follows the singers.", "Adding a video monitor so a sunken conductor can see the stage action.", "Adjusting a player's wedge so they hear the lead vocal over their own instrument."]}, "ed7ee5a1-b55b-4852-ad14-20a0a5b77832": {"definition": "The chosen placement of a monitor in the orchestra pit—the location, height, and aim of a foldback loudspeaker, personal monitor, or video screen—so the intended musicians or the conductor can hear or see it clearly while minimising spill into open microphones and keeping it clear of players, stands, and sightlines.", "plain_english": "This is where a pit monitor is placed. It covers a speaker's spot and aim, or a screen's location. A good position lets the right players hear or see it. It also keeps sound out of the mics.", "purpose_function": "It ensures the monitor reaches its intended listeners or viewers with enough clarity, without leaking into microphones or blocking movement and sightlines in the crowded pit.", "practical_application": "A technician places and aims each pit monitor during setup, checking that the target players hear or see it and that it does not spill into nearby microphones.", "category": "Pit monitoring", "related_terms": ["Pit monitor", "Pit monitor system", "Pit loudspeaker", "Pit microphone position", "Conductor monitor", "Sightlines"], "common_mistakes": ["Aiming a foldback speaker across open microphones, adding spill and feedback risk instead of covering the players.", "Placing a monitor where a player or stand blocks it, so the intended listener cannot hear or see it.", "Setting a video monitor where glare or a bad angle stops the conductor from reading it clearly."], "scenario_contexts": ["Angling a wedge toward the string section so it clears the nearby overhead mics.", "Mounting a conductor video monitor at eye height on the pit rail.", "Moving a foldback speaker during tech because it was spilling into the harp mic."]}, "62a4a3d2-e5e5-4f6e-9a23-25a7b9372da4": {"definition": "The complete foldback and reference setup for the orchestra pit—the monitors, feeds, sends, mixers or personal-monitor units, cabling, and any video relay—designed as a whole to give every pit musician and the conductor the audio and visual cues they need to stay synchronised with the performance. It defines what each player hears or sees and how those mixes are generated and routed.", "plain_english": "This is the whole setup that keeps the pit in sync. It includes the monitors, the mixes, and all the cabling. It may add screens of the conductor or stage. Together it gives each player what they need to hear and see.", "purpose_function": "It provides a planned, repeatable way to deliver the right foldback and video to every pit position, so the whole pit stays locked to the singers and the stage.", "practical_application": "A technician designs and patches the pit monitor system from a needs list, then sets each mix and checks coverage before rehearsals and each performance.", "category": "Pit monitoring", "related_terms": ["Pit monitor", "Pit monitor position", "Pit foldback", "Personal mixer", "Conductor monitor", "Pit loudspeaker"], "common_mistakes": ["Building one shared mix for the whole pit when different players need different balances of vocals, click, and instruments.", "UNSAFE: Designing the system with no level management, allowing sustained monitor levels that risk musicians' hearing over a long run.", "Forgetting the conductor's needs, so the video relay or cue feed is left out of the system plan."], "scenario_contexts": ["Designing separate foldback mixes for strings, brass, and percussion in one pit.", "Integrating a click, vocal feed, and conductor video into a single pit monitor system.", "Commissioning the pit monitor system during tech and saving it for the run."]}, "76109e5b-c423-437c-8303-1e7966f4464f": {"definition": "A safety net rigged across or around an exposed orchestra pit to catch performers or objects that fall from the stage edge into the pit. It is used where the pit is open to the stage or auditorium and the drop presents a fall hazard to cast, crew, or musicians.", "plain_english": "A strong net stretched over an open orchestra pit. It catches anyone who falls off the stage edge before they hit the musicians below.", "purpose_function": "Guards the vertical drop at an open pit edge so a fall from the stage does not injure a performer above or the players below. It provides fall protection where a solid guardrail would block sightlines or the action.", "practical_application": "Crews rig and tension the net to rated anchor points before the pit is opened, then inspect it during pre-show checks for slack, damage, and secure attachment.", "category": "Pit Safety", "related_terms": ["Pit rail", "Pit opening", "Orchestra pit", "Guardrail", "Fall protection", "Stage apron"], "common_mistakes": ["UNSAFE: Treating a pit net as a substitute for edge guarding or spotters; it is a last line of defense, not a replacement for a rail or clearly marked edge.", "UNSAFE: Leaving the net slack or fixing it to unrated points, which can let a falling person bottom out onto the pit floor.", "Confusing a fall-catch pit net with acoustic or debris screening.", "Skipping the pre-show inspection of net tension, anchors, and fabric condition."], "scenario_contexts": ["A musical where actors work near an open downstage pit edge and a net spans the gap for the run.", "A concert staging where the pit lift is lowered and a net guards the resulting drop.", "A pre-show safety walk where the crew checks net anchors and tension before doors open."]}, "647ef402-e9e7-4c7b-8c96-06c7964b45be": {"definition": "The unroofed area of an orchestra pit that lies open to the auditorium, that is, the part not covered by the stage apron or overhang. Its size relative to the covered area governs how much orchestral sound reaches the house and how well players hear one another.", "plain_english": "The open, uncovered part of the orchestra pit facing the audience. How big it is decides how much of the orchestra's sound the crowd hears.", "purpose_function": "It sets the acoustic coupling between the pit and the auditorium, balancing orchestra loudness against singers on stage. Designers size it to control blend, level, and the players' ability to hear the stage.", "practical_application": "Staff may adjust the overhang, pit rail, or lift position to change the effective opening when the orchestra is too loud or too covered for the singers.", "category": "Pit Architecture", "related_terms": ["Orchestra pit", "Pit rail", "Stage apron", "Pit lift", "Pit net", "Sightlines"], "common_mistakes": ["Confusing the pit opening (the area exposed to the house) with the pit's total floor area.", "Assuming a larger opening always improves sound, when it can also let the orchestra overpower the singers.", "Ignoring how the overhang depth changes the effective opening and the players' self-monitoring."], "scenario_contexts": ["An opera where the pit sits partly under a deep overhang and staff assess the opening for balance.", "Tuning a pit's brass balance by discussing overhang and opening with the conductor.", "A design review of a new hall where the pit opening ratio is specified for acoustic balance."]}, "584f9876-c6dc-418c-a15a-32f68d6f061f": {"definition": "An equipment rack positioned in or beside the orchestra pit to house the audio gear used there, such as sound modules, keyboard tone generators, direct boxes, playback devices, amplifiers, or an I/O interface for the pit musicians.", "plain_english": "A frame of audio gear kept in the orchestra pit. It holds things like keyboard sound modules and signal boxes for the players.", "purpose_function": "Keeps the pit's electronics organized, powered, and cabled in one place close to the musicians who use them. It shortens cable runs and simplifies patching between pit instruments and the mix system.", "practical_application": "A technician builds and labels the pit rack, patches keyboards, direct boxes, and monitor sends to it, and secures it clear of walkways during load-in.", "category": "Pit Signal Flow", "related_terms": ["Pit stage box", "Pit submix", "Direct box", "Keyboard rack", "Multicore snake", "Pit speaker position"], "common_mistakes": ["UNSAFE: Blocking a pit exit path, or routing cables so they create trip hazards around the rack, which endangers players evacuating a confined pit.", "Under-providing power or cooling for a densely loaded rack of sound modules.", "Failing to label rack I/O, which makes troubleshooting during a show slow and error-prone."], "scenario_contexts": ["A musical with programmed keyboards where all sound modules live in a single pit rack.", "A load-in where the pit rack is wheeled in and patched to the stage box and monitors.", "Show-call troubleshooting when a keyboard patch fails and the tech traces it at the rack."]}, "e8e6bc30-4338-4e89-bb98-2198bce03fb8": {"definition": "The fixed barrier, usually a low wall or railing, running along the audience-facing edge of an orchestra pit, separating the pit from the front seating and guarding the drop into it. Its top or face is often used to mount house-side lighting, reflectors, or connector strips.", "plain_english": "The low wall or railing at the front of the orchestra pit. It keeps front-row audience members from falling into the pit.", "purpose_function": "Provides fall protection and a clear divide between audience and orchestra at the pit edge. It also offers a handy surface for mounting lights, reflectors, or connector panels facing the stage.", "practical_application": "Crews confirm the rail is secure and at a safe height, and may clamp front-fill speakers, footlights, or mics to it, dressing cables so they do not hang into the seating.", "category": "Pit Architecture", "related_terms": ["Orchestra pit", "Pit net", "Pit opening", "Guardrail", "Front fill", "Pit speaker position"], "common_mistakes": ["UNSAFE: Treating a low decorative pit rail as adequate fall protection; verify its height and strength meet the venue's guardrail requirements where a fall hazard exists.", "UNSAFE: Overloading the rail with heavy fixtures or letting cables dangle into the seating, creating fall or trip hazards.", "Confusing the pit rail (front barrier) with the pit net or the conductor's stand rail.", "Assuming the pit-rail lighting position is the same as the balcony rail in a plot."], "scenario_contexts": ["Hanging front-fill speakers or footlights on the pit rail for front-row coverage.", "A safety check confirming the pit rail height and fixings before the audience is admitted.", "Running a connector strip along the pit rail to feed pit-edge lighting or mics."]}, "6c3b4ee8-c43d-44be-8123-c1be6dbe58c1": {"definition": "The feed of live stage program sound distributed into the orchestra pit as part of a venue's show-relay system, letting the conductor and players hear stage dialogue, vocals, and action they cannot clearly see. It is typically a dedicated loudspeaker or monitor send carrying the relay mix to the pit.", "plain_english": "A sound feed that pipes the stage audio down into the orchestra pit. It lets the players and conductor hear the singers and action they cannot see.", "purpose_function": "Keeps pit musicians in time with the stage when they cannot clearly see or hear the performers directly. It is part of the wider show-relay system that also feeds dressing rooms and backstage.", "practical_application": "A technician routes a stage-mic relay mix to a pit loudspeaker or the conductor's monitor and sets its level to aid timing without upsetting the acoustic balance.", "category": "Pit Communications", "related_terms": ["Show relay", "Pit speaker position", "Foldback", "Conductor monitor", "Pit submix", "Paging system"], "common_mistakes": ["Confusing the pit relay (stage sound sent to the pit) with foldback (the pit's own sound sent back to the musicians).", "Setting the relay too loud, which muddies the pit's acoustic balance and distracts players.", "Assuming the relay replaces line-of-sight cues from the conductor's monitor or cue lights."], "scenario_contexts": ["An opera where the pit sits under a deep overhang and players rely on a relay to hear the singers.", "Feeding stage vocal mics to a conductor's monitor so entries stay tight.", "Setting up show relay to the pit, dressing rooms, and green room during a fit-up."]}, "98d6418e-84bd-42fe-9b0e-00afd663cbe7": {"definition": "A loudspeaker location in or at the orchestra pit, used either to reinforce sound toward the front rows (front-fill or pit-fill) or to provide foldback and show relay to the musicians. Placement is constrained by sightlines, the pit rail, and the players' acoustic environment.", "plain_english": "A spot in or at the orchestra pit where a loudspeaker is placed. It can cover the front seats or help the players hear.", "purpose_function": "Fills coverage gaps for the closest audience seats and delivers monitor or relay sound to the pit. It exists because main speaker arrays often miss the front rows and pit players need their own feed.", "practical_application": "A technician mounts small speakers on the pit rail for front-fill or places monitors in the pit, then aims and levels them to avoid feedback and audience distraction.", "category": "Pit Signal Flow", "related_terms": ["Front fill", "Pit rail", "Foldback", "Pit relay", "Pit submix", "Pit stage box"], "common_mistakes": ["UNSAFE: Aiming pit-rail front-fills up into open microphones on stage, which invites feedback that can spike the level during a live show.", "Setting front-fill level too high so it draws attention instead of just filling the gap.", "Confusing audience front-fill from the pit with musicians' foldback in the pit."], "scenario_contexts": ["Adding front-fill speakers on the pit rail so front-row patrons hear a centered image.", "Placing wedge monitors in the pit for musicians on a loud musical.", "Positioning a pit loudspeaker for show relay under a deep stage overhang."]}, "5e2386b2-c454-47f7-9442-372e5a1b9105": {"definition": "A close or accent microphone placed on a specific instrument or section within the orchestra pit to capture or reinforce it individually, supplementing any main or area miking. In musical theatre it commonly picks out instruments such as reeds, brass, or percussion that need extra presence in the mix.", "plain_english": "A microphone aimed at one instrument or group in the orchestra pit. It picks out that sound so it stands out in the mix.", "purpose_function": "Gives the mixer individual control and added clarity for chosen pit instruments that a distant main mic cannot capture well. It supports blend, level, and presence in reinforcement or recording.", "practical_application": "A technician clips or stands a spot mic close to an instrument, sets gain to avoid overload and bleed, and assigns it to its own channel or a pit submix.", "category": "Pit Microphones", "related_terms": ["Spot microphone", "Pit submix", "Pit stage box", "Direct box", "Overhead microphone", "Gain before feedback"], "common_mistakes": ["UNSAFE: Running mic cables across pit walkways instead of dressing them safely, tripping players in a tight, dim pit.", "Placing a spot mic too close, causing overload, tonal imbalance, or heavy bleed from neighboring instruments.", "Confusing a spot (accent) mic with a main or area mic and expecting it to capture the whole section.", "Forgetting that added spot mics raise feedback risk in a reinforced pit."], "scenario_contexts": ["Miking individual reed doublers and brass in a Broadway-style pit.", "Adding a spot mic to a solo instrument so it can be lifted for a feature moment.", "Balancing spot mics against a main pit pair when recording a pit orchestra."]}, "9c64262a-4276-4e30-9afd-b582126d780d": {"definition": "A stage box (I/O box or snake head) installed in the orchestra pit that concentrates the pit's microphone, line, and DI inputs, and often monitor or relay outputs, into a single multicore or digital-network connection back to the console or stage rack.", "plain_english": "A connection box in the orchestra pit. All the pit's mic and instrument cables plug into it, then one main cable carries them to the mixer.", "purpose_function": "Collects many pit signals at the source and sends them to the mix position over one multicore or network cable, cutting clutter and simplifying patching. It can also return monitor and relay feeds to the pit.", "practical_application": "A technician positions the pit stage box near the players, patches instrument and mic lines into it, and links it to the console via a copper snake or a digital audio network.", "category": "Pit Signal Flow", "related_terms": ["Multicore snake", "Pit rack", "Pit submix", "Direct box", "Stage box", "Audio network"], "common_mistakes": ["UNSAFE: Placing the box or its multicore across a pit walkway or exit, creating a trip hazard in a confined space.", "Overrunning the box's input count and losing channels mid-fit-up.", "Confusing analog multicore returns with digital network patching when connecting the box.", "Forgetting to provide and protect power for a networked or active stage box."], "scenario_contexts": ["Patching all pit instruments into a stage box that feeds a digital snake to front of house.", "Using the pit stage box's returns to send monitors and show relay to the players.", "Troubleshooting a dead pit channel by checking the connection at the stage box."]}, "52b3e4d3-725c-4255-b2ec-d9d3b018ff36": {"definition": "A submix that combines the orchestra pit's microphone and instrument channels into one or more subgroups before they reach the main mix. It lets the operator control the whole pit, or sections of it, with a single fader and apply shared processing.", "plain_english": "A group fader that blends all the orchestra pit's channels together. The mixer can then raise or lower the whole pit at once.", "purpose_function": "Simplifies control of many pit sources and lets the operator balance the pit against vocals with one move, while applying common EQ, dynamics, or effects to the group. It cuts the number of faders ridden during a fast-moving show.", "practical_application": "An operator routes the pit channels to a subgroup, balances the internal mix once, then rides that subgroup fader against the cast vocals through the show.", "category": "Pit Signal Flow", "related_terms": ["Subgroup", "Pit stage box", "Pit rack", "Pit spot microphone", "VCA group", "Mix bus"], "common_mistakes": ["Confusing a subgroup pit submix with an aux or monitor mix of the pit.", "Applying heavy group processing that ruins a carefully set internal pit balance.", "Routing the submix to both the main bus and directly to the main output, double-feeding the signal."], "scenario_contexts": ["Grouping a 20-piece pit onto one or two faders to ride against vocals.", "Adding gentle compression across the pit subgroup to steady its level.", "Using a pit submix so a single move can duck the orchestra under dialogue."]}, "5051b050-8564-43fe-86c4-73efbbd16740": {"definition": "A talkback communication link serving the orchestra pit, typically a microphone at the conductor's or musical director's position feeding the sound control position, stage management and sometimes the stage, with a return so those positions can speak back into the pit. Unlike one-way orchestra paging, pit talkback is intended as a two-way conversational path used for coordination during rehearsal and performance.", "plain_english": "Pit talkback is a mic-and-speaker link for the orchestra pit. The conductor can talk to the sound crew or the stage team. Those people can answer back. It works two ways, unlike paging, which only goes one way.", "purpose_function": "It gives the conductor a direct two-way voice channel to the sound operator, stage manager and stage, so the pit can be coordinated with the rest of the production without shouting or leaving position.", "practical_application": "A sound technician wires a talkback mic and a small monitor speaker or headset at the podium, routes it into the intercom or console talkback bus, and checks it during rehearsal so the conductor can flag balance or tempo issues.", "category": "Communication Systems", "related_terms": ["Orchestra paging", "Show relay", "Stage relay", "Conductor talkback", "Production intercom", "Orchestra headphone system"], "common_mistakes": ["Confusing pit talkback (two-way) with orchestra paging, which is a one-way announcement feed into the pit.", "Leaving the conductor's talkback mic open into the house mix, so podium comments and cues are heard by the audience.", "Routing talkback only to the sound booth and forgetting the stage manager, who also needs to coordinate with the pit."], "scenario_contexts": ["A musical where the conductor needs to query the sound operator about vocal-to-band balance between numbers.", "A pit placed under the stage or in a separate room, where the conductor cannot be seen and must communicate by voice link.", "A technical rehearsal where stage management and the pit coordinate the start of a number over talkback."]}, "c96d6227-af55-4efc-a6ff-51a0d5484afe": {"definition": "An enclosed passageway, usually running under or beside the stage, that connects the orchestra pit to backstage areas, dressing rooms or the understage so that musicians can enter and leave the pit without crossing the stage or passing through the auditorium. It also carries cabling and services to the pit and keeps musician movement out of sight of the audience.", "plain_english": "A pit tunnel is a hidden passage under or beside the stage. Players use it to reach the orchestra pit. They do not have to cross the stage or walk through the crowd.", "purpose_function": "It provides a concealed, direct route between the pit and backstage so players and instruments can move discreetly, and it routes power, audio and lighting cabling to the pit.", "practical_application": "Crew run and dress cabling through the pit tunnel to the pit, keep the route clear as a means of egress, and use it to move large instruments such as timpani or harp in and out before and after a show.", "category": "Pit Architecture", "related_terms": ["Orchestra pit", "Pit wall", "Musician entrance", "Understage", "Get-in"], "common_mistakes": ["UNSAFE: Blocking or storing gear in the pit tunnel, obstructing a route that also serves as an emergency exit for players.", "Assuming every pit has a tunnel; many smaller or retrofitted pits are entered only from the auditorium or a side door.", "Running unsecured cable across the tunnel floor, creating a trip hazard in a dimly lit passage."], "scenario_contexts": ["An opera house where the full pit orchestra reaches its seats from the dressing rooms via an understage tunnel.", "Moving a harp or timpani into the pit before the house opens, using the tunnel instead of the stage.", "Planning cable runs from a backstage amp room out to the pit during a system install."]}, "497e816d-c4fa-40e5-ac61-02d45ae80504": {"definition": "The vertical boundary wall of the orchestra pit, most often the front wall (pit rail) that separates the pit from the front rows of the auditorium, together with the side and rear walls that define the pit enclosure. The pit wall marks the edge of the pit for safety, supports the pit rail and any acoustic screening, and influences how directly pit sound reaches the audience.", "plain_english": "The pit wall is the wall around the orchestra pit. The front part sits between the players and the first row of seats. It marks the edge and helps control how much pit sound spills into the room.", "purpose_function": "It encloses and defines the pit, provides a safety edge between players and audience, and acts as an acoustic surface that shapes the balance of pit sound reaching the hall.", "practical_application": "Technicians mount pit-rail lighting, cue lights or acoustic panels on the pit wall and take its height and reflectivity into account when placing pit microphones and setting orchestra balance.", "category": "Pit Architecture", "related_terms": ["Orchestra pit", "Pit tunnel", "Pit rail", "Acoustic shell", "Pit screen"], "common_mistakes": ["UNSAFE: Treating an open top edge of the pit wall as safe without a rail or barrier, risking a fall from stage or house level into the pit.", "Ignoring reflections off a hard pit wall, which can make brass and percussion sound harsh in the front rows.", "Confusing the pit wall (the structural boundary) with the pit rail, the barrier mounted along its top edge."], "scenario_contexts": ["Deciding where to place pit microphones given a high, hard front pit wall that shadows the audience from string sound.", "Fitting acoustic absorption to the pit wall to tame a loud brass section in a shallow pit.", "Mounting cue lights on the audience side of the pit wall for musicians who cannot see the stage manager."]}, "1a69922c-eb44-4b69-b3e3-6d53e2e96468": {"definition": "The seating position of the principal, the leading player of an orchestral section, who plays exposed solo passages, sets bowings and phrasing for the section, and leads its entries and balance. The principal chair sits at the front of the section, closest to the conductor and audience, and outranks the other desks in that section.", "plain_english": "The principal chair is the top seat in a section of players. The person in it leads that group. They play the solo parts and decide how the section plays together.", "purpose_function": "It designates one player to lead each section, giving the ensemble a single reference for entries, articulation and balance and a soloist for that instrument's exposed lines.", "practical_application": "When setting stage seating or spot-miking soloists, crew identify the principal chair of each section so the section leader is placed at the front desk and, where needed, covered by a dedicated microphone.", "category": "Ensemble Roles", "related_terms": ["Section leader position", "Concertmaster", "String section", "Second violins", "Desk"], "common_mistakes": ["Assuming the concertmaster and every section principal are the same rank; the concertmaster is the leader of the whole orchestra, above the other principals.", "Placing a section's solo microphone on the wrong desk instead of the principal chair at the front.", "Confusing 'principal' (the section leader) with 'first chair' terminology from a different desk-numbering scheme."], "scenario_contexts": ["Spot-miking a woodwind principal for an exposed solo in a live concert recording.", "Arranging pit or stage seating so each section principal occupies the front, aisle-side desk.", "A student learning why the principal cellist, not the whole section, plays a marked solo passage."]}, "9a14e17a-fb48-4799-993a-b226e875d9c1": {"definition": "The second of the two violin sections of a symphony orchestra, playing the second violin part, which typically supplies inner harmonies, accompaniment figures or a countermelody beneath the first violins, and led by its own principal. Second violins are usually seated to the conductor's left beside the firsts, or facing them across the stage in antiphonal (divided) seating.", "plain_english": "The second violins are one of two violin groups in an orchestra. They often play the inner or backing notes. The first violins usually play the main tune above them.", "purpose_function": "They add a second, lower violin line that fills out the harmony and rhythm of the string sound and can answer or echo the first violins when the music is written antiphonally.", "practical_application": "When miking or mixing strings, an engineer places or pans the second violins as a distinct group and balances them against the firsts to keep inner parts audible without covering the melody.", "category": "Ensemble Section", "related_terms": ["String section", "First violins", "Concertmaster", "Principal chair", "Antiphonal seating"], "common_mistakes": ["Thinking second violins play easier or lower-quality parts; they play a different, equally demanding line, not a beginner's part.", "Miking or panning both violin sections as one block, losing the antiphonal exchange between firsts and seconds.", "Assuming seconds always sit next to the firsts; many orchestras seat them opposite, on the conductor's right."], "scenario_contexts": ["Setting stereo mic placement so first and second violins are distinguishable in a classical recording.", "A conductor calling for the second violins to bring out a countermelody in rehearsal.", "Explaining to a student why a score has two separate violin staves."]}, "d9714c52-ac69-441d-a579-d985ffa566fa": {"definition": "The seat at the front of an instrumental section, nearest the conductor and audience, occupied by the section principal from which the section is led. From this position the leader cues entries, sets bowings and articulation, and controls the section's timing and balance, and it is the reference point for laying out the rest of the section's desks behind it.", "plain_english": "This is the front seat of a group of players, closest to the conductor. The section leader sits here. From it they guide the group's timing and style.", "purpose_function": "It fixes where the section's principal sits so the leader is visible to the conductor and the rest of the section can follow their bowing and cues.", "practical_application": "Stage crew set the section leader position first when laying out chairs and stands, then arrange the remaining desks behind it, and often reserve a mic or monitor for that seat.", "category": "Ensemble Roles", "related_terms": ["Principal chair", "Concertmaster", "String section", "Second violins", "Desk"], "common_mistakes": ["Setting up section chairs symmetrically without first fixing the leader's front, aisle-side seat as the reference.", "Confusing the section leader position with the concertmaster's chair, which leads the whole orchestra rather than one section.", "Placing the leader where the conductor cannot see them, breaking the visual chain the section relies on for cues."], "scenario_contexts": ["Chalking or taping a stage plot so each section leader position lands in the same spot every performance.", "Positioning a solo microphone at the woodwind section leader position for exposed passages.", "Arranging a pit so each string section leader can see both the conductor and their players."]}, "677efa09-824a-485e-8c8f-8f9380246a7d": {"definition": "A distribution system that feeds a live audio pickup of the onstage performance (sometimes with video) to backstage areas such as dressing rooms, the green room, wings, the orchestra pit and front-of-house offices, so that cast, crew and staff can follow the show's progress and take their cues. It is a one-way monitoring feed, usually combined with the paging system and controlled from the stage manager's position.", "plain_english": "Show relay is a live feed of the sound on stage. It is piped to dressing rooms, the pit, and other backstage spots. This lets cast and crew follow the show from far away.", "purpose_function": "It lets everyone offstage hear the performance in real time so they know when to get ready, make an entrance or run a cue without having to watch the stage directly.", "practical_application": "A technician sets up stage relay microphones, routes their mix to dressing-room and backstage loudspeakers alongside the paging feed, and checks levels so announcements can duck or override the relay when the stage manager pages.", "category": "Communication Systems", "related_terms": ["Stage relay", "Dressing-room loudspeaker", "Orchestra paging", "Call desk", "Production intercom"], "common_mistakes": ["Confusing show relay (a one-way listen feed of the performance) with intercom or talkback, which are two-way crew channels.", "Setting relay speakers so loud in a dressing room that a page announcement cannot be heard over them.", "Placing relay pickup mics only at center stage, so quiet or downstage-edge action is missed backstage."], "scenario_contexts": ["Actors in dressing rooms listening to the show relay to time their return to the wings.", "A stage manager paging 'places' that ducks the relay feed across all backstage speakers.", "The orchestra pit receiving a relay feed so players can hear onstage dialogue before a cue."]}, "8e48b39d-4569-479b-a737-158a8c61e803": {"definition": "The live pickup of onstage sound, taken from dedicated stage microphones and distributed to backstage areas, dressing rooms and the orchestra pit so that people offstage can hear the performance in progress; the term is used largely interchangeably with show relay, sometimes emphasizing the stage-microphone source of the feed. It is a one-way monitoring path, normally integrated with the paging system.", "plain_english": "Stage relay sends the live stage sound to backstage rooms and the pit. People who are not on stage can still hear the show. It is another name for show relay.", "purpose_function": "It captures the performance at the stage and carries it to everyone working offstage so they can follow the action and stay ready for their cues.", "practical_application": "A technician hangs or places stage relay microphones over the acting area, mixes them to backstage and dressing-room speakers, and balances the feed so the paging system can cut through when needed.", "category": "Communication Systems", "related_terms": ["Show relay", "Dressing-room loudspeaker", "Orchestra paging", "Call desk", "Production intercom"], "common_mistakes": ["Assuming stage relay and paging are the same; relay is the ongoing performance feed, paging is the stage manager's live announcements.", "Using vocal or effects mics from the main mix as the relay source, so backstage hears a processed mix rather than a clear stage pickup.", "Forgetting to feed the pit, leaving musicians unable to hear onstage cues they must respond to."], "scenario_contexts": ["Dedicated relay mics over the stage feeding the green room and dressing rooms during a play.", "Musicians in a covered pit relying on stage relay to hear dialogue leading into a musical number.", "Commissioning backstage speakers and verifying the stage relay feed reaches every room before opening night."]}, "3a7034f0-05be-473a-a2d0-b022bdb2a527": {"definition": "The family of bowed string instruments that forms the largest and foundational body of the symphony orchestra: first violins, second violins, violas, cellos (violoncellos) and double basses (contrabasses), and sometimes the harp. Players are grouped by instrument and each subsection is led by its own principal, with the string sound providing the orchestra's core sustained texture.", "plain_english": "The string section is the group of bowed string instruments. It has violins, violas, cellos, and double basses. It is usually the biggest part of an orchestra.", "purpose_function": "It supplies the orchestra's core, blendable sustained sound and its widest pitch range, from high violins down to the double basses, forming the base on which the other sections sit.", "practical_application": "Engineers mic the string section as grouped desks or with a stereo array, and manage its wide dynamic range and many players when balancing it against louder brass and percussion.", "category": "Ensemble Section", "related_terms": ["Second violins", "First violins", "Viola section", "Cello section", "Concertmaster", "Principal chair"], "common_mistakes": ["Listing the piano or guitar as string-section instruments; the orchestral string section is bowed strings, not struck or plucked ones.", "Under-miking a large string section against brass, so its quieter, blended sound is buried in the mix.", "Forgetting the double basses as part of the strings and treating them only as a rhythm-section instrument."], "scenario_contexts": ["Choosing a stereo pair or spot mics to capture a full string section in a concert-hall recording.", "Balancing the strings against a loud brass section during a film-score session.", "Laying out orchestra seating so all string subsections face the conductor with clear sightlines."]}, "f07dbfd9-ceda-4cfe-a6a4-b51b0befaf0c": {"definition": "The viola section is the group of violists in a string ensemble, one of the standard string subsections. Its players sit together among the strings and supply the alto register of the string choir, filling the harmony between the violins above and the cellos below. The viola is larger than the violin, played under the chin, and tuned a fifth lower.", "plain_english": "The viola section is the group of viola players in an orchestra. A viola looks like a violin but is a bit bigger. It plays lower notes than the violin. The violas fill in the middle of the string sound, between the violins and the cellos.", "purpose_function": "Grouping the violas gives a composer a unified alto string voice, and lets the ensemble seat them together for blend, so they can carry inner harmony and link the sound of the violins and cellos.", "practical_application": "When laying out a pit or stage, a technician allows chair and floor space for the viola section among the strings, and for close micing treats the violas as one group aimed toward the audience or conductor.", "category": "Orchestral section", "related_terms": ["String section", "Cello section", "First violins", "Double-bass section", "Chair layout", "Orchestra pit"], "common_mistakes": ["Confusing the viola with the violin; the viola is larger, tuned a fifth lower, and reads mainly in the alto clef, so it is not simply a big violin played the same way.", "Assuming the violas always sit in one fixed spot; seating differs between orchestras and conductors, so the viola block may be inner-right, center, or on the conductor's right edge.", "Underestimating how easily the violas' alto register is masked; because they sit inside the string group, their sound is readily covered by louder sections and needs care when balancing or micing."], "scenario_contexts": ["Allocating chair and floor space for the violas when planning a pit layout.", "Seating the viola section between the second violins and cellos so the string harmony blends.", "Micing the violas as a group for a recording session.", "Adjusting the viola position when a conductor prefers a different string seating."]}, "b41a46a5-f8cf-45b3-8b6a-d5e3d8873ea8": {"definition": "The woodwind section is the family of wind instruments that produce sound with an air reed or a cane reed, typically flutes, oboes, clarinets, and bassoons, plus their relatives such as piccolo, English horn, bass clarinet, and contrabassoon, treated both as an orchestration unit and as a seating block. In the standard orchestra it is placed in the center behind the strings and in front of the brass, usually in two rows with flutes and oboes in front and clarinets and bassoons behind.", "plain_english": "The woodwind section is the group of wind instruments like flutes, oboes, clarinets, and bassoons. Players make sound by blowing air across or through a reed. The saxophone counts as a woodwind too, even though it is made of metal. This group usually sits in the middle, behind the strings.", "purpose_function": "Grouping the woodwinds lets a composer write for them as a blended block of contrasting colors, and lets the ensemble seat these agile, moderate-volume instruments in the center where they are heard clearly between the strings and the louder brass.", "practical_application": "When placing microphones or planning a pit, a technician seats the woodwinds as a central block behind the strings, spacing them so each color is captured and not buried under the brass behind them.", "category": "Orchestral section", "related_terms": ["Brass section", "String section", "Percussion section", "Orchestra pit", "Chair layout", "Instrument doubling area"], "common_mistakes": ["Defining woodwinds by material; the flute is usually metal and the saxophone is made of brass, yet both are woodwinds because sound is made with an air reed or a cane reed, not a buzzing-lips mouthpiece.", "Forgetting that woodwind players often double on related instruments, such as flute and piccolo or oboe and English horn, which changes the parts and the space they need.", "Placing the woodwinds too far back or directly behind the brass, so their moderate output is covered and lost in the ensemble balance."], "scenario_contexts": ["Seating flutes, oboes, clarinets, and bassoons in the center of an orchestra behind the strings.", "Allowing space for woodwind players who double on piccolo, English horn, or bass clarinet.", "Micing the woodwinds as a section for a recording or broadcast.", "Balancing the woodwinds against the louder brass behind them during a rehearsal."]}, "bb5d700d-5daf-4b3a-a6fc-202843e93f3d": {"definition": "A show-control input in which a performer presses a physical push-button, wired through a MIDI, keyboard, or contact-closure interface, to fire a cue from onstage rather than having an operator call or start it. The button feeds the trigger input of a playback system such as QLab or a show controller, so an effect executes in exact synchronization with the actor's action.", "plain_english": "It is a button an actor presses to start a sound or effect. The actor sets off the cue instead of a crew member. This makes the effect happen at the exact right moment.", "purpose_function": "It hands the timing of an effect to the performer, so sound, light, or video can land precisely with a live action that an offstage operator cannot time as tightly.", "practical_application": "A technician wires a stage button to a MIDI or keyboard input and maps it in the playback system's Triggers tab so the actor's press starts the cue.", "category": "Cue triggering", "related_terms": ["Actor Footswitch Trigger", "MIDI trigger", "Hotkey trigger", "QLab", "Cue", "Show control"], "common_mistakes": ["Assuming the button sends audio; it only sends a trigger signal that tells the playback system to start a cue.", "Providing no operator backup, so the cue cannot be fired manually if the actor misses it or the button fails.", "Not debouncing or testing the switch, so one press fires the cue twice or not at all."], "scenario_contexts": ["An actor pressing a hidden button to fire a gunshot sound exactly on the trigger-pull.", "A magician pressing a concealed button to start a music sting on a reveal.", "Fitting a button to a prop so a performer fires a lighting effect on their own timing."]}, "56d7823d-3595-43a5-93f2-6b051d7bb940": {"definition": "A show-control input in which a performer uses a foot-operated switch to fire a cue from onstage, keeping the hands free for performance. The footswitch connects through a MIDI, keyboard-emulating, or contact-closure interface to the trigger input of a playback system such as QLab or a show controller.", "plain_english": "It is a foot pedal an actor steps on to start a cue. Using a foot keeps both hands free to act. The effect then happens right on the actor's move.", "purpose_function": "It gives the performer hands-free control of a cue's timing, so effects sync to a live action while the actor still uses their hands for the scene.", "practical_application": "A technician hides a footswitch at the actor's position and maps it in the playback system so a step on the pedal starts the cue.", "category": "Cue triggering", "related_terms": ["Actor Button Trigger", "MIDI trigger", "Footswitch", "QLab", "Cue", "Show control"], "common_mistakes": ["Placing the footswitch where the actor cannot find it in the dark, causing missed cues.", "Assuming the pedal carries audio; it only sends a trigger to the playback system.", "UNSAFE: Running the footswitch cable across a walked path without taping or matting it, creating a trip hazard onstage."], "scenario_contexts": ["A guitarist-actor stepping on a pedal to start a backing track at the top of a number.", "An actor triggering a doorbell sound with a hidden foot pedal while holding a prop.", "A puppeteer using a footswitch to fire a sound effect with both hands on the puppet."]}, "649ad439-6ff0-4335-8ef9-7123d96ac7fb": {"definition": "Playback of a pre-recorded vocal or speech file that the performer themselves triggers and paces, so the recorded voice aligns with the actor's lip-sync, gesture, or action. The performer starts, and sometimes advances, the audio through a button, footswitch, or other trigger feeding a playback system, rather than an operator calling it.", "plain_english": "It is a recorded voice that the actor starts, not the crew. The actor sets it off so the words match their mouth or moves. It is used when timing must fit the actor exactly.", "purpose_function": "It puts control of vocal playback in the performer's hands so recorded speech matches live action closely, which an offstage operator cannot time as precisely.", "practical_application": "A technician loads the voice files into a playback system and gives the actor a trigger so each line fires on the actor's own cue.", "category": "Cue triggering", "related_terms": ["Actor Button Trigger", "Actor Footswitch Trigger", "Audio channel", "Cue", "Playback", "Lip-sync"], "common_mistakes": ["Confusing it with live reinforcement; the sound is pre-recorded and triggered, not spoken into a microphone.", "Giving the actor an awkward or unreliable trigger, so lines fire late or out of sync with the mouth.", "Providing no operator backup if the actor's trigger fails mid-scene."], "scenario_contexts": ["A masked character triggering recorded lines so the voice matches the mask or puppet.", "An actor firing a robot's speech line by line to match their movements.", "A performer starting a recorded inner-monologue track on their own timing."]}, "d3d782a0-1f61-4397-b471-385dd0b18c7b": {"definition": "In haunted attractions and immersive theatre, a startle or 'stinger' sound effect that a scare-actor fires on their own timing—through a hidden button, footswitch, or sensor feeding a playback system—so the audio hits precisely as the actor reveals or lunges. Triggering by the actor synchronizes the sound to the live scare, which fixed timers or an operator cannot match.", "plain_english": "It is a sudden scary sound an actor sets off in a haunted house. The actor triggers it right as they jump out. That makes the sound and the scare happen together.", "purpose_function": "It ties a startle sound to the actor's live action so the scare lands as one moment, which pre-timed playback cannot reliably achieve.", "practical_application": "A technician mounts a hidden trigger at the actor's spot and sets the stinger in the playback system so the actor fires it on each scare.", "category": "Cue triggering", "related_terms": ["Actor Button Trigger", "Actor Footswitch Trigger", "Stinger", "Cue", "Sound effect", "Show control"], "common_mistakes": ["UNSAFE: Setting the scare-audio level so high it risks hearing damage to patrons or the actor over a long run; keep exposure within recognised safe limits.", "Placing the trigger where the actor must break character or reach awkwardly, so the sound lags the reveal.", "Relying on one distant loudspeaker, so the scare sound does not seem to come from the actor's position."], "scenario_contexts": ["A haunt actor hitting a hidden button to fire a scream exactly as they lunge from a corner.", "A scare-actor using a footswitch to trigger a loud bang as a wall panel drops.", "Timing a growl effect to an actor's reveal in a dark maze."]}, "23359fc4-9015-46ad-8c2c-9a8e3754b590": {"definition": "A microphone dedicated to spoken announcements over a paging or program-feed system—such as backstage calls, front-of-house pre-show announcements, or a talkback/announce feed—rather than for musical reinforcement or recording. It is routed to the paging, intercom, or announce bus so its speech reaches the intended zones on demand.", "plain_english": "It is a microphone used only for announcements. Someone speaks into it to make calls or notices. It feeds the paging or talkback system, not the main music mix.", "purpose_function": "It provides a fixed, always-available voice input for paging and announcements, kept separate from performance microphones so calls do not disturb the show mix.", "practical_application": "A technician patches the announce mic to the paging or announce bus and checks it can reach dressing rooms, backstage, or the house as needed.", "category": "Communications", "related_terms": ["Paging system", "Talkback", "Intercom", "Program feed", "Audio channel", "Cue light"], "common_mistakes": ["Routing the announce mic into the main program mix, so announcements reach the audience by mistake.", "Leaving the announce mic open, letting backstage noise leak into paging or comms.", "Confusing the announce mic with a talkback mic; announce feeds paging zones, talkback feeds crew intercom."], "scenario_contexts": ["Making a 'places' call to dressing rooms before a show.", "A front-of-house announcement asking patrons to take their seats.", "Paging a crew member backstage over the announce system."]}, "279e946a-a671-47e9-a34a-426c76ff2c48": {"definition": "A cue executed or called slightly ahead of its apparent target moment to compensate for human reaction time and system latency, so the resulting effect lands exactly on the intended beat. The lead time anticipates the delay between the 'go' and the effect actually occurring.", "plain_english": "It is a cue started a moment early on purpose. People and gear take time to react. Starting early means the effect lands right on time.", "purpose_function": "It corrects for the small delay between calling or firing a cue and the effect happening, so the audience sees the effect as perfectly timed.", "practical_application": "An operator or stage manager learns to call 'go' a beat early on fast cues, anticipating reaction and equipment lag so the effect hits the mark.", "category": "Cue calling", "related_terms": ["Cue", "Standby", "Audio go", "Latency", "Cue calling", "Warning cue"], "common_mistakes": ["Anticipating too much, so the effect fires visibly early and breaks the illusion.", "Assuming no delay between 'go' and the effect, so cues consistently land late.", "Confusing anticipation with a standby; a standby only warns, while anticipation adjusts the actual timing of 'go'."], "scenario_contexts": ["Calling a blackout a beat early so the lights are fully out on the final word.", "Firing a sound sting slightly ahead to hit exactly on an actor's move.", "Anticipating a slow-to-strike lighting fixture so it reaches full level on the beat."]}, "6a09109e-2df6-46f8-ae3f-f9dd03ea3c03": {"definition": "A single, independent path that carries one audio signal through a system, from an input, through any processing and routing, to an output. On a mixing console it is one input strip; in a file, interface, or network stream it is one discrete, usually mono, signal within the larger format.", "plain_english": "It is one lane for a single sound in a system. Each source, like a mic, gets its own channel. The channel carries that sound so it can be mixed and sent onward.", "purpose_function": "It keeps each source's signal separate so it can be processed, levelled, and routed on its own before being combined with others.", "practical_application": "A technician assigns each microphone or source to its own channel so it can be set, equalised, and routed independently at the console.", "category": "Signal path", "related_terms": ["Signal path", "Mixing console", "Bus", "Input", "Gain", "Audio go"], "common_mistakes": ["Confusing a channel with a bus; a channel carries one input, while a bus sums many signals together.", "Assuming 'channel' always means mono; a stereo channel carries two correlated signals as a pair.", "Mixing up the physical input jack with the channel; one channel can be fed from different inputs by patching."], "scenario_contexts": ["Assigning a vocal mic to channel 1 on the console.", "Counting how many channels a show needs to size the console and stagebox.", "Routing one channel to a monitor send without affecting the others."]}, "15c47336-e521-41d4-89c8-1f5cf9471dea": {"definition": "The execution command in the cueing sequence directed to the audio or sound department, in which the stage manager calls '(Sound/Audio) cue [number]… Go' to tell the operator to start the specified audio cue at that instant. 'Go' is the single reserved word that triggers execution, given only after a standby has been acknowledged.", "plain_english": "It is the word that tells the sound operator to start an audio cue. The stage manager says 'Sound Go' at the exact moment. 'Go' is the only word used to start a cue.", "purpose_function": "It gives the sound operator one clear, unmistakable command to execute a cue on the beat, avoiding any word that might be misheard as an instruction.", "practical_application": "On headset the operator hears the standby, answers 'standing by,' then runs the audio cue the instant the stage manager says 'Go.'", "category": "Cue calling", "related_terms": ["Standby", "Audio not ready", "Cue", "Cue calling", "Anticipation Cue", "Intercom"], "common_mistakes": ["Executing on the department name instead of waiting for 'Go,' so the cue fires early.", "Using words like 'fade' or 'stop' as the trigger; only 'Go' should start a cue.", "Missing the standby, so the operator is not prepared when 'Go' is called."], "scenario_contexts": ["A stage manager calling 'Sound Q 12… Go' to start music at a scene change.", "An operator running a gunshot effect the instant 'Go' is heard on comms.", "Chaining a light and sound cue so both operators act on the same 'Go.'"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"dc203515-0c53-4f6d-b990-7a8594f5aeaf": {"definition": "A status response in the cueing communications protocol in which the audio or sound department reports it is not prepared to proceed—typically given instead of 'standing by' after a standby call—so the stage manager holds the cue until readiness is confirmed. It signals a problem such as an unloaded file, a device not reset, or an operator out of position.", "plain_english": "It is the sound operator telling the stage manager they are not ready. It is said after a standby if something is wrong. The stage manager then waits before calling 'Go.'", "purpose_function": "It lets the sound department stop a cue from being called before it can be run, preventing a missed or wrong cue during the show.", "practical_application": "If a file has not loaded or a device has not reset, the operator answers 'audio not ready' on comms so the stage manager holds the sequence.", "category": "Cue calling", "related_terms": ["Standby", "Audio go", "Cue", "Hold", "Cue calling", "Intercom"], "common_mistakes": ["Staying silent when not ready, so the stage manager calls 'Go' into a cue that cannot run.", "Saying 'not ready' but never reporting when the problem is fixed, so the show stays held.", "Confusing 'not ready' with 'standing by'; they are opposite replies to a standby."], "scenario_contexts": ["An operator reporting 'audio not ready' when a sound file has not finished loading.", "Holding a cue during a tech rehearsal while the sound system is re-patched.", "A playback device needing a reset before the operator can stand by."]}, "6f281a2c-526e-4d26-8e43-c8d675deff11": {"definition": "A readiness confirmation given by the sound/audio operator to the stage manager, stating that the audio department and its playback and cue systems are cued, functional, and standing by to execute the next cue or to begin the performance. It is the audio department's response within the pre-show clearance and the standby stage of the warning/standby/go cue-calling protocol.", "plain_english": "This is when the sound operator tells the stage manager that sound is set and standing by. It means the gear and the next cue are ready. The show can go ahead.", "purpose_function": "It confirms to the stage manager that the audio department is prepared, so cues can be called and the show can proceed safely and on time.", "practical_application": "During the stage manager's pre-show department check or after a standby call over comms, the sound operator answers 'audio ready' to confirm the system and next cue are set.", "category": "Cue calling", "related_terms": ["Standby", "Go", "Warning cue", "Cue calling", "Production intercom", "Stage manager"], "common_mistakes": ["Confusing 'audio ready', a standby response confirming readiness, with 'go', the command to execute the cue; ready means prepared, not fired.", "Reporting ready before actually confirming the playback system and the correct next cue are loaded.", "Answering on the wrong intercom channel, so the stage manager never hears the confirmation."], "scenario_contexts": ["Answering 'audio ready' during the stage manager's pre-show department check before the house opens.", "Confirming 'audio ready' after a 'standby sound cue 12' call during the performance.", "Reporting audio ready once a backup playback system has been armed and tested."]}, "b7c53f90-2b60-4ac8-9363-6240d9f4ae41": {"definition": "A cue-sequence trigger setting in which a cue automatically starts the next cue in the list after the initial cue's post-wait time has elapsed; with no post-wait set, both cues begin simultaneously. It is time-based, launching the following cue after a fixed delay rather than waiting for the first cue to finish, allowing several cues to run from a single GO.", "plain_english": "This is a setting that fires the next cue on its own. It starts after a set delay, not after the first cue ends. It lets one button press run several cues in a row.", "purpose_function": "It links cues so one operator action can trigger a timed chain, starting the next cue a fixed time after the current one begins.", "practical_application": "In QLab a technician enables auto-continue and sets a post-wait so a sound cue fires a set number of seconds after the cue before it, without a second GO.", "category": "Cue sequencing", "related_terms": ["Auto-follow", "Post-wait", "Pre-wait", "Cue sequence", "Go", "QLab"], "common_mistakes": ["Confusing auto-continue, which is time-based and starts after a delay, with auto-follow, which starts only after the previous cue finishes.", "Forgetting that with no post-wait set, auto-continue starts the next cue at the same time as the current one.", "Assuming auto-continue waits for a fade or effect to end; it follows the post-wait clock, not the cue's completion."], "scenario_contexts": ["Chaining a lighting cue and a sound cue so both run from a single GO.", "Setting a post-wait so a follow-on cue starts a few seconds into the current cue.", "Building an automated pre-show sequence that advances on timers without operator input."]}, "35045469-d304-4558-9664-41a6b7781996": {"definition": "A cue-sequence trigger setting in which a cue automatically starts the next cue only after the initial cue has fully completed, including its pre-wait, action/duration, and post-wait. It is event-based, so the next cue's start time shifts automatically if the preceding cue's length changes, letting cues run back-to-back from a single GO.", "plain_english": "This setting fires the next cue only after the current one finishes. If you make the first cue longer, the next one still follows right after. It runs cues back to back from one press.", "purpose_function": "It chains cues so the next begins exactly when the previous one ends, keeping them seamless even if the first cue's duration is later edited.", "practical_application": "A technician sets auto-follow on a fade-out so the next track starts the instant the fade completes, with no manual GO and no gap.", "category": "Cue sequencing", "related_terms": ["Auto-continue", "Post-wait", "Pre-wait", "Cue sequence", "Go", "QLab"], "common_mistakes": ["Confusing auto-follow, which waits for the cue to finish, with auto-continue, which starts on a timer regardless of completion.", "Expecting a fixed delay; auto-follow timing changes automatically whenever the preceding cue's length changes.", "Using auto-follow on a looping or open-ended cue that never completes, so the next cue never fires."], "scenario_contexts": ["Starting the next music track the moment a fade-out finishes.", "Running a sequence of short effects seamlessly from a single GO.", "Triggering a lighting restore right after a video clip ends."]}, "ce5f59a6-85bc-4a8e-b032-2c61b27a3c3c": {"definition": "The unattended switching of a program or playback feed from a primary source or machine to a backup on detection of failure, silence, or loss of signal, so output continues without manual intervention. It is performed by a dedicated changeover/failover unit that monitors the main feed and cuts to a standby source; historically the term also names the automatic switch between two cinema projectors at reel-end.", "plain_english": "This is gear that switches to a backup on its own when the main source fails. If the main feed goes silent or dies, it cuts to the spare. Playback keeps going without anyone stepping in.", "purpose_function": "It protects a show or broadcast from dead air by detecting a source failure and switching to a backup automatically, faster and more reliably than a person could react.", "practical_application": "A technician wires a changeover unit to monitor the main playback machine and feed a standby machine, so audio continues if the primary drops out mid-show.", "category": "Playback redundancy", "related_terms": ["Backup playback system", "Failover", "Redundancy", "Silence detection", "Main/backup", "Playback"], "common_mistakes": ["Assuming the changeover unit fixes the fault; it only switches to the backup, so the failed primary source still needs repair.", "Never testing the changeover, so the backup source is misconfigured or silent when it is finally needed.", "Setting silence-detection thresholds so tight that quiet program passages trigger a false changeover."], "scenario_contexts": ["Switching to a backup playback machine when the main one loses signal mid-performance.", "A broadcast audio fail/changeover unit cutting to a standby feed to avoid dead air.", "Historically, an automatic device switching between two film projectors at reel changeover."]}, "243be111-7f45-41e9-a21e-2d4dbde8c395": {"definition": "A one-way loudspeaker announcement system that distributes the stage manager's or production's voice, and often a program/show-relay feed, to dressing rooms, corridors, green rooms, and backstage areas. It is used to call performers and crew and to relay the performance so they can track their cues, and is distinct from the two-way production intercom.", "plain_english": "This is the loudspeaker system that carries announcements backstage. The stage manager uses it to call actors from dressing rooms. It often also plays live show sound so people know when to get ready.", "purpose_function": "It lets one person reach everyone backstage at once with calls and show relay, so performers and crew are in the right place at the right time.", "practical_application": "A technician installs and checks paging speakers in dressing rooms and corridors so the stage manager's 'half-hour' and 'places' calls reach the whole company.", "category": "Communications", "related_terms": ["Backstage paging microphone", "Show relay", "Program feed", "Production intercom", "Stage manager", "Places call"], "common_mistakes": ["Confusing paging, which is one-way announcements and show relay, with intercom, which is two-way headset comms between operators.", "Setting paging speakers so loud they bleed onto open stage microphones or into the auditorium.", "Forgetting to feed show relay to remote areas, so performers miss their entrance cues."], "scenario_contexts": ["Calling 'the half' and 'places, please' to dressing rooms before curtain.", "Relaying the live show audio to green rooms so actors can follow the act.", "Paging a specific crew member to report to the stage-management desk."]}, "df78f63d-547c-4169-94c4-3473a5409e4e": {"definition": "The dedicated microphone, typically at the stage manager's desk or prompt corner, used to make voice announcements over the backstage paging (one-way loudspeaker) system, routing the speaker's voice to dressing rooms, corridors, and backstage areas. It is usually a push-to-talk microphone that overrides or ducks any show-relay program carried on the paging channel.", "plain_english": "This is the mic the stage manager talks into to make backstage announcements. Pressing its button sends the voice to speakers in dressing rooms and halls. It usually lowers the show sound while someone speaks.", "purpose_function": "It gives the stage manager a single point to address the whole backstage at once, taking priority over the paging system's show-relay feed.", "practical_application": "A technician sets up the paging microphone at the SM desk, checks its push-to-talk and its ducking of program, then confirms calls are clear in every backstage area.", "category": "Communications", "related_terms": ["Backstage paging", "Show relay", "Production intercom", "Push-to-talk", "Stage manager", "Prompt corner"], "common_mistakes": ["Leaving the paging microphone open rather than push-to-talk, so backstage noise and private talk go out over the speakers.", "Placing it where it picks up monitor or stage spill, making calls hard to understand.", "Assuming it feeds intercom headsets; it feeds the one-way paging speakers, not the two-way comms."], "scenario_contexts": ["Making time calls and 'places' announcements from the stage-management desk.", "Paging an individual performer to the stage during a scene change.", "Overriding the show-relay feed to give an urgent instruction backstage."]}, "de5389cd-5132-4a6f-9b42-e14068af5586": {"definition": "A redundant, standby playback rig, such as a duplicate computer running mirrored playback software, media player, or deck, kept ready to take over from the primary playback system so audio/video cues continue if the main system fails. It may run in hot standby, mirrored and tracking cues in real time, or be manually switched in, and is a core element of show-playback redundancy.", "plain_english": "This is a spare playback setup that takes over if the main one crashes. It often mirrors the main computer so both stay on the same cue. If the primary dies mid-show, the backup keeps the cues running.", "purpose_function": "It removes a single point of failure in playback, so a crash or hardware fault does not stop the show's sound and video cues.", "practical_application": "A technician runs a second QLab machine mirrored to the main one, plus a switch to change outputs, so playback continues if the primary computer fails during a performance.", "category": "Playback redundancy", "related_terms": ["Automatic changeover", "Redundancy", "Failover", "QLab", "Main/backup", "Playback"], "common_mistakes": ["Assuming a backup helps even when out of sync; a standby stuck on the wrong cue cannot seamlessly take over.", "Never rehearsing the switchover, so the crossover to the backup is slow or wrong under pressure.", "Sharing one power feed or one drive between main and backup, recreating a single point of failure."], "scenario_contexts": ["Mirroring a second QLab computer so it tracks every cue on the primary.", "Switching playback outputs to the backup rig when the main computer freezes mid-show.", "Testing the backup during tech to confirm it can take over cleanly."]}, "cd748578-8169-40a0-a43c-106114ecfd7a": {"definition": "A body-worn intercom user station, clipped to a belt or worn on a strap, that connects a headset to a production intercom (party-line or digital/matrix) system, giving the wearer talk and listen on one or more channels. It provides a microphone/sidetone level control, channel talk buttons, and often a call signal; examples include Clear-Com and RTS party-line and digital wireless beltpacks.", "plain_english": "This is a small intercom box worn on your belt. You plug a headset into it to talk and listen to the crew. Buttons and a knob let you pick channels and set your volume.", "purpose_function": "It gives each crew member a portable connection to the intercom so the team can coordinate cues and moves during setup and the performance.", "practical_application": "A technician clips on a beltpack, plugs in a headset, selects the stage manager's channel, and sets the level before a comms check.", "category": "Communications", "related_terms": ["Production intercom", "Party-line", "Headset", "Base station", "Wireless intercom", "Call signal"], "common_mistakes": ["Confusing a beltpack, a user station, with the main station or power supply that drives the party line.", "Latching the beltpack's talk button and forgetting it, so private conversation goes out to the whole channel.", "On an analog party-line, adding beltpacks beyond the power supply's rating, causing weak or noisy comms."], "scenario_contexts": ["Issuing beltpacks and headsets to the lighting, sound, and fly crews before a show.", "Selecting the correct intercom channel on a beltpack during a comms check.", "Using a wireless beltpack so a followspot or deck crew can move freely."]}, "18a41a7f-1093-4c33-9b05-9096a87ab8c2": {"definition": "A spoken safety warning called out on deck or backstage when someone is running or pulling a cable through a shared space, alerting others to the cable so they yield to it and avoid tripping over, snagging, or unplugging the run.", "plain_english": "This is a shout used backstage. It means someone is pulling a cable through the area. Everyone should look and step aside. It stops people tripping or knocking the cable loose.", "purpose_function": "It warns people in a busy, often dark space that a cable is being moved, so it prevents trips, falls, snagged connectors, and lost signal during setup or a show.", "practical_application": "A stagehand or audio tech shouts it while feeding a snake or mic cable across a crossover, so crew and performers make way and protect the run.", "category": "Backstage callout", "related_terms": ["Clear the path", "Cable management", "Crossover", "Snake", "Deck", "Cable ramp"], "common_mistakes": ["Assuming everyone heard the warning in a noisy room, then pulling the cable before people have actually cleared.", "UNSAFE: running a cable across a walkway or fire exit without matting or taping it down, leaving a trip hazard once the call is forgotten.", "Pulling the cable hard and snagging it, which can yank a connector loose or drag a device off a table."], "scenario_contexts": ["Feeding a multicore snake from the stage to front-of-house across a shared backstage corridor.", "Running a temporary mic cable through the wings during a quick changeover.", "Pulling a power or DMX line through a crowded pit before a show."]}, "7d5bda6e-1db5-40e4-b032-7cc33cf03eb8": {"definition": "An indicator lamp or LED on an intercom station or beltpack that lights or flashes when a call signal is received, used to get the attention of a user whose headset is off or who is working in a noisy area.", "plain_english": "This is a small light on a headset intercom station. It turns on or flashes when someone wants to reach you. You can see it even with your headset off. Then you put the headset on to talk.", "purpose_function": "It gives a visual alert so a crew member notices an incoming call when they cannot hear the intercom, which keeps everyone reachable during a show.", "practical_application": "A tech glances for the flashing call light on a beltpack or wall station, then puts on the headset to answer the stage manager or another operator.", "category": "Intercom", "related_terms": ["Call signal", "Party-line intercom", "Beltpack", "Cans", "Talkback", "Cue light"], "common_mistakes": ["Confusing the call light, which is an attention alert, with a cue light, which signals a standby or a GO.", "Not noticing the flashing light when the headset is off, so calls go unanswered.", "Assuming the call light means an emergency; it simply means someone wants your attention on comms."], "scenario_contexts": ["A follow-spot operator sees the call light flash and puts on cans to hear the stage manager.", "A stagehand with the headset around the neck notices the call light during a scene change.", "Testing beltpacks before a show to confirm each call light lights when the call button is pressed."]}, "abdeb8c0-eb26-43e2-8f41-ad091f0c637f": {"definition": "In a party-line intercom, a signal sent by pressing a call button that alerts users at other stations, shown by a flashing lamp or LED and sometimes an audible tone; it travels silently through the intercom wiring and can also trigger external devices such as flashers or relays.", "plain_english": "This is a way to get attention on a headset intercom. You press a call button. A light flashes at the other stations, and sometimes a tone sounds. It works even when someone has taken their headset off.", "purpose_function": "It lets one operator alert others when voice alone will not reach them, such as when a headset is off or the room is loud, so no one misses important comms.", "practical_application": "The stage manager presses call to flash the call lights and get a distracted or unplugged crew member back on headset before a cue.", "category": "Intercom", "related_terms": ["Call light", "Party-line intercom", "Beltpack", "Main station", "Tone alert", "Cans"], "common_mistakes": ["Thinking the call signal carries voice; it only flags attention, so you still must talk once the person is on cans.", "Leaning on the call button as a general signal instead of using clear voice callouts and cue lights.", "Forgetting that some call signals also fire relays or flashers, so pressing call may trigger other gear."], "scenario_contexts": ["Sending a call signal to summon a crew member who has removed their headset during a long scene.", "Using call to flash a signal light in a loud loading area where speech is drowned out.", "Wiring a call signal to a strobe or relay to alert a booth through a soundproof window."]}, "189e9815-ddb4-491d-b266-4ffa9750d66c": {"definition": "Communication over the production intercom that is kept clear and disciplined—brief, intelligible, and free of non-essential chatter—so that standbys, cues, and safety calls get through without confusion or delay.", "plain_english": "This means keeping talk on the headset system short and clear. Crew stay off the line unless they need it. That way important cues and warnings are not missed. Good habits keep the channel useful for everyone.", "purpose_function": "It keeps the intercom usable during a fast, high-pressure show by cutting crosstalk and clutter, so the stage manager's standbys and GOs are heard clearly.", "practical_application": "Crew keep non-essential talk off cans and use short, standard callouts, so the channel stays clear for cues and emergencies.", "category": "Comms discipline", "related_terms": ["Party-line intercom", "Cans", "Standby", "Call signal", "Talkback", "Quiet on cans"], "common_mistakes": ["Treating the intercom as a social channel and filling it with chatter that buries real cues.", "Leaving a talk button latched on, so background noise blocks the channel for everyone.", "Speaking over a standby or a GO instead of waiting for the channel to be clear."], "scenario_contexts": ["A stage manager asking for quiet on cans so the channel is clear before a tricky cue sequence.", "Briefing new crew on keeping comms clear and using standard callouts.", "Clearing chatter off the line during an emergency so safety instructions are heard."]}, "567c658e-379d-4855-b580-d86901f1db03": {"definition": "A spoken instruction or warning to keep a route—such as a crossover, wing, exit, or loading path—free of people, cases, cables, and other obstructions so performers, crew, scenery, or equipment can move through safely, especially in low light.", "plain_english": "This is a call to keep a walkway clear. People, cases, and cables must be moved out of the way. It lets performers or crew pass safely. It matters most in the dark backstage.", "purpose_function": "It prevents collisions, trips, and blocked exits by making sure a needed route stays open before someone or something moves through it.", "practical_application": "A stagehand calls it before wheeling a heavy set piece through the wings, so people and gear are cleared from the route first.", "category": "Backstage callout", "related_terms": ["Cable coming through", "Crossover", "Wings", "Egress", "Blackout", "Deck"], "common_mistakes": ["UNSAFE: blocking or narrowing a marked fire exit or egress route with cases or cable, which must be kept clear at all times.", "Calling to clear the path but moving the load before people have actually stepped aside.", "Leaving cables or props in a dark crossover, which creates trip hazards during a scene change."], "scenario_contexts": ["Moving a large rolling platform through the wings during a blackout.", "Clearing a crossover so an actor can make a fast entrance on the far side.", "Keeping a loading path open while striking gear after the show."]}, "99ce5690-6ff9-4637-adb6-2a4c7175c81c": {"definition": "A comms confirmation, common in live sound and broadcast, that permission is granted to send audio through the system—for example to run test noise, ring out monitors, or begin soundcheck—confirming that no one is working on the loudspeakers, amplifiers, or rigging and that crew are ready for sudden sound.", "plain_english": "This means it is now okay to send sound through the speakers. The engineer first checks that no one is working on the gear. It warns people a loud test or soundcheck is coming. That protects ears and avoids surprises.", "purpose_function": "It coordinates the moment sound starts, so people near speakers are warned, no one is mid-repair, and a sudden high level does not startle crew or harm hearing.", "practical_application": "Before running pink noise or starting soundcheck, the engineer asks 'clear to make noise?' on comms and waits for the all-clear.", "category": "Comms callout", "related_terms": ["Clear to mute", "Soundcheck", "Pink noise", "Ring out", "Line check", "Talkback"], "common_mistakes": ["UNSAFE: sending full-level test noise without confirming clear and warning anyone near the speakers, since sudden high sound can harm hearing and startle crew on ladders.", "Assuming silence on comms means clear; wait for an explicit all-clear before making noise.", "Starting soundcheck while a tech is still working on an amp or a speaker, risking loud sound close to their ears."], "scenario_contexts": ["Confirming clear before ringing out stage monitors, so a tech at the amp rack is not caught off guard.", "Checking clear to make noise before firing pink noise through a newly rigged PA.", "Coordinating on comms so a loud line check does not surprise crew still on the deck."]}, "c0d4ec70-1ef9-4985-89fe-e7910786c046": {"definition": "A comms confirmation that permission is granted to mute a channel, group, or the whole system—for example muting the PA between acts or a source that is no longer needed—verifying the mute will not cut audio that is still required for the show.", "plain_english": "This means it is now okay to turn off, or mute, some sound. The engineer first checks that nothing needed will be lost. Then they mute the channel or system. It avoids cutting audio at the wrong moment.", "purpose_function": "It coordinates muting so a source or the whole PA is silenced only when it is safe, which avoids losing audio the audience or performers still need.", "practical_application": "A monitor engineer asks 'clear to mute?' before muting a vocal channel during a break, confirming the singer is done and no cue depends on it.", "category": "Comms callout", "related_terms": ["Clear to make noise", "Mute", "Cut", "Standby", "Talkback", "Monitor mix"], "common_mistakes": ["Muting a channel or the main system before getting the all-clear, which can cut audio that was still cued.", "Confusing a temporary mute with a full shutdown; muting silences audio but leaves the system live.", "Forgetting to un-mute after a break, so the source is dead when it is next needed."], "scenario_contexts": ["Confirming clear to mute the PA during an interval, so house music can take over.", "Muting a spare radio mic once a scene ends, after checking no later cue uses it.", "Silencing a noisy channel during a talk, once the operator confirms it is clear to mute."]}, "69939384-3565-4694-b926-bb7147dc8854": {"definition": "A manufacturer of professional intercom (crew communications) systems, and by extension the party-line intercom equipment used to coordinate technical teams in live production, broadcast, film, and theatre. Clear-Com analog party-line systems carry full-duplex hands-free voice over two-conductor shielded cable, using a central main station that supplies DC power and channel termination together with distributed beltpacks, headsets, and speaker stations; digital and IP-based families (such as HelixNet and Arcadia) extend the same party-line topology.", "plain_english": "Clear-Com is a maker of headset intercom systems for live shows. Crew members wear belt packs and headsets so they can all talk and listen at once while a show runs.", "purpose_function": "It exists to give a whole production team one shared, hands-free voice circuit so the stage manager, operators, and crew can cue and coordinate a show in real time. Its distributed-amplifier design keeps each user's audio level steady as beltpacks join or leave the line.", "practical_application": "A technician connects beltpacks and headsets to party-line channels, sets talk, listen, and call functions, and troubleshoots faults such as cable breaks, sidetone, or missing line termination. Crew members use it to receive standby and go cues from the stage manager and to confirm actions during the show.", "category": "Intercom Systems", "related_terms": ["Partyline intercom", "Beltpack", "IFB (Interruptible Foldback)", "RTS", "Two-wire intercom", "Four-wire intercom"], "common_mistakes": ["Treating Clear-Com as one device rather than a brand spanning analog, digital, and IP intercom families.", "Failing to terminate the party-line at the main station, which makes levels and audio shift as stations connect or disconnect.", "Assuming two-wire and four-wire ports interconnect directly without a proper interface and nulling adjustment.", "UNSAFE: Driving very low-impedance headphones without a capable amplifier, risking distortion and hearing damage at high listening levels."], "scenario_contexts": ["A stage manager calls standby and go cues to lighting, sound, and fly crew over a Clear-Com party-line channel.", "A camera operator on a broadcast takes coordination on one channel while monitoring program audio.", "A crew chief runs heavier-gauge cable for a long party-line run and terminates it at the main station to keep levels stable.", "During load-in, an audio assistant patches beltpacks and headsets and checks each channel for clear communication."]}, "ac8486b9-a960-4496-bb0d-794d945ed4de": {"definition": "In show and music playback, the metronome pulse (click track) delivered as a dedicated audio stem, kept separate from the music, vocal, and effects stems. It is routed only to performers' monitoring paths, such as in-ear monitors or the musical director's foldback, so the ensemble stays locked to tempo with backing tracks or timecode-driven playback, and it is deliberately excluded from the front-of-house mix.", "plain_english": "A click stem is the metronome beat sent out as its own separate track. Musicians hear it in their earpieces to stay in time with backing tracks, but the audience never hears it.", "purpose_function": "It exists to feed a steady tempo reference to performers separately from the music, so the click can be kept out of the audience mix. Keeping it as its own stem lets the engineer control its level and routing independently of the other tracks.", "practical_application": "A playback or monitor engineer routes the click stem to in-ear monitors and to the drummer's or musical director's foldback, and confirms it is not present on the front-of-house send. During line check they verify the click is heard in monitors only.", "category": "Show Playback", "related_terms": ["Click track", "Stem", "Timecode", "In-ear monitors (IEM)", "Backing track", "Foldback"], "common_mistakes": ["Routing the click stem to the front-of-house mix, so the audience hears the metronome.", "Confusing a click stem with a full backing track; the click is only the tempo pulse, not the music.", "Failing to send the click to every performer who needs it, leaving some players without a tempo reference."], "scenario_contexts": ["A musical's playback rig sends the click stem to the pit and cast in-ears while backing tracks run to the house.", "A touring band's drummer takes the click stem in one ear to stay locked to sequenced tracks.", "An engineer builds a playback session with separate music, vocal, and click stems so each can be routed independently."]}, "471a3aed-018f-4ae4-9453-2d271bd5bec0": {"definition": "In multitrack playback and click-track systems, the count stem is the discrete audio stem (a routed submix track) that carries a recorded spoken count-in—such as 'one, two, three, four'—fed to performers' in-ear monitors to set the tempo and mark the exact start of a song or section. It is one of several stems, alongside the click, guide/cue, and backing stems, that make up a playback rig's output.", "plain_english": "A count stem is a playback track that plays a spoken count-in. It says something like 'one, two, three, four' before a song. The band hears it in their earpieces. This sets the speed and tells them when to start.", "purpose_function": "It gives musicians a clear, on-tempo count-in so a whole band or worship team starts a click-driven song together, locked to the backing tracks and click.", "practical_application": "A playback operator routes the count stem only to the performers' in-ear monitor mix, keeping it out of the front-of-house feed so the audience never hears the count.", "category": "Playback", "related_terms": ["Click track", "Guide track", "In-ear monitor", "Stem", "Count-in", "Playback"], "common_mistakes": ["Sending the count stem to the front-of-house mix, so the audience hears the spoken count before the song.", "Confusing the count stem with the click stem; the count is a spoken lead-in, while the click is the ongoing metronome pulse.", "Forgetting to include the count-in when building a track, leaving the band with no cue to start together."], "scenario_contexts": ["A worship band on in-ears relies on the count stem to start a click-driven song in unison.", "A musical director records a spoken count-in as its own stem so tempo is set before the downbeat.", "A playback operator patches the count stem into the monitor console but excludes it from the house mix."]}, "fe6f6d48-4293-42e8-b2ce-bccd9db471ea": {"definition": "A cue cart is a QLab layout that arranges cues in a clickable grid, ranging from a single cell up to fifteen rows by fifteen columns, where selecting a cell triggers the cue held in it. Because a cart keeps no playhead and imposes no running order, an operator can fire its cues one at a time in any sequence and repeat them freely; a cart also cannot chain cues onward, so it offers no auto-continue or auto-follow.", "plain_english": "A cue cart is a grid of buttons in show software. Each button plays one cue when you click it. You can press them in any order. It works like a soundboard of clips for unplanned moments.", "purpose_function": "It lets an operator fire cues on the fly in any order, which suits improvised or unpredictable moments where a strict top-to-bottom cue list would be too rigid.", "practical_application": "An operator builds a cue cart of sound effects or music beds and clicks cells live to respond to improvised action, audience interaction, or a host's ad-libs.", "category": "Cue organization", "related_terms": ["Cue list", "Cue", "Cue trigger", "Cue number", "Hotkey"], "common_mistakes": ["Expecting cues in a cart to auto-continue or auto-follow; a cart has no playhead, so each cue must be fired individually.", "Trying to place a Group cue in a cart, which QLab does not allow.", "Using a cart when a fixed, sequential cue list would be safer for a tightly scripted show."], "scenario_contexts": ["An operator fires ad-lib sound effects from a cue cart during an improv comedy set.", "A cart of music beds lets an operator jump between tracks in any order at a corporate event.", "A cart of stingers and buttons supports a game-show host's unpredictable timing."]}, "8513708c-f547-4d15-bef9-ab39f8e7176a": {"definition": "A cue label is an alphanumeric name or description attached to a cue (or cue part) in addition to its cue number, used to identify what the cue does—for example 'House to Half' or 'Blackout.' On consoles such as ETC Eos it is entered with the [Label] key and appears next to the cue in the cue list and on playback displays.", "plain_english": "A cue label is a short name you give a cue. The number sets the order; the label says what the cue does. For example, a cue might be labeled 'Blackout.' It helps the operator find the right cue fast.", "purpose_function": "It makes cues human-readable so an operator or stage manager can recognise a cue's content at a glance, rather than relying on the number alone.", "practical_application": "A programmer labels each cue during tech—'Sunrise,' 'Door Slam SFX,' 'House Out'—so the running crew can follow the show and troubleshoot quickly.", "category": "Cue attribute", "related_terms": ["Cue number", "Cue list", "Cue", "Cue sequence", "Cue trigger"], "common_mistakes": ["Leaving cues unlabeled, so the operator must guess each cue's purpose from its number alone.", "Confusing the cue label with the cue number; the number sets order, and the label only describes content.", "Writing vague labels that do not say what the cue actually does."], "scenario_contexts": ["A lighting programmer labels cues on an ETC Eos console during a tech rehearsal.", "A stage manager reads cue labels to confirm the next look before calling 'go.'", "A relief operator uses labels to learn an unfamiliar show file quickly."]}, "404955b7-7c2e-433c-8ecb-cf5d483aabfe": {"definition": "A cue light is a hardwired or networked signalling device that gives a performer or technician a silent, visual cue. The stage manager sends a warning/standby (commonly a red light, often flashing until acknowledged) and then a go (a green light, or in single-light systems the light switching off), run from a master station to remote outstations for cueing in noisy positions or where spoken cues on headset are impractical.", "plain_english": "A cue light is a light that tells someone exactly when to act. One color, or a flashing light, means 'get ready.' Then a change to green, or the light going out, means 'go now.' It works where it is too loud or too quiet to speak a cue.", "purpose_function": "It delivers a precise, silent go signal to people who cannot use or hear a headset, such as a performer waiting in the wings or a fly operator in a noisy position.", "practical_application": "The stage manager arms a warning light to put an operator on standby, then switches the go light at the exact cue point to trigger the action.", "category": "Cue-light system", "related_terms": ["Cue-light station", "Standby", "Go", "Stage manager", "Production intercom", "Outstation"], "common_mistakes": ["UNSAFE: Acting on a warning (standby) light as though it were the go, moving scenery or making an entrance before the go signal is given.", "Assuming every rig uses green-for-go; many single-light systems signal go by turning the light off.", "Failing to acknowledge the standby, so the stage manager does not know the operator is ready."], "scenario_contexts": ["A fly operator watches a cue light to time a scenery move over a loud musical number.", "A performer in a dark wing waits for the go light before making an entrance.", "A stage manager cues a pyrotechnic operator by cue light instead of a spoken headset cue."]}, "ef3b00f2-21a1-44f7-b7f7-aba3bec3cd6f": {"definition": "A cue list is an ordered, linear collection of cues—arranged top to bottom in the order they will run—through which a playhead advances each time a 'go' is given. It is the primary structure for running a show sequentially, whether in software such as QLab or on a lighting console, and a workspace or show file may hold several separate cue lists.", "plain_english": "A cue list is all the cues for a show, written in order. A marker called the playhead sits on the next cue. Each time the operator presses 'go,' that cue runs and the marker moves down. It works like a to-do list the show follows top to bottom.", "purpose_function": "It puts every cue in running order so an operator can step through a show one 'go' at a time, keeping cues reliable and repeatable across performances.", "practical_application": "An operator loads the cue list, keeps the playhead on the next cue, and presses 'go' on each line as the stage manager calls the show.", "category": "Cue organization", "related_terms": ["Cue", "Cue number", "Playhead", "Cue sequence", "Go", "Cue cart"], "common_mistakes": ["Losing track of the playhead, so pressing 'go' fires the wrong cue.", "Confusing a cue list with a cue cart; a list runs in fixed order through a playhead, while a cart fires cues in any order.", "Editing cue order during a run without moving the playhead, causing a mis-fire."], "scenario_contexts": ["A sound operator runs a play from a single QLab cue list, pressing 'go' on each line.", "A lighting programmer builds the main cue list during tech so the show runs top to bottom.", "A stage manager calls cues by number from the same cue list the operators are following."]}, "139828d7-5efb-43f8-bcb8-8aa091e65aa1": {"definition": "A cue number is the identifier assigned to a cue that sets its position and order within a cue list, and by which it is called and recalled—for example 'Cue 12' or 'LX 145.5.' Numbers are usually whole numbers but can be decimal, so intermediate cues (such as 12.5) can be inserted between existing cues without renumbering the whole list.", "plain_english": "A cue number is the label that gives each cue its place in line. Cues usually count up, like 1, 2, 3. You can also add a cue in between, such as 2.5. That way you insert a new cue without renumbering the rest.", "purpose_function": "It gives every cue a unique place in the running order so the stage manager can call it and the operator can find and fire the right cue.", "practical_application": "When a new moment is added mid-show, a programmer inserts a decimal cue such as 101.5 between cues 101 and 102 instead of renumbering everything.", "category": "Cue attribute", "related_terms": ["Cue", "Cue list", "Cue label", "Cue sequence", "Standby"], "common_mistakes": ["Renumbering a whole cue list mid-production, which breaks the stage manager's called script and everyone's paperwork.", "Confusing the cue number, which sets order, with the cue label, which only describes the cue.", "Assuming cue numbers must be whole numbers, forgetting that decimals let you insert cues between existing ones."], "scenario_contexts": ["A stage manager calls 'Standby LX 45, Sound 45' by cue number over headset.", "A programmer inserts cue 45.5 to add a look between two existing cues.", "An operator confirms the playhead is on the correct cue number before pressing 'go.'"]}, "9c904d25-a690-4485-b341-24bfc15dfea0": {"definition": "A cue sequence is two or more cues started from a single trigger—one button press, or one incoming MIDI/MSC/OSC command or hotkey—so that firing the first cue automatically runs the others. In QLab this is built with auto-continue (the next cue starts after the first cue's post-wait) or auto-follow (the next cue starts once the first cue finishes).", "plain_english": "A cue sequence is a group of cues that run from one 'go.' You press the button once, and the cues fire in order on their own. It works like a row of dominoes: tip the first, and the rest follow. This links actions such as a light change and a sound.", "purpose_function": "It chains related cues so a single trigger runs a whole moment—say a lighting change, a sound effect, and a video start—reliably and in step every time.", "practical_application": "A programmer sets a sound cue to auto-follow a light cue so both fire from one 'go,' keeping a thunderclap locked to the lightning flash.", "category": "Cue structure", "related_terms": ["Cue list", "Auto-follow", "Auto-continue", "Cue trigger", "Cue", "Cue number"], "common_mistakes": ["Mixing up auto-continue and auto-follow; auto-continue times off the first cue's post-wait, while auto-follow waits for the cue to finish.", "Building a long auto-continue chain and losing track of which single 'go' starts the whole sequence.", "Expecting a cue cart to run sequences; cues in a cart cannot auto-continue or auto-follow."], "scenario_contexts": ["A designer links a lightning flash cue and a thunder sound cue into one sequence.", "An operator fires a scene change as a single sequence of light, sound, and automation cues.", "A programmer uses auto-follow so a fade-out cue starts only after the preceding cue completes."]}, "a1e98cd4-59bf-4f11-a9cb-ef0eeea30df7": {"definition": "A cue trigger is the event that causes a cue to start. It may be a manual 'go,' or an automatic source such as a hotkey, an incoming MIDI or MIDI Show Control message, an OSC command, SMPTE timecode, or wall-clock time. Triggers let cues be run on cue by an operator or be slaved to another system without a person pressing 'go.'", "plain_english": "A cue trigger is whatever makes a cue start. It can be a person pressing 'go.' It can also be an automatic signal, like a timecode or a message from another machine. Think of it as the starting gun for a cue.", "purpose_function": "It defines how each cue starts, so cues can be run by hand or fired automatically in sync with music, video, or another control system.", "practical_application": "An operator assigns SMPTE timecode as the trigger so cues fire in sync with a playback track, or a MIDI Show Control message so a lighting console starts QLab.", "category": "Cue triggering", "related_terms": ["Cue sequence", "MIDI Show Control", "Timecode", "OSC", "Go", "Hotkey"], "common_mistakes": ["Leaving a stray trigger (such as a hotkey or MIDI note) assigned, so a cue fires unexpectedly.", "Confusing the trigger, which starts a cue, with the cue's own action or contents.", "Relying on timecode triggers with no manual 'go' backup if the timecode source fails."], "scenario_contexts": ["A festival rig triggers lighting and video cues from SMPTE timecode locked to the band's playback.", "A lighting console sends a MIDI Show Control message to trigger a QLab sound cue.", "An operator sets a hotkey trigger so a stagehand can fire a cue from a laptop offstage."]}, "95bf03ff-4d53-42da-89b6-0a511c1e3238": {"definition": "A cue-light station is a single position in a cue-light system—either the master station at the stage manager's desk, from which cues are sent, or a remote outstation at an operator or performer position, which displays the warning and go lights. An outstation typically carries the light(s) plus an acknowledge button so the recipient can confirm they are ready.", "plain_english": "A cue-light station is one spot in a cue-light system. The main station sits at the stage manager's desk, where cues are sent. A remote station sits where a crew member or performer works, and shows the lights. Many remote stations have a button to say 'I'm ready.'", "purpose_function": "It provides the physical send point or receive point for silent cues, letting the stage manager cue a specific position and letting that position acknowledge readiness.", "practical_application": "A technician installs an outstation at a fly rail or trap and runs it back to the master station so the stage manager can cue that position silently.", "category": "Cue-light system", "related_terms": ["Cue light", "Master station", "Outstation", "Standby", "Stage manager", "Production intercom"], "common_mistakes": ["Confusing the master station, which sends cues, with an outstation, which receives and displays them.", "Not pressing the acknowledge button at the outstation, leaving the stage manager unsure the position is ready.", "Placing an outstation where its light is out of the operator's sightline during the cue."], "scenario_contexts": ["A stage manager sends a standby from the master station to a fly operator's outstation.", "A technician patches outstations at each wing entrance for silent performer cues.", "An operator presses the acknowledge button at their station to confirm they are standing by."]}, "e7258316-ead7-4633-ab7c-1434d255ca5d": {"definition": "A dedicated system of remotely controlled indicator lights, driven from the stage manager's prompt desk, that gives silent visual cues to performers and crew who cannot hear or acknowledge spoken calls. By convention a warning/standby indication (typically a red light) is sent first and the go indication (typically a green light) triggers the action; many systems flash the standby light and let the outstation acknowledge receipt before the go.", "plain_english": "A cue-light system sends silent light signals from the stage manager to the crew. A red light means get ready. A green light means go now. It works where people cannot hear spoken cues over the show.", "purpose_function": "It lets the stage manager cue actions silently and reliably at positions where headset talk is impractical or where noise, distance, or the need for silence rules out a verbal go.", "practical_application": "A technician runs cue-light cable to fly rails, traps, and entrances, then the stage manager arms a red standby and presses green to send the go for a scene change or entrance.", "category": "Cueing systems", "related_terms": ["Cue light", "Standby", "Go", "Prompt desk", "Production intercom", "Stage manager"], "common_mistakes": ["Treating the standby light as the go; the standby only warns, and the action happens on the separate go indication.", "Assuming a lit cue light was acknowledged; without a confirm-back feature the stage manager cannot be sure the operator saw it.", "Running cue-light cable in the same bundle as sensitive audio lines and inducing clicks, instead of separating or screening the runs."], "scenario_contexts": ["Cueing a fly operator to bring in a drop silently during an actor's quiet scene.", "Signalling a performer waiting in a dark wing to make an entrance on the green.", "Giving a standby then go to a trap operator who cannot wear a headset."]}, "65836245-6a4c-45bf-80b9-cb1346d46e7f": {"definition": "An intercom talk-and-listen channel on a production communications system that is assigned to the stage-deck crew—the stagehands, automation, and scene-change personnel working on the stage floor—keeping their traffic separate from other departments such as lighting, sound, and flies. It is one of the departmental channels of a partyline or matrix intercom system.", "plain_english": "A deck channel is one talk line on the backstage intercom. It is set aside for the stage-floor crew. They use it to plan and time scene changes together, without other departments talking over them.", "purpose_function": "It gives the deck crew a private conversation path so scene-change and automation coordination is not buried under lighting, sound, or fly-crew chatter on shared comms.", "practical_application": "A technician assigns the deck crew's beltpacks to the deck channel and confirms the stage manager can reach that channel to call standbys for shifts.", "category": "Production intercom", "related_terms": ["Production intercom", "Partyline", "Beltpack", "Channel", "Deck crew", "Stage manager"], "common_mistakes": ["Assigning deck beltpacks to the wrong channel, so the deck crew cannot hear the stage manager's shift calls.", "Confusing the deck channel, used by stage-floor crew, with the fly or lighting channels used by other departments.", "Putting every department on one channel, so the deck crew's cross-talk swamps critical show cues."], "scenario_contexts": ["Coordinating a fast furniture shift between deck hands during a blackout.", "Calling automation moves to the deck crew on their own intercom channel.", "Separating deck traffic from the sound channel so each department stays clear."]}, "8659a737-a07a-4f20-bf38-2a0a93fe51f3": {"definition": "A scare cue—a programmed cue that fires a startle effect such as a sudden sound, prop movement, light, or air blast—set to trigger after a deliberate time offset rather than instantly on its trigger. The delay, implemented as a cue pre-wait or timed follow in show-control software, times the effect to land a beat after the trigger or once the audience has reached a specific point.", "plain_english": "This is a scare effect set to fire after a short wait. The pause makes the scare land at the perfect moment. Show software adds a set delay before the effect plays, so the surprise hits when guests least expect it.", "purpose_function": "It exists so a startle effect can be timed precisely to a moment or a guest's position, using a delay instead of firing the instant the cue is triggered.", "practical_application": "A programmer sets a pre-wait on the scare cue in the show-control software so the bang or drop happens a moment after a sensor or operator triggers it.", "category": "Cue types", "related_terms": ["Cue", "Pre-wait", "Show control", "Trigger", "Auto-follow", "QLab"], "common_mistakes": ["Setting the delay so long the scare no longer connects to what triggered it, so it lands on an empty space.", "Confusing the pre-wait delay before a cue with the fade or duration of the effect itself.", "UNSAFE: Timing a startle effect near stairs, ledges, or moving scenery without assessing the fall or collision risk a sudden scare can cause."], "scenario_contexts": ["Delaying a sudden speaker hit until a walkthrough guest steps into a doorway.", "Programming a prop to jump a beat after an operator presses go, for better surprise.", "Setting a pre-wait so a scare fires only after a lighting change finishes."]}, "284aafd7-6baa-4cfe-90e9-d3ea0c70fefa": {"definition": "A stage-management announcement, given over backstage paging and intercom, stating that the auditorium (house) doors have been opened and the audience is being admitted to the seats. From this call onward, backstage discipline applies: the stage must not be crossed in the audience's view, noise is kept down, and the set and preset are treated as final.", "plain_english": "This call means the audience is now coming into the seats. From now on, the crew stays quiet and out of sight. No one crosses the stage where the audience can see.", "purpose_function": "It tells everyone backstage that the audience is present, so the crew switches to show-quiet discipline and stops any work visible or audible to the house.", "practical_application": "On hearing 'doors are open,' a technician stops onstage work, clears the deck of tools and cases, and finishes any remaining tasks out of the audience's sight and hearing.", "category": "Stage management calls", "related_terms": ["House open", "Preset", "Front of house", "Beginners", "Stage manager", "Paging"], "common_mistakes": ["Continuing to cross the open stage or make noise after the call, in full view or earshot of the arriving audience.", "Leaving tools, cases, or unfinished preset onstage once the house is admitted.", "Confusing 'doors are open' with the show start; the audience is seating, and the performance has not yet begun."], "scenario_contexts": ["The stage manager pages 'doors are open' once front of house confirms the audience may enter.", "A crew member abandons an onstage adjustment the moment the doors-open call is made.", "Backstage conversation drops to a whisper after the house is opened."]}, "d59828c6-4370-45a5-af59-39da1c872a93": {"definition": "A stage-management instruction to delay opening the house doors and keep the audience out of the auditorium beyond the planned admission time, usually because the stage, preset, or a technical or safety matter is not yet ready. Front of house holds the audience in the lobby until the stage manager clears the house to open.", "plain_english": "This means the audience is kept waiting outside a bit longer. The crew needs more time to get ready. Front-of-house staff hold the crowd until the stage manager says the house can open.", "purpose_function": "It buys the backstage team time to finish the preset or resolve a problem before the audience enters, preventing the house from opening onto an unready or unsafe stage.", "practical_application": "When a preset runs late, the stage manager calls a doors hold, front of house keeps the audience in the lobby, and the doors open only once the stage is cleared.", "category": "Stage management calls", "related_terms": ["House open", "Doors are open", "Front of house", "Preset", "Stage manager", "Hold"], "common_mistakes": ["Opening the doors on the scheduled time despite a hold, letting the audience see an unfinished stage.", "Failing to tell front of house the reason or expected length, so they cannot manage the waiting audience.", "Confusing a doors hold, which delays admitting the audience, with a hold during the show, which pauses the running performance."], "scenario_contexts": ["Holding the doors while the crew resets a scenic element that failed in the preset check.", "Delaying house open after a late safety inspection of the stage.", "Front of house keeping the audience in the lobby until the stage manager lifts the hold."]}, "13da1cd4-adb3-4fa2-b594-aabb1165c505": {"definition": "An intercom headset fitted with two earcups (one over each ear), also called a dual-ear or binaural headset, as distinct from a single-muff (single-ear) headset. The two enclosed earcups attenuate ambient noise and deliver the intercom signal to both ears, improving comms intelligibility in loud environments.", "plain_english": "This is an intercom headset that covers both ears. Two earcups block loud noise around you. That makes it easier to hear cues in a noisy backstage, pit, or arena.", "purpose_function": "It exists to keep intercom speech clear where ambient noise is high, by sealing both ears and feeding comms to both, at the cost of the user's awareness of live room sound.", "practical_application": "A technician issues double-muff headsets to crew working near loud sources such as the band or blowers, and single-muff sets to those who must also hear the stage.", "category": "Intercom hardware", "related_terms": ["Single-muff headset", "Headset", "Beltpack", "Production intercom", "Cans", "Microphone"], "common_mistakes": ["Giving a double-muff headset to someone who must also hear stage or verbal cues in the room, cutting their situational awareness.", "Confusing single-muff and double-muff sets; single-ear keeps one ear open to the room, dual-ear seals both.", "UNSAFE: Cranking headset volume to beat ambient noise for long periods; sustained high levels risk hearing damage, so follow OSHA 1910.95 and NIOSH exposure guidance."], "scenario_contexts": ["Wearing a double-muff headset at a monitor position beside a loud stage rig.", "Choosing dual-ear headsets for a pyro or automation operator in a noisy pit.", "Swapping to single-muff for a deck hand who needs to hear onstage action."]}, "379c2ba7-3fc4-4051-b1c2-ef30077f970f": {"definition": "A one-way audio distribution system that carries the stage manager's paging announcements and, usually, a live show-relay feed of the stage into the dressing rooms and other backstage areas. It lets performers and staff away from the stage hear their calls (such as 'Act 1 beginners') and follow the progress of the show so they are ready on time.", "plain_english": "This system pipes the stage manager's calls into the dressing rooms. It also plays live sound from the stage. Performers hear their calls and know when to head toward the stage.", "purpose_function": "It keeps performers and crew who are away from the stage informed of calls and of where the show has reached, so they arrive at the right place on cue.", "practical_application": "A technician installs and levels dressing-room speakers, then checks that both the stage manager's page and the show-relay feed are clear and audible in every room.", "category": "Paging systems", "related_terms": ["Show relay", "Paging", "Beginners", "Stage manager", "Backstage", "Program feed"], "common_mistakes": ["Setting dressing-room paging too quiet, so performers miss calls and are late to the stage.", "Confusing the one-way page and show relay with two-way intercom; dressing-room paging is listen-only.", "Feeding only music with no verbal calls, so performers cannot hear the stage manager's beginners call."], "scenario_contexts": ["Paging 'Act 2 beginners' from the prompt desk to all dressing rooms.", "Playing the live stage relay so a performer times their move to the stage.", "Checking every dressing-room speaker during a pre-show comms and paging test."]}, "51b655f3-4e89-460f-ab1a-01fd5162075e": {"definition": "An emergency stop device—a manually actuated control, typically a red mushroom-head button on a yellow background, that on operation immediately commands hazardous machinery such as powered hoists, automation, or moving scenery to a safe stopped state. Per emergency-stop standards it latches on actuation, must be reset by a deliberate manual action, and resetting it does not by itself restart the equipment.", "plain_english": "An E-stop is a big red emergency button. Hitting it instantly stops moving scenery or rigging. It stays locked in until someone safely resets it by hand. Even after reset, the machine will not start on its own.", "purpose_function": "It exists to let anyone halt dangerous motion instantly in an emergency, providing a reliable, always-available means to bring machinery to a safe stop and prevent injury.", "practical_application": "Before any automation or powered-hoist move, a technician confirms every E-stop is functional and reachable, and knows that pressing one halts all governed motion until it is reset and re-armed.", "category": "Machinery safety", "related_terms": ["Deadman", "Powered hoist", "Automation", "Interlock", "Rigging", "Show control"], "common_mistakes": ["UNSAFE: Treating the E-stop as a routine on/off or 'pause' control; it is an emergency device, and normal stops must use the standard controls.", "UNSAFE: Blocking, disabling, or failing to test E-stop buttons before a show, so a stop cannot be commanded when it is needed.", "Assuming resetting an E-stop restarts the move; per standard, restart requires a deliberate, separate start command."], "scenario_contexts": ["Slamming an E-stop when a performer strays into the path of a moving truck.", "Testing every E-stop station in an automation system during pre-show checks.", "Halting a powered flying move instantly when a line fouls."]}, "68602a68-ca22-4c89-b152-b95288bd802f": {"definition": "A stage-management call marking the conclusion of the performance—after the final cue, curtain call, and the audience's departure—at which running responsibilities close out and post-show procedures begin, such as clearing the stage, restoring safe states, securing equipment, and logging the show report. It signals the transition from running the show to shutting it down.", "plain_english": "This call marks the moment the performance is over. The stage manager uses it to close out the show. Crew then start their end-of-night jobs, like clearing the stage and shutting things down.", "purpose_function": "It marks the formal end of the running show so the team switches from show operation to safe shutdown, restoration, and reporting.", "practical_application": "At end of show, a technician powers down and secures equipment to a safe state, helps clear the stage, and notes any faults for the show report.", "category": "Stage management calls", "related_terms": ["Show report", "Curtain call", "Cue", "Stage manager", "Post-show", "House"], "common_mistakes": ["Powering down or clearing the stage before the audience has actually left, while the house is still occupied.", "Skipping the show report and safe-shutdown steps once the performance ends.", "Confusing the end of the last cue with end of show; the curtain call and audience exit still follow."], "scenario_contexts": ["The stage manager calls end of show once the house has cleared after curtain call.", "Crew begin post-show restore and secure of automation and rigging at end of show.", "Logging faults in the show report as part of end-of-show procedure."]}, "4a5e9859-a0e1-4955-bb84-3507281834ff": {"definition": "A single control action that simultaneously fades every currently active output - all channels, cues, or intensities - down to zero over a defined time rather than cutting them instantly. On lighting consoles it is the timed fade-to-black or grandmaster fade; in cue-playback software it is the equivalent 'fade and stop all' or panic action applied to every running cue.", "plain_english": "A fade-all command turns down every active output to zero at once. It happens over a set time, like a few seconds, not in a snap. Crews use it to end a scene smoothly or to clear everything.", "purpose_function": "It gives the operator one reliable way to bring an entire look or soundscape down together and on a controlled timing, whether to end a section cleanly or to recover from a problem without an abrupt cut.", "practical_application": "An operator triggers the fade-all to take a scene smoothly to black or silence at the end of an act, or uses it as a quick controlled all-off when something goes wrong mid-show.", "category": "Cueing Commands", "related_terms": ["Go cue", "Go button", "Blackout", "Grandmaster", "Fade time", "Panic"], "common_mistakes": ["Confusing a fade-all with a hard blackout; the fade-all ramps down over a time while a blackout snaps to zero", "Assuming a fade-all also stops or unloads the cues; on some systems it only takes levels to zero and cues may still be running", "Setting the fade time to zero by accident, so an intended smooth fade becomes an instant cut"], "scenario_contexts": ["Fading all lighting to black over five seconds at the end of an act", "Bringing every running sound cue down together at the top of an interval", "Using a controlled all-fade to recover cleanly when a cue misfires"]}, "1c96ea14-0727-469c-b780-39bcde58058a": {"definition": "A spoken time signal given by stage management to the company approximately five minutes before performers must be in position for the start of a performance or act. It is one of the standard sequence of calls - typically the half-hour, the fifteen (or quarter), the five, and finally 'places' - delivered backstage and to dressing rooms to keep the company on schedule.", "plain_english": "The five-minute call warns the cast that the show starts in about five minutes. Stage management says it out loud or over backstage speakers. It tells performers to finish getting ready and head toward their spots.", "purpose_function": "It keeps the whole company aware of how much time remains before the show begins, so performers and crew finish preparation and move toward their positions in an orderly way.", "practical_application": "The stage manager or assistant makes the five-minute call over the backstage paging system and to dressing rooms, usually adding 'thank you' and expecting an acknowledgement from the company.", "category": "Performance Calls", "related_terms": ["Half-hour call", "Places call", "Standby", "Paging system", "Stage manager", "Show relay"], "common_mistakes": ["Treating the five-minute call as the exact cue to begin; 'places' and then 'go' still follow it", "Assuming the standard call times are fixed everywhere; exact timings vary by house rule and union agreement", "Forgetting to page dressing rooms and other backstage areas, so some of the company misses the call"], "scenario_contexts": ["Calling 'five minutes, please' to the company before the top of the show", "Giving the five before an act resumes after an interval", "Paging the five-minute call to dressing rooms over the backstage system"]}, "1ea7fc1f-3def-408b-a0ba-5713af4cb204": {"definition": "An intercom circuit that carries the send (talk) and receive (listen) audio on two separate balanced line-level pairs, giving full-duplex communication with no shared path between directions. Unlike two-wire party-line, where both directions ride one line, four-wire keeps transmit and receive independent (Clear-Com specifies a nominal 0 dBu line level), which is how matrix intercom frames interconnect and interface to consoles, IFB, and telephone hybrids.", "plain_english": "A four-wire intercom uses separate paths to send your voice and hear others at the same time. One pair carries your voice out and the other brings sound in. This lets large talkback systems link together cleanly.", "purpose_function": "It separates the talk and listen paths so audio can flow both ways at once without crosstalk, which lets matrix intercom systems route each direction independently and connect reliably to other line-level audio equipment.", "practical_application": "A technician uses four-wire ports to link matrix intercom frames, to tie an intercom to a mixing console or IFB feed, or to interface a party-line channel through a two-wire-to-four-wire converter.", "category": "Intercom Systems", "related_terms": ["Two-wire intercom", "Party-line intercom", "Matrix intercom", "Full-duplex", "IFB", "Talkback"], "common_mistakes": ["Assuming 'four-wire' always means four physical conductors; it names two audio paths, which may be carried digitally or on other media", "Plugging a two-wire party-line device straight into a four-wire port without an interface, so it does not work", "Reversing the send and receive pairs, so operators can hear but not be heard, or the reverse"], "scenario_contexts": ["Linking two matrix intercom frames between control rooms", "Interfacing an intercom channel to a broadcast mixing console", "Converting a party-line channel to four-wire for a matrix system"]}, "3c4cf066-eb0e-496a-b0b3-f28cbd8b53f1": {"definition": "The control - a physical key, on-screen button, or remote trigger - that executes the cue currently standing by and advances the playhead to the next one. It is the primary run control on cueing consoles and playback software (for example the GO key on ETC Eos or the on-screen GO in QLab), and it can be fired remotely by a MIDI Show Control GO message.", "plain_english": "The Go button fires the next cue that is standing by. Press it and the console runs that step of the show. It is the main control an operator uses to move a show forward.", "purpose_function": "It gives the operator a single, consistent action to launch each pre-programmed cue at the right moment, so a complex sequence runs step by step under manual control.", "practical_application": "An operator watches or listens for the calling cue, then presses GO to run the standing cue; the same action can be sent between devices as an MSC GO so one console triggers another.", "category": "Cueing Controls", "related_terms": ["Go cue", "Standby", "Cue", "Playhead", "MIDI Show Control", "Fade-all command"], "common_mistakes": ["Pressing GO twice or too early, which runs the following cue before its time", "Assuming the Go button loads a specific cue; it fires whatever cue is currently standing by", "Forgetting that a stray MSC or remote GO can also fire the cue, causing an unexpected trigger"], "scenario_contexts": ["An operator pressing GO on each called cue during a performance", "Using a foot-switch or app as a remote GO for hands-free cueing", "A lighting console sending an MSC GO to trigger a sound cue in QLab"]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"ffc53324-2daa-4fb4-88c8-2c4ecd4c8932": {"definition": "The instruction that tells an operator or device to execute a cue at that exact instant - spoken by the person calling the show as the word 'Go', or sent electronically as a MIDI Show Control GO command. It always follows a standby (warning), and the action of the cue is timed to the 'Go', not to the standby.", "plain_english": "A go cue is the signal to make something happen right now. The person calling the show says 'Go' so an operator acts at the exact moment. It always comes after a warning called a standby.", "purpose_function": "It marks the precise moment a cue must fire, separating the warning to get ready from the trigger to act, so many departments hit their marks together at the right time.", "practical_application": "The stage manager gives a standby, then calls 'Sound one - GO' on the headset, and the operator fires the cue on the word; systems can send the same instruction as an MSC GO between devices.", "category": "Cueing Commands", "related_terms": ["Standby", "Go button", "Cue", "Calling the show", "MIDI Show Control", "Stage manager"], "common_mistakes": ["Acting on the standby instead of waiting for the 'Go', which fires the cue early", "Placing the emphasis wrong when calling, so the operator cannot tell exactly when 'Go' lands", "Confusing the go cue (the trigger to act) with the cue itself (the programmed action)"], "scenario_contexts": ["A stage manager calling 'Lights five, go' during a performance", "A console sending an MSC GO to fire the next cue on another device", "Timing a scene-change go so several departments move together"]}, "1ceee5ed-1e22-4b97-aea9-16628eadd15e": {"definition": "A spoken intercom response by which the audio operator acknowledges a call on the communications system and signals readiness to receive it - in effect 'audio is listening, go ahead'. It follows standard comms discipline of answering a hail with 'go for [position]', and in a readiness (go/no-go) check it also reports that the audio department is ready to proceed.", "plain_english": "'Go for audio' is how the sound operator answers a call on the headset. It means 'I hear you, go ahead.' It also tells the team that audio is ready.", "purpose_function": "It confirms on a shared intercom that the audio position has heard the call and is listening, keeping headset traffic clear and letting the caller know exactly who is responding and that audio is ready.", "practical_application": "When the director or stage manager calls 'Audio?' on comms, the operator answers 'Go for audio' before the message, and gives the same reply in a pre-show go/no-go check.", "category": "Communications Protocol", "related_terms": ["Intercom", "Party-line intercom", "Talkback", "Standby", "Go cue", "Comms discipline"], "common_mistakes": ["Starting to talk before hearing an acknowledgement, so the message is missed on a busy channel", "Reading 'go for audio' as a command to fire an audio cue rather than an acknowledgement to a call", "Forgetting to name the position, so on a shared channel no one knows who answered"], "scenario_contexts": ["Answering 'Go for audio' when the director hails audio on the headset", "Reporting audio ready during a pre-show go/no-go check", "Keeping intercom traffic clear during a live broadcast or event"]}, "26cbede1-b8b6-4323-be66-f2c49045b613": {"definition": "A talkback microphone at a control position - the FOH desk, booth, or director's table - whose output is routed over the room's main loudspeakers or monitors so one person can address everyone in the space at once. Also called the voice-of-God mic, it is used chiefly during rehearsals and tech to give notes and directions to performers and crew on stage.", "plain_english": "A god mic is a talkback microphone at the control desk. Its voice plays over the room's speakers so one person can talk to everyone. Directors use it to give notes during rehearsals.", "purpose_function": "It lets a director, musical director, or stage manager speak to the whole room from the control position without shouting or leaving the desk, making rehearsals and technical sessions faster to run.", "practical_application": "A technician patches a talkback mic at the control position to the PA or monitors and sets its level, so the person running the session can stop, note, and restart the cast at will.", "category": "Communication Systems", "related_terms": ["Talkback", "God microphone", "Public address", "Foldback", "Intercom", "Stage manager"], "common_mistakes": ["Leaving the god mic open, so private control-room talk is broadcast to the room", "Setting it far louder than the programme, startling performers when it cuts in", "Assuming it is the same as intercom; the god mic goes to the room's speakers, not to headsets"], "scenario_contexts": ["A director giving notes to the cast during a rehearsal", "A musical director counting a number in from the control position", "A stage manager addressing the stage during a technical rehearsal"]}, "859d4797-7a33-4f45-b884-fb8e1f798f9d": {"definition": "A talkback microphone at a control position - the FOH desk, booth, or director's table - whose output is routed over the room's main loudspeakers or monitors so one person can address everyone in the space at once. Commonly shortened to 'god mic' and also called the voice-of-God microphone, it is used chiefly during rehearsals and tech to give notes and directions to performers and crew on stage.", "plain_english": "A god microphone is a talkback mic at the control desk. Its voice plays over the room's speakers so one person can talk to everyone. Directors use it to give notes during rehearsals.", "purpose_function": "It lets a director, musical director, or stage manager speak to the whole room from the control position without shouting or leaving the desk, making rehearsals and technical sessions faster to run.", "practical_application": "A technician patches a talkback mic at the control position to the PA or monitors and sets its level, so the person running the session can stop, note, and restart the cast at will.", "category": "Communication Systems", "related_terms": ["God mic", "Talkback", "Public address", "Foldback", "Intercom", "Stage manager"], "common_mistakes": ["Leaving the god microphone open, so private control-room talk is broadcast to the room", "Setting it far louder than the programme, startling performers when it cuts in", "Assuming it is the same as intercom; the god microphone goes to the room's speakers, not to headsets"], "scenario_contexts": ["A director giving notes to the cast during a rehearsal", "A musical director counting a number in from the control position", "A stage manager addressing the stage during a technical rehearsal"]}, "789c8c09-7793-4cc3-996e-070ce5d792ec": {"definition": "A stage manager's verbal warning, called over the backstage paging or comms system and often to the company, announcing that the performance is about to begin—historically that the front curtain is about to rise. It signals the transition from pre-show to the live top of show, telling all departments and cast to take their opening positions and go quiet.", "plain_english": "\"Going up\" is the call that warns everyone the show is about to start. It means the curtain is about to rise. Cast and crew take their opening spots and get quiet.", "purpose_function": "It gives the whole company one clear signal that the show is starting now, so cast and crew reach their opening positions and go quiet together.", "practical_application": "A technician at a backstage or comms station hears \"going up,\" stops pre-show tasks, clears the deck, and stands ready at their first cue.", "category": "Stage management calls", "related_terms": ["Places", "Standby", "Go", "Top of show", "Stage manager", "Hold the show"], "common_mistakes": ["Treating 'going up' as the actual GO for a cue; it is a general warning that the show is starting, not an executable cue.", "Continuing noisy pre-show work or conversation after the call instead of clearing the stage and going quiet.", "Ignoring the call because you have no early cue; every department is expected to be at opening positions once 'going up' is given."], "scenario_contexts": ["A stage manager calls 'going up' over comms once the house is set and the stage is cleared to start.", "Backstage crew hearing 'going up' take their opening positions and switch off worklights.", "The stage manager warns 'going up in two minutes' so late cast reach the wings in time."]}, "c999af9f-df4b-4621-a81e-fc0c53b436b5": {"definition": "A control event fired by the state change of a General Purpose Input/Output (GPIO) line—typically a dry contact closure or logic-level signal—used to start or advance a cue or action between show-control devices. A General Purpose Input (GPI) reads an external closure to trigger an action on the device, while a General Purpose Output (GPO) closes a contact or relay to trigger downstream equipment.", "plain_english": "GPIO stands for General Purpose Input/Output. A GPIO trigger is a simple on/off electrical signal that starts an action. Think of it like a doorbell button: pressing it tells another device to go. Show gear uses it to fire cues.", "purpose_function": "It lets separate devices start each other's cues using a simple, reliable contact closure, without needing a shared network protocol or a manual button press.", "practical_application": "A technician wires a button, sensor, or relay to a device's GPI port so an external action fires a cue, or patches a GPO to trigger a relay, lamp, or another machine.", "category": "Show control", "related_terms": ["Contact closure", "MIDI Show Control", "Cue", "Show control", "Relay", "Timecode"], "common_mistakes": ["Confusing a GPI (input that receives a closure to trigger this device) with a GPO (output that closes a contact to trigger another device).", "Assuming every GPIO input supplies its own voltage; many expect a dry, voltage-free contact and can be damaged by an applied voltage.", "UNSAFE: Wiring mains or other high voltage to a low-voltage GPIO or contact input, which can destroy the device and create a shock hazard."], "scenario_contexts": ["A push button wired to a media server's GPI fires an effect cue on demand.", "A show controller closes a GPO relay to trigger a lighting console GO or a safe external device.", "A door sensor's contact closure triggers an audio cue as guests enter a themed room."]}, "6f772b27-1371-4685-a204-f6ea9aa80fbc": {"definition": "In a theatrical cue-light system, the green lamp that signals GO—the moment for an operator or performer to execute their action—as distinct from the red lamp that signals standby/warning. The stage manager switches the green light on at the cue point, after the standby has been given and acknowledged.", "plain_english": "A cue light is a signal light used instead of a spoken cue. The green light means go, do it now. It usually follows a red standby light that warns you to get ready. It lets people take cues silently.", "purpose_function": "It gives a silent, unmistakable GO signal to crew or performers who cannot hear, or should not hear, a spoken cue in noisy or quiet-critical moments.", "practical_application": "An operator watches the cue light: red on means stand by, and when it turns green they perform the action, such as a scene shift, an entrance, or a fly move.", "category": "Cueing", "related_terms": ["Cue light", "Red cue light", "Standby", "Go", "Stage manager", "Warning"], "common_mistakes": ["Assuming every system uses green for GO; some single-lamp systems use light-on for standby and light-out for GO, so confirm the local convention.", "Acting on the green before a standby has been given or acknowledged, which can cause an early or missed cue.", "Confusing the green cue light with a general power or 'ready' indicator; here green specifically means execute the cue now."], "scenario_contexts": ["A flyman watches the green cue light to take a scenery move on the exact beat.", "An actor making a blackout entrance waits for the green cue light before stepping onstage.", "A deckhand takes a silent scene-change cue from the green light during a quiet scene."]}, "fe4f5724-36d7-487d-b10e-5786d587a264": {"definition": "In themed entertainment and haunted attractions, a sound-effect cue that is fired by a guest's own action—breaking an infrared beam, stepping on a pressure mat, or pressing a button—detected by a sensor and passed to a show-control system that plays the scare audio. It ties the frightening sound to the guest's position or movement so the effect lands at the intended moment.", "plain_english": "This is a scary sound that plays when a guest sets it off. A sensor notices the guest, like a hidden beam or a floor mat. Then the system plays the sound at just the right moment to make them jump.", "purpose_function": "It makes a scare feel personal and perfectly timed by letting the guest's own movement, rather than a fixed clock, decide when the sound plays.", "practical_application": "A technician places a sensor (beam, mat, or button) at a trigger point, wires it to a show controller or audio player, and sets the scare sound to fire on that input.", "category": "Themed entertainment", "related_terms": ["GPIO trigger", "Contact closure", "Show control", "Trigger", "Sound cue", "Sensor"], "common_mistakes": ["Assuming the sound plays on a timer; here it is the guest's action, sensed in real time, that fires the cue.", "Placing the sensor so it triggers too early or too late, so the scare misses the guest's position.", "UNSAFE: Setting scare-audio levels dangerously loud; sustained high sound levels can harm hearing, so keep exposure within safe limits."], "scenario_contexts": ["A guest breaks a hidden infrared beam in a haunted maze and a loud growl fires.", "Stepping on a pressure mat triggers a scream from a nearby speaker.", "A guest pressing a prop button sets off a startling sound as part of an interactive scene."]}, "6d7e7ea7-aeff-4ee4-a7d7-dfc5be04d5d4": {"definition": "A verbal safety confirmation used around powered flying, stage automation, and machinery, stating that all personnel's hands and bodies are clear of the moving element, its load, and any pinch points, so a move may safely begin. It is given and confirmed before an operator initiates the move.", "plain_english": "\"Hands clear\" means everyone's hands are away from the moving gear. It is said before something heavy or motorized moves. It confirms no one can get caught or crushed. Only then is it safe to start the move.", "purpose_function": "It confirms out loud that no one is within reach of a load or pinch point, so a move does not crush, drag, or trap a worker.", "practical_application": "Before flying scenery or running an automation move, the operator waits for or calls \"hands clear,\" visually confirms the area, and only then initiates travel.", "category": "Safety calls", "related_terms": ["Clear", "Standby", "Hold the show", "Stage automation", "Flying", "Deadman switch"], "common_mistakes": ["UNSAFE: Starting a move before hearing and confirming 'hands clear', risking crushing or dragging someone at a pinch point.", "UNSAFE: Treating 'hands clear' as a formality instead of actually looking to verify every person is clear before moving.", "Assuming 'hands clear' covers only the operator; it means all personnel and their limbs are clear of the load and its path."], "scenario_contexts": ["An automation operator confirms 'hands clear' before driving a moving wall onstage.", "A flyman calls for 'hands clear' before flying a heavy piece out.", "Crew rigging an automated truck step back and confirm 'hands clear' before it travels."]}, "6424e3ed-f2b5-4f74-b0dd-041bb322a3b4": {"definition": "In production communications, the combined earphone(s) and boom microphone worn by a crew member, connecting to an intercom beltpack or station to talk and listen on a party-line or matrix comms system. It keeps the wearer's hands free while the earcups isolate comms audio from loud surrounding sound.", "plain_english": "A headset is an earpiece plus a small boom microphone worn on the head. Crew use it to talk and listen on the show's intercom. It keeps hands free and blocks stage noise so you can hear cues.", "purpose_function": "It lets crew communicate hands-free during a show while the earcups block loud stage sound, so calls and cues are heard clearly.", "practical_application": "A technician plugs a headset into a beltpack or comms station, positions the mic boom near the mouth, and sets sidetone and level to talk with the stage manager and other departments.", "category": "Intercom", "related_terms": ["Headset station", "Beltpack", "Intercom", "Party-line", "Sidetone", "Cans"], "common_mistakes": ["Confusing single-muff (single-ear) and double-muff headsets; double-muff blocks more noise but reduces awareness of the live room.", "Leaving the microphone live and open, so coughs and side conversation go out to the whole comms channel.", "UNSAFE: Setting comms or program level in the headset too loud, risking hearing damage over a long call; keep levels moderate."], "scenario_contexts": ["A deck crew member wears a headset to hear standby and GO from the stage manager.", "A follow-spot operator uses a headset to take verbal cues during the show.", "A sound tech plugs a headset into a beltpack to coordinate a soundcheck."]}, "020775ca-b30c-4dfb-bb0c-e9ddfbd40155": {"definition": "A user station on a production intercom system that provides a headset connection with talk and listen controls, level adjustment, and call signalling; it may be a portable beltpack or a fixed desktop or rack panel on a party-line or matrix system. It is the point at which a crew member joins one or more comms channels.", "plain_english": "A headset station is the box you plug your headset into for intercom. It has talk and listen buttons and a volume knob. It can be a belt pack you wear or a fixed panel. It connects you to the show's comms channels.", "purpose_function": "It gives each crew member a controllable access point to the intercom, letting them choose channels, talk, listen, and signal a call.", "practical_application": "A technician assigns and cables a headset station (beltpack or panel) to each position, sets its channel and level, and tests talk and listen before the show.", "category": "Intercom", "related_terms": ["Headset", "Beltpack", "Intercom", "Party-line", "Matrix intercom", "Call signal"], "common_mistakes": ["Confusing a beltpack station with the main station or power supply; the main station powers and links the party-line, while beltpacks are user stations on it.", "Forgetting to select or enable the correct channel, so the operator cannot hear or be heard on the intended circuit.", "Overloading a party-line with more stations than its power supply supports, causing weak or distorted comms."], "scenario_contexts": ["Each department position gets a headset station wired back to the comms system before a show.", "A stage manager's desk has a fixed headset station to run standby and GO calls.", "Adding beltpack headset stations along a runway for a fashion show's cue crew."]}, "586d6a05-deaf-466b-bdda-a602c494ae43": {"definition": "An instruction, given over comms or as a control command, to immediately stop or pause sound playback—holding the audio cue in place rather than letting it continue—usually because of a technical fault, safety issue, or a hold on the show. It halts the sound department's output while other action pauses or is corrected.", "plain_english": "\"Hold audio\" means stop the sound right now. The operator pauses or stops the playing sound cue. It is used if something goes wrong or the show is paused. The audio waits until it is told to continue.", "purpose_function": "It lets the stage manager or operator freeze sound playback instantly, so audio does not run ahead while a problem is fixed or the show is held.", "practical_application": "On hearing \"hold audio,\" the operator pauses or stops the current sound cue and stands by to resume or restart it on the stage manager's call.", "category": "Stage management calls", "related_terms": ["Hold the show", "Standby", "Go", "Sound cue", "Cue", "Stage manager"], "common_mistakes": ["Confusing 'hold audio' (pause the sound now) with a scripted pause built into playback; this is a live instruction to stop.", "Stopping the cue from the top instead of pausing it, so the sound cannot resume cleanly from where it held.", "Ignoring the hold and letting the cue play out, so the audio runs ahead of a paused or troubled show."], "scenario_contexts": ["A stage manager calls 'hold audio' when a scene stops for a technical fault.", "An operator holds a long underscore when the show is paused for a safety check.", "'Hold audio' is called so a mistimed music cue can be reset before it continues."]}, "c66592e5-19ad-4c96-a881-6864d78cb8c9": {"definition": "A stage manager's command to temporarily stop the performance—pausing action, dialogue, and cues—usually because of a safety hazard, medical emergency, technical failure, or disturbance, until the situation is resolved and the show resumes from an agreed point. It is a deliberate, controlled pause, distinct from ending or aborting the performance.", "plain_english": "\"Hold the show\" means stop the performance for now. Everyone pauses, and actors, crew, and cues wait. It is usually called for safety, an injury, or a technical fault. The show restarts once things are safe and ready.", "purpose_function": "It gives one clear command to freeze the whole production at once, so a hazard or failure can be handled safely before the show continues.", "practical_application": "When the stage manager calls \"hold\" or \"hold the show,\" a technician stops running cues, safes any moving equipment, and stands by to resume from the agreed restart point.", "category": "Stage management calls", "related_terms": ["Hold audio", "Hands clear", "Standby", "Going up", "Places", "Stage manager"], "common_mistakes": ["UNSAFE: Continuing to run cues or move equipment after 'hold the show' is called, instead of stopping and making the stage safe.", "Confusing a hold (temporary, meant to resume) with a stop or abort of the performance.", "Failing to agree and communicate the restart point, so departments resume at different places when the show continues."], "scenario_contexts": ["A stage manager calls 'hold the show' when an audience member needs medical help.", "The show is held after a scenic automation fault until the piece is made safe.", "A hold is called during a fight scene when a performer is injured, then resumed after checks."]}, "a8d4d4af-b658-40ff-91ca-8553309e07c0": {"definition": "A verbal confirmation, given on the intercom or during a physical handoff, that the speaker has received, understood, or taken control of what was passed to them, whether a cue, a piece of information, or a physical load. It closes a call-and-response loop so the other party knows the message or object was accepted and is now the speaker's responsibility.", "plain_english": "This is a way to say 'I've got it' out loud. On a headset it means you heard and understood the message. During a handoff it means you now hold the weight. The other person can then safely let go.", "purpose_function": "It confirms that a message or a load was received, closing the communication loop so the sender knows it is safe to move on and no one wrongly assumes the other party still has control.", "practical_application": "A crew member says 'I have it' on comms to acknowledge a standby or instruction, or when taking the weight of scenery or a rigged load being handed over.", "category": "Communications protocol", "related_terms": ["Intercom channel", "Intercom station", "Cue", "Standby", "Go", "Interruptible foldback"], "common_mistakes": ["Assuming silence means the message was received; without a spoken confirmation the sender cannot know the cue or load was accepted.", "UNSAFE: Releasing a load, line, or piece of scenery before the person taking it has clearly said 'I have it', which can drop the load on someone.", "Saying 'I have it' before you actually understand the instruction or have real control of the load, which breaks the trust the call depends on."], "scenario_contexts": ["Acknowledging a stage manager's standby or instruction over the headset.", "Confirming you have taken the weight of a flat or set piece during a handoff.", "Telling a rigger you have control of a line before they release it.", "Answering a caller on the intercom so they know their message got through."]}, "28d591f2-832e-409b-bc9e-ba10dad44ee6": {"definition": "Sound content in a haunted attraction that is triggered or altered in real time by guests' actions, using sensors and a show-control system, rather than playing on a fixed timeline. Motion sensors, pressure mats, or manual triggers fire specific stingers, ambiences, or dialogue as visitors move through the space.", "plain_english": "This is spooky sound in a haunted house that reacts to you. Hidden sensors notice where you walk. They set off screams, growls, or noises at just the right moment. So the sound feels like it is responding to you.", "purpose_function": "It exists to make scares feel personal and well timed, firing sound the instant a guest reaches a spot, so the attraction responds to each visitor instead of running the same fixed track for everyone.", "practical_application": "A technician wires sensors or triggers into a show controller or media player, then maps each trigger to an audio file and speaker zone so the right sound plays when a guest passes.", "category": "Themed entertainment audio", "related_terms": ["Show control", "Cue", "Trigger", "Playback", "Sound effect", "Intercom channel"], "common_mistakes": ["Thinking the audio runs on a fixed timeline; interactive haunt audio is event-driven, firing from guest actions and sensor triggers, not from a clock.", "Placing speakers or sensors so triggers fire too early or too late, which ruins the timing that makes a scare land.", "UNSAFE: Running audio and sensor cabling across guest walkways without proper protection, creating a trip hazard in a dark space."], "scenario_contexts": ["A motion sensor firing a scream as a guest turns a dark corner.", "A pressure mat triggering a growl when someone steps on it.", "Zoning a haunted maze so each room plays its own reactive soundscape.", "Linking a sensor to a show controller that plays a stinger and a light flash together."]}, "7247d3d4-a366-4a36-99ad-64dffb4ce342": {"definition": "A discrete two-way (duplex) talk-and-listen path on an intercom system that connects a defined group of users so they can converse without being heard on other paths. On party-line systems it is a physical line, while on matrix and digital systems it is a logical group or partition that users can be assigned to and switched between.", "plain_english": "An intercom channel is one conversation line on a headset system. Everyone assigned to that channel can talk and hear each other. People on other channels do not hear it. It is like having separate group chats, but for voices.", "purpose_function": "Channels keep different departments' talk separate, so lighting, sound, and flies each get their own conversation and the system is not jammed by everyone hearing everything at once.", "practical_application": "A technician assigns each department to its own channel on a beltpack or panel, then selects which channels to talk or listen on during the show.", "category": "Intercom system", "related_terms": ["Intercom station", "Party-line", "Matrix intercom", "Interruptible foldback", "Headset", "Beltpack"], "common_mistakes": ["Confusing a channel with a station; a channel is a conversation path, while a station is the physical panel or beltpack a user talks on.", "Leaving talk latched on the wrong channel, so private comments are broadcast to a department that should not hear them.", "Assuming all channels are heard by everyone; each user only hears the channels their station is set to listen on."], "scenario_contexts": ["Putting the lighting crew on one channel and the deck crew on another.", "Selecting which channels a beltpack talks and listens to before a show.", "Adding a channel for a guest department during a load-in.", "Routing a director's channel into a matrix so key operators can hear it."]}, "24398d7a-1d9a-41d3-8532-3e5492ab9106": {"definition": "A user endpoint on an intercom system, such as a beltpack, wall panel, desktop station, or rack unit, that lets one operator talk and listen on one or more channels from a single device. Stations provide the microphone, headset or speaker connection, talk and listen controls, and channel selection for that position.", "plain_english": "An intercom station is the unit a person uses to join the headset system. It might be a beltpack, a desk unit, or a wall panel. It has the controls to talk, listen, and pick which channel you are on.", "purpose_function": "A station gives each crew position a place to connect and control their comms, turning one seat or worker into a full talk-and-listen point on the system.", "practical_application": "A technician places a station at each work position, a beltpack for a moving crew member or a panel at front-of-house, and sets its channels before the show.", "category": "Intercom system", "related_terms": ["Intercom channel", "Party-line", "Beltpack", "Headset", "Matrix intercom", "Interruptible foldback"], "common_mistakes": ["Confusing a station with a channel; the station is the physical device, while a channel is the conversation path it connects to.", "Overloading a party-line with too many powered stations, which can exceed the line's power supply and cause weak or noisy audio.", "Forgetting to set a station's talk and listen assignments, so the user cannot reach the department they need."], "scenario_contexts": ["Fitting a beltpack station on each crew member during load-in.", "Mounting a fixed panel station at the lighting or sound position.", "Adding a desktop station in the production office during tech.", "Checking every station's mic and channel setting at comms check."]}, "55000232-f8e8-4794-b216-16806fd13941": {"definition": "Recorded or live music played to the audience during the intermission (interval) of a performance, typically fed to the house and lobby speakers between acts. It is part of the show's playback and is timed to cover the break and to fade out as the audience is called back for the next act.", "plain_english": "This is the music played for the crowd during the break between acts. It fills the quiet while people stretch or get drinks. The sound operator fades it out when it is time for the next act to start.", "purpose_function": "It keeps the room feeling alive during the break, covers silence and set changes, sets the mood, then fades out to bring the audience back for the next act.", "practical_application": "The sound operator loads intermission tracks into the playback system, sends them to house and lobby zones, and fades them out on cue as the house lights dim for act two.", "category": "Show playback", "related_terms": ["House music", "Preshow music", "Playback", "Cue", "Sound cue", "House lights"], "common_mistakes": ["Setting intermission music too loud, so it carries into the auditorium and disturbs patrons still in their seats.", "Forgetting to route it to the lobby and restroom zones, so the music only plays where the audience is not.", "Letting the track run out into dead air, instead of looping or timing it to cover the whole break."], "scenario_contexts": ["Playing music to the house and lobby during the interval of a play.", "Fading intermission music down as the house lights dim for act two.", "Choosing tracks that match the show's period or mood for the break.", "Zoning the intermission feed to lobby and bar speakers."]}, "cac229ac-c93b-4bf1-a2ae-a515065116ab": {"definition": "Interruptible foldback (IFB) is a one-way monitor feed sent to on-air talent, usually through an earpiece, carrying program or foldback audio that a director or producer can interrupt with live instructions. When the talk key is pressed the program audio ducks or cuts so the talent hears the cue, then the program returns.", "plain_english": "IFB stands for interruptible foldback. It is the earpiece feed a TV presenter wears. Normally they hear the show's audio. When the director needs to talk, that audio drops so the presenter hears the instruction instead.", "purpose_function": "IFB lets a director cue and correct talent live without the audience hearing, by feeding them program audio that can be broken into with private instructions at any moment.", "practical_application": "An engineer sets up an IFB feed to each presenter's earpiece, mixing program audio with the director's mic, so instructions duck the program when the talk key is pressed.", "category": "Intercom system", "related_terms": ["Intercom channel", "Intercom station", "Foldback", "Talkback", "Program feed", "Earpiece"], "common_mistakes": ["Confusing IFB with normal foldback; IFB is a monitor feed that can be interrupted by the director, not just a fixed stage monitor mix.", "Setting the program and interrupt at the wrong levels, so the talent cannot hear the director's cue clearly over the show.", "Assuming the talent can reply on IFB; the earpiece feed is one-way, so a separate return path is needed for them to talk back."], "scenario_contexts": ["Cueing a news anchor's earpiece during a live broadcast.", "A director counting a presenter into a live segment over IFB.", "Feeding a reporter in the field program audio that the studio can interrupt.", "Setting IFB earpiece levels for talent before a show."]}, "64210553-be61-4b4f-bff8-ba0a61666eb0": {"definition": "To quickly cut or disconnect electrical power to equipment or a system, either as an emergency response or to begin de-energizing gear before service. It means opening the disconnecting means, such as a breaker, switch, or emergency stop, so the load is no longer energized; it does not by itself guarantee the equipment is safe to touch.", "plain_english": "To kill power means to shut off the electricity to something fast. You might do it in an emergency or before working on gear. But turning it off is not enough to make it safe. You must still check that no power is left and lock it out.", "purpose_function": "It stops current flow quickly to protect people and equipment, whether to end an emergency, halt a fault, or begin de-energizing a system before maintenance.", "practical_application": "A technician kills power at the breaker or emergency stop, then follows lockout/tagout and verifies zero energy with a meter before touching conductors.", "category": "Electrical safety", "related_terms": ["Lockout/tagout", "Emergency stop", "Disconnecting means", "Mains power", "Circuit breaker", "Grounding"], "common_mistakes": ["UNSAFE: Assuming that killing power at a switch makes a circuit safe to touch; you must lock out, tag out, and verify zero voltage with a meter first per OSHA 1910.147 and NFPA 70E.", "UNSAFE: Forgetting that capacitors and power supplies can hold a dangerous charge after power is cut, so parts may still shock you.", "Killing the wrong circuit or leaving a second source connected, so the equipment stays energized while you believe it is dead.", "Treating 'kill power' as the whole safety procedure, rather than the first step before lockout/tagout and verification."], "scenario_contexts": ["Hitting the emergency stop to cut power when a machine or effect malfunctions.", "Opening a breaker to de-energize an amp rack before servicing it.", "Cutting stage power fast when someone contacts a live conductor.", "Isolating a circuit before lockout/tagout and voltage verification."]}, "91511d46-4573-4e70-aa61-77d78c524644": {"definition": "A control number in a lighting console that an operator uses to command one or more DMX addresses as a single controllable unit, such as a dimmer, a group of dimmers, or all the parameters of a moving light or LED fixture. The channel is the console-side handle for control, distinct from the DMX address, which is the output-side slot a device listens to.", "plain_english": "A lighting channel is the number you use on the desk to control a light. One channel can run a single lamp or a whole group. It is different from the DMX address, which is the slot the fixture listens to. Patching links the channel to the address.", "purpose_function": "Channels give the operator a simple, stable set of control handles, so lights can be commanded by channel number no matter how the underlying addresses are patched.", "practical_application": "An operator patches each fixture to a channel, then sets levels and records cues by channel number rather than by raw DMX address.", "category": "Lighting control", "related_terms": ["DMX address", "Dimmer", "Patch", "Cue", "Lighting console", "DMX512"], "common_mistakes": ["Confusing a channel with a DMX address; the channel is the console control number, while the address is the output slot the fixture reads.", "Assuming one channel always equals one dimmer; a modern channel can bundle many addresses and a whole moving light.", "Forgetting to patch, so a channel controls nothing because it is not linked to any address."], "scenario_contexts": ["Patching a moving light's many addresses to a single channel number.", "Recording a cue by setting channel levels on the console.", "Grouping several dimmers under one channel for a wash.", "Troubleshooting a dead fixture by checking its channel-to-address patch."]}, "9829674e-6389-4e10-a964-28e6fd9a83de": {"definition": "In an intercom or communications system, the listen level is the adjustable volume of the incoming audio a user hears at their beltpack, headset station, or panel, set independently of the talk (microphone) level. Each user station provides a listen-level control so operators can balance program, partyline, and channel audio to a comfortable, intelligible level.", "plain_english": "Listen level is how loud you hear other people in your headset. Each intercom pack has its own knob for this. You turn it up or down to hear cues clearly. It does not change how loud others hear you.", "purpose_function": "It lets each user set incoming comms audio to a clear, comfortable level without affecting other users or their own microphone level.", "practical_application": "During a comms check, a crew member adjusts the listen level on their beltpack so the stage manager's cues stay clear over the running show.", "category": "Intercom", "related_terms": ["Beltpack", "Matrix intercom", "Partyline intercom", "Talk level", "Headset station", "Production intercom"], "common_mistakes": ["Confusing listen level (how loud you hear others) with talk or mic level (how loud others hear you).", "Setting the listen level too low and then missing spoken cues during the show.", "UNSAFE: Turning the listen level to maximum to overcome noise, risking hearing damage from sustained loud headset audio; follow safe listening limits per OSHA and NIOSH guidance."], "scenario_contexts": ["Balancing partyline and program audio at a beltpack before a performance.", "Raising listen level on a noisy loading dock so radio cues stay intelligible.", "Setting each channel's listen level on a matrix panel to prioritise the stage manager."]}, "f6e2ddfd-8918-4b77-b11e-207474fb9c89": {"definition": "A listen microphone is a microphone placed in the performance space, onstage or in the auditorium, whose output feeds show-relay, paging, or program-audio systems so that people in acoustically isolated areas such as dressing rooms, control rooms, and backstage can hear the live performance. It provides the pickup source for the 'listen' or program feed of a communications and show-relay system.", "plain_english": "A listen mic is a microphone aimed at the stage or audience. It sends the live sound to speakers backstage and in dressing rooms. This lets people who cannot hear the stage follow the show. They use it to know when to get ready.", "purpose_function": "It captures the live performance so show-relay and paging systems can carry the sound to isolated backstage and dressing-room areas.", "practical_application": "A technician hangs a listen mic over the stage and routes it to dressing-room show-relay speakers so performers can hear their cues to come to stage.", "category": "Show relay", "related_terms": ["Show relay", "Program feed", "Paging", "Production intercom", "God mic", "Listen level"], "common_mistakes": ["Confusing a listen mic (feeds backstage show relay) with a reinforcement mic (feeds the house PA).", "Placing the listen mic where it picks up mostly noise, so the relay feed is unintelligible.", "Assuming the listen-mic feed is broadcast quality; it is a monitoring feed, not a recording or PA source."], "scenario_contexts": ["Feeding a stage listen mic to dressing-room speakers so the cast can follow the show.", "Providing program audio from a listen mic to a soundproof control booth.", "Routing a house listen mic to backstage so crew can hear applause and act ends."]}, "014150b4-5635-4e98-a11f-62c6a044184e": {"definition": "A matrix intercom is an intercom system built around a central digital matrix (crosspoint switcher) to which all user stations connect, allowing any port to be routed to any other port, group, or partyline under software control. Unlike a fixed partyline, routing is fully assignable, so point-to-point calls, conferences, and interfaces to IFB, program, telephone, and radio can be configured per production.", "plain_english": "A matrix intercom is a smart switchboard for headsets. Every station plugs into one central hub. Software decides who can talk to whom. You can set up private calls or group channels for each show. It is more flexible than a simple shared party line.", "purpose_function": "It provides fully assignable, any-to-any communication routing from one central system, so large productions can build custom talk groups and point-to-point paths.", "practical_application": "A comms technician programs a matrix intercom so, for example, the lighting board talks only to the lighting crew while the stage manager reaches everyone.", "category": "Intercom", "related_terms": ["Partyline intercom", "Beltpack", "Listen level", "IFB", "Production intercom", "Program feed"], "common_mistakes": ["Assuming a matrix works like a partyline where everyone hears everyone; matrix routing is assigned per port and per key.", "Forgetting to program key assignments, so stations cannot reach the groups they need during the show.", "Confusing the matrix frame (the central router) with the user panels that connect to it."], "scenario_contexts": ["Programming talk groups on a matrix frame for a multi-department tour.", "Interfacing two-way radios and telephone lines into the matrix for a broadcast event.", "Assigning point-to-point keys so the director reaches only the camera operators."]}, "b4911f88-7df1-4f12-b248-2b52bfff15fa": {"definition": "A MIDI trigger is an incoming MIDI message, such as a Note On, Program Change, Control Change, or MIDI Show Control command, used to start (fire) a cue or action in a receiving device such as a cue-playback application, lighting console, or media server. The device is configured to listen for a specific message on a specific channel and execute a mapped action when it arrives.", "plain_english": "A MIDI (Musical Instrument Digital Interface) trigger is a digital signal that starts something. One device sends a MIDI message and another device reacts. For example, pressing a key can fire a sound cue. It lets separate gear act together on one command.", "purpose_function": "It lets one device automatically start a cue or action on another, so a single command can drive lights, sound, and media in step.", "practical_application": "An operator maps a MIDI Note On from a keyboard or console so it fires the next audio cue in the playback software on cue.", "category": "Show control", "related_terms": ["MIDI Show Control", "SMPTE timecode", "Cue", "MIDI", "OSC", "Go button"], "common_mistakes": ["Setting the sending and receiving devices to different MIDI channels, so the trigger is ignored.", "Confusing a general MIDI note trigger with MIDI Show Control, which is a specific command set for cueing.", "Leaving a device listening to all messages, so stray MIDI data fires cues unexpectedly."], "scenario_contexts": ["Firing sound cues from a lighting console over MIDI in a synchronised show.", "Using a MIDI footswitch to advance playback cues hands-free.", "Triggering a media-server clip from a music sequencer via MIDI."]}, "203e4e02-be84-4c15-a18d-f82387cba831": {"definition": "'Moving stage left' is a spoken warning called by a performer or crew member to announce that they are moving toward stage left, the actor's left when facing the audience, so others in the often dark or crowded backstage and onstage space are aware and can avoid a collision. It is part of standard backstage safety and communication etiquette.", "plain_english": "This is a spoken warning that you are moving to stage left. Stage left is the actor's left when facing the crowd. You say it so people nearby do not bump into you. It keeps everyone safe in the dark.", "purpose_function": "It alerts others to your direction of movement in low-light, crowded conditions, preventing collisions and keeping traffic flowing safely.", "practical_application": "During a blackout scene change, a crew member carrying a set piece calls 'moving stage left' so others clear the path.", "category": "Verbal warning", "related_terms": ["Moving stage right", "Stage left", "Stage right", "Blackout", "Scene change", "Cue light"], "common_mistakes": ["Calling the direction from your own facing instead of the standard convention (the actor facing the audience), confusing others.", "UNSAFE: Moving through the dark backstage or crossing behind scenery without calling out, risking collisions with crew, cast, or moving scenery.", "Confusing stage left with house left; stage left is the performer's left, which is the audience's right."], "scenario_contexts": ["Warning of movement during a dark scene change.", "Carrying a prop across a crowded wing during a performance.", "Coordinating crew traffic in a narrow backstage crossover."]}, "5367f031-a012-4b94-8a40-1258a725f871": {"definition": "'Moving stage right' is a spoken warning called by a performer or crew member to announce that they are moving toward stage right, the actor's right when facing the audience, so others in the often dark or crowded backstage and onstage space are aware and can avoid a collision. It is part of standard backstage safety and communication etiquette.", "plain_english": "This is a spoken warning that you are moving to stage right. Stage right is the actor's right when facing the crowd. You say it so people nearby do not bump into you. It keeps everyone safe in the dark.", "purpose_function": "It alerts others to your direction of movement in low-light, crowded conditions, preventing collisions and keeping traffic flowing safely.", "practical_application": "During a blackout scene change, a crew member carrying a set piece calls 'moving stage right' so others clear the path.", "category": "Verbal warning", "related_terms": ["Moving stage left", "Stage right", "Stage left", "Blackout", "Scene change", "Cue light"], "common_mistakes": ["Calling the direction from your own facing instead of the standard convention (the actor facing the audience), confusing others.", "UNSAFE: Moving through the dark backstage or crossing behind scenery without calling out, risking collisions with crew, cast, or moving scenery.", "Confusing stage right with house right; stage right is the performer's right, which is the audience's left."], "scenario_contexts": ["Warning of movement during a dark scene change.", "Carrying a prop across a crowded wing during a performance.", "Coordinating crew traffic in a narrow backstage crossover."]}, "726cf9b1-9098-495c-b92a-6f959e9ab35d": {"definition": "'On three' is a verbal coordination cue used to synchronise a simultaneous physical action, such as a team lift, a set move, or a shift, by counting so the action happens together at the agreed count. Because crews differ on whether the action falls on the spoken 'three' or on the beat after it, the caller must state the convention before counting.", "plain_english": "'On three' is a way to time a group action by counting out loud. Everyone lifts or moves together on the count. But teams disagree on when to move. It may be on the word 'three,' or right after. So the caller must say clearly which one they mean.", "purpose_function": "It coordinates people so a shared, effortful, or precise action happens at the same instant, reducing strain and mistakes.", "practical_application": "Before a heavy team lift, the crew lead confirms 'we go on three, not after' so everyone lifts on the same count.", "category": "Verbal cue", "related_terms": ["Standby", "Go", "Cue", "Moving stage left", "Moving stage right", "Cue light"], "common_mistakes": ["UNSAFE: Not agreeing whether the lift is on 'three' or after 'three' before a heavy team lift, so people pull at different moments and risk dropping the load or injury; NIOSH advises one person coordinate a team lift with clear commands.", "Counting too fast for everyone to react together.", "Assuming 'on three' is universal; always confirm the convention with the specific crew."], "scenario_contexts": ["Coordinating a four-person lift of a heavy road case.", "Timing a manual scenery shift during a blackout.", "Synchronising a group push of a rolling platform."]}, "7ef0f595-317d-4aa5-adc6-ebb9cd2ac085": {"definition": "An operator note is a written instruction or reminder directed to a specific console or equipment operator, recorded in the prompt book, cue sheet, or a cue's notes field in playback software, telling them what to do, watch for, or prepare at a given point in the show. It documents operational detail that is not itself a numbered cue but is needed to run the cue correctly.", "plain_english": "An operator note is a short written reminder for the person running a board or playback. It tells them what to watch for or do at a certain moment. It is written in the prompt book or cue list. It is not a cue itself, just a helpful instruction.", "purpose_function": "It captures the operational details and reminders an operator needs so cues run correctly and consistently at every performance.", "practical_application": "A stage manager writes an operator note beside a cue, such as 'watch for the actor's hand, then GO,' so the operator times the fade precisely.", "category": "Cueing", "related_terms": ["Prompt book", "Cue sheet", "Cue", "Standby", "Cue light", "Go"], "common_mistakes": ["Writing an operator note as if it were a numbered cue, confusing what the operator should actually execute.", "Leaving notes so vague the operator cannot act on them under show pressure.", "Failing to update operator notes after rehearsal changes, so the running notes no longer match the show."], "scenario_contexts": ["Adding a note in QLab's notes field reminding the operator to check a wireless mic before a cue.", "Annotating the prompt book with a warning to the follow-spot operator.", "Writing a reminder on the cue sheet to preset a fader before the next scene."]}, "74ab6814-b5de-4cd5-a499-631071e8be96": {"definition": "A stem is a discrete submix of a group of related audio sources, bounced or routed as its own track so it can later be combined with or balanced against other stems. An orchestra stem is that submix carrying the orchestral parts (or a section of them), used in theatre and musical playback to provide pre-recorded orchestra, orchestral augmentation, or a mixdown element the operator can level independently.", "plain_english": "A stem is a ready-made mix of a group of instruments saved as one track. An orchestra stem holds the orchestra sound this way. A show can play it back instead of, or on top of, live players.", "purpose_function": "It packages the orchestra as a single, self-contained playback element so the sound team can trigger, level, and route the whole orchestral sound without rebuilding every instrument track live.", "practical_application": "A sound designer loads the orchestra stem into the playback system as a cue, then sets its level and routing so it sits correctly with the cast and any live musicians.", "category": "Playback audio", "related_terms": ["Stem", "Playback computer", "Playback interface", "Click track", "Backing track", "Submix"], "common_mistakes": ["Confusing a stem, which is a grouped submix, with a full multitrack or a single instrument track; a stem already blends several sources together.", "Assuming the orchestra stem is a finished stereo mix; stems are meant to be combined and re-balanced, not treated as an untouchable master.", "Forgetting to check the stem's sync reference or tempo, so it drifts against a click track or live conductor."], "scenario_contexts": ["Playing a pre-recorded orchestra stem for a musical staged without a live pit.", "Adding an orchestra stem to reinforce a small live band during big numbers.", "Balancing the orchestra stem against lead-vocal mics from the playback position during tech."]}, "ae9f6261-8b60-4d06-9419-8f1f266ddcf4": {"definition": "Control of show equipment using Open Sound Control (OSC), a message-based network protocol first developed at CNMAT (UC Berkeley) to let computers, sound gear, and other media devices exchange control data. OSC messages carry a URL-style address pattern (for example /cue/1/start) plus typed arguments, and are typically carried over UDP (or TCP) on a network, letting devices such as QLab and lighting consoles trigger and query each other.", "plain_english": "OSC means Open Sound Control. It lets show computers and gear send messages over a network. Each message has an address, like a web link, that tells the gear what to do.", "purpose_function": "It gives show systems a flexible, network-based way to send commands and data to one another, so one device can start cues, change levels, or read status on another across a show network.", "practical_application": "A technician sets a QLab OSC cue to fire a lighting console, or maps OSC addresses so a tablet or console can remote-control the playback machine over the network.", "category": "Show control protocol", "related_terms": ["MIDI Show Control", "QLab", "Show network", "sACN", "Cue", "Timecode"], "common_mistakes": ["Assuming OSC is a fixed command set; OSC only defines the message format, so the address patterns each device responds to must be checked in its documentation.", "Forgetting that OSC usually rides on UDP, which does not guarantee delivery, so a dropped packet can silently miss a command.", "Mismatching IP addresses or ports between sender and receiver, so messages are sent but never arrive."], "scenario_contexts": ["Triggering an ETC Eos lighting cue from a QLab OSC cue during a show.", "Remote-controlling QLab from a tablet using OSC over the show's wireless network.", "Sending fader levels from a console to a media server using OSC messages."]}, "eddacfa3-2356-4213-b3b1-30eb6d20cb50": {"definition": "A microphone used to make paging announcements over a venue's backstage/program paging system—for example the stage manager calling the company or making dressing-room and backstage announcements. It is commonly the microphone on a stage manager's desk or the built-in/attached microphone of an intercom main station whose stage-announce or program output feeds paging loudspeakers.", "plain_english": "This is the mic used to make announcements backstage. The stage manager talks into it to call the cast and crew. It feeds speakers in dressing rooms and hallways.", "purpose_function": "It provides the talk source for the paging system, letting one person address performers and crew in areas that headset intercom alone does not cover.", "practical_application": "A technician wires the page microphone to the main station's stage-announce or program output and checks it reaches all dressing-room and backstage speakers during a comms check.", "category": "Paging", "related_terms": ["Partyline intercom", "Stage announce", "Program feed", "Places call", "Show relay", "Intercom station"], "common_mistakes": ["Confusing paging, which broadcasts to loudspeakers in backstage areas, with headset intercom, which is a private talk channel between crew.", "Leaving the page microphone open or routed live, so announcements bleed into open stage or pit microphones and out to the house.", "Assuming paging reaches everywhere; distant or noisy rooms may need added speakers or a visual call as well."], "scenario_contexts": ["Calling 'half hour' to the company over dressing-room speakers before a show.", "Making a backstage safety or evacuation announcement from the stage manager's desk.", "Paging a specific crew member to the stage during a technical rehearsal."]}, "7edb7be8-1ce1-482e-8857-db721971b7f4": {"definition": "A single manually operated control that instantly forces a system into a predetermined safe or known state—for example an all-stop of automated scenery, bringing up work or house lights, or aborting a running cue sequence. In show control the term covers both software 'panic' functions in cue software and consoles and dedicated hardware controls; it is distinct from a safety-rated emergency stop (E-stop), which is a hardware device governed by machinery-safety standards.", "plain_english": "This is one button that puts a system into a safe, known state fast. It might stop all moving scenery or bring the lights back up. It is there for when something goes wrong.", "purpose_function": "It gives an operator one fast, unambiguous action to recover control or reach safety when a show goes wrong, instead of hunting through menus or many controls under pressure.", "practical_application": "An operator programs a panic or all-stop control and confirms in rehearsal exactly what state it produces, so it can be hit confidently if a cue misfires or scenery must stop.", "category": "Emergency control", "related_terms": ["Emergency stop", "All stop", "Cue", "Show control", "Blackout", "Automation"], "common_mistakes": ["Assuming every 'panic button' does the same thing; its result depends entirely on how it is programmed, so its exact effect must be confirmed in advance.", "UNSAFE: Treating a software panic or all-stop cue as a substitute for a safety-rated hardware emergency stop on powered machinery; life-safety stopping of scenery and hoists must use standards-compliant E-stop hardware per machinery-safety standards (e.g. ANSI E1.6-1, ISO 13850), not a software cue.", "Placing or labelling the control where it can be hit by accident, or where the operator cannot reach it quickly in an emergency."], "scenario_contexts": ["Hitting an all-stop control when automated scenery moves toward a performer.", "Using a panic cue to snap house and work lights up if a show must be halted.", "Programming a recovery 'panic' state on a console to reset a look after a misfired cue."]}, "faa6fd21-3c18-4573-9160-e200ac5946cf": {"definition": "An intercom system in which multiple users share a common circuit (a 'party line'), so everyone connected to a given channel can talk and listen simultaneously on that shared conductor pair. Classic analogue partyline systems (such as Clear-Com and RTS/Telex TW) power the line from a central main station or power supply and connect beltpacks and speaker stations over two-wire (or four-wire) cabling; digital partyline systems carry the same shared-channel model over a digital link.", "plain_english": "This is a headset system where everyone shares one line. All users on a channel hear and talk to each other at once. It works like a group phone call for the crew.", "purpose_function": "It lets a whole crew coordinate in real time over shared channels, giving the stage manager and operators an always-open talk-and-listen path during rehearsals and shows.", "practical_application": "A technician runs partyline cable from the main station to beltpacks and speaker stations, sets channel and termination, and does a comms check so every position can talk and hear.", "category": "Intercom systems", "related_terms": ["Intercom station", "Beltpack", "Main station", "Page microphone", "Show relay", "Cue light"], "common_mistakes": ["Forgetting that partyline is a shared channel, so several people talking at once step on each other; discipline and channel planning matter.", "Leaving the line unterminated or mis-terminated, causing noise, low headroom, or poor performance on the two-wire circuit.", "Assuming any headset works; using the wrong impedance or wiring for the system can give weak or distorted audio."], "scenario_contexts": ["Running headset comms between the stage manager, lighting, sound, and deck crew during a show.", "Splitting the crew across two channels so deck and flys can talk without cluttering the main channel.", "Doing a pre-show comms check across all beltpacks and speaker stations on the partyline."]}, "3e24ec7e-51ea-47be-94f4-42f02332482e": {"definition": "The stage manager's call summoning cast and crew to their starting positions for the top of the show or an act, given (typically as 'Places' or 'Places, please') as the final call in the sequence of pre-show time calls before the performance begins. It signals that everyone must be in their opening positions and ready for the show to start.", "plain_english": "This is the call telling everyone to go to their start spots. The stage manager says places, please just before the show begins. Then the show can start on time.", "purpose_function": "It gets every performer and crew member into position at the same moment, so the show can begin cleanly and on schedule with no one caught out of place.", "practical_application": "The stage manager gives the places call over paging and intercom, confirms positions are set, then proceeds to the opening cues once places are held.", "category": "Stage management calls", "related_terms": ["Half-hour call", "Page microphone", "Show relay", "Cue light", "Standby", "Top of show"], "common_mistakes": ["Confusing the places call with earlier time calls (half hour, fifteen, five); places is the final call to opening positions, not a time warning.", "Giving places before backstage is actually ready, so the show starts with performers or crew still moving.", "Assuming everyone heard the call; positions should be confirmed rather than presumed."], "scenario_contexts": ["Calling 'Places, please' a few minutes before curtain to bring the company to opening positions.", "Calling places for the top of Act Two after intermission.", "Holding places while a late technical issue is resolved before starting the show."]}, "96d937e8-5adf-46ed-92bb-cfd089700a63": {"definition": "The computer that stores and fires a show's cues—running playback software such as QLab, SCS, Ableton Live, or a media server/show-control platform—to trigger audio, video, and control events during a performance. It is the machine an operator runs 'GO' on to advance the cue list in sequence.", "plain_english": "This is the computer that runs the show sound and video cues. An operator presses go, and it fires each cue in order. Software like QLab does this job.", "purpose_function": "It centralises a show's audio, video, and control cues in one reliable, repeatable system, so a single operator can run complex sequences accurately every performance.", "practical_application": "A sound operator loads the show file, checks outputs and cue order, and presses GO on the playback computer to fire each cue on the stage manager's call.", "category": "Playback systems", "related_terms": ["Playback interface", "QLab", "Cue", "Orchestra stem", "OSC control", "Show control"], "common_mistakes": ["Relying on a single playback computer for a critical show with no backup or redundancy plan if it crashes.", "Running unrelated background software or updates on the show machine, risking glitches or dropouts mid-performance.", "Confusing the playback computer, which fires the cues, with the audio interface, which actually carries the outputs to the system."], "scenario_contexts": ["Running QLab on the show laptop to fire sound and video cues on the stage manager's call.", "Setting up a backup playback machine mirrored to the primary for a high-stakes show.", "Building and rehearsing the cue list on the playback computer during tech."]}, "fc2198b0-19e1-4374-aba7-2fdd14288fb8": {"definition": "The audio interface (I/O device) that connects the playback computer to the sound system, converting the software's digital cue outputs into the multiple analogue or digital output channels routed to the mixing console or matrix. It provides the physical outputs (and often inputs) and the device driver the playback software addresses to place each cue on the correct channels.", "plain_english": "This is the box that connects the playback computer to the sound system. It turns the computer cues into real audio outputs. Those outputs feed the mixing console.", "purpose_function": "It gives the playback computer enough discrete, good-quality outputs to route each cue or stem to the right destination, bridging the software world and the physical sound system.", "practical_application": "A technician connects the interface, installs its driver, and patches its outputs in the playback software so each cue lands on the intended console inputs.", "category": "Playback systems", "related_terms": ["Playback computer", "QLab", "Audio interface", "Orchestra stem", "Mixing console", "Output patch"], "common_mistakes": ["Confusing the playback interface (the audio I/O hardware) with the playback computer that runs the cue software.", "Mismatching the software's output patch to the interface's physical outputs, so cues come out on the wrong channels or not at all.", "Ignoring sample-rate or clock settings between the interface and the rest of the system, causing clicks, dropouts, or sync errors."], "scenario_contexts": ["Patching a multi-output USB or network audio interface so each QLab cue reaches its console input.", "Choosing an interface with enough discrete outputs to keep stems separate for the mix.", "Troubleshooting silent cues by checking the interface driver and output patch."]}, "8f8231a6-23cf-4fdc-a550-aa5c806bd508": {"definition": "A rack-mounted assembly of the equipment used to play back a show's audio (and often video/control) cues—typically housing the playback computer(s), audio interface(s), and supporting devices such as DSP, matrix, network switches, and sometimes amplification—integrated and wired as a single transportable unit. Racking the playback chain together standardises the wiring, protects the gear, and lets the whole system be moved, powered, and connected as one package.", "plain_english": "A playback rack is a case that holds the gear used to play a show's cues. It keeps the computer, sound box, and other units together in one unit. That makes it easy to move and connect.", "purpose_function": "It consolidates the playback signal chain into one organised, protected, and repeatably-wired unit, so the system can be transported, powered, and patched quickly and reliably at each venue.", "practical_application": "A technician mounts and wires the playback computer, interface, and support gear into the rack, labels the I/O, and connects it to the console and network as a single package during load-in.", "category": "Playback systems", "related_terms": ["Playback computer", "Playback interface", "Primary playback system", "QLab", "DSP", "Patch"], "common_mistakes": ["Confusing the playback rack (the housing and full signal chain) with just the playback computer inside it.", "Poor cable management or unlabelled I/O in the rack, making fast fault-finding during a show almost impossible.", "UNSAFE: Overloading a single power circuit or outlet strip in the rack, or ignoring proper grounding, creating shock or fire risk."], "scenario_contexts": ["Building a self-contained playback rack for a touring musical so it installs quickly at each venue.", "Wiring the playback computer, interface, and network switch into one rack for a repertory theatre.", "Rolling the playback rack into position and patching it to the console during load-in."]}, "433c372b-3ce1-44f6-b4ab-235ae39df6f5": {"definition": "A stem—a discrete submix of related audio sources bounced or routed as its own track—used as a playback element in a show. Loaded as a cue in the playback system, a playback stem lets the operator trigger, level, and route a pre-mixed group of sources (for example orchestra, band, vocals, or effects) independently of other stems during the performance.", "plain_english": "A stem is a ready-made mix of related sounds saved as one track. A playback stem is a stem you play back during a show. The team can set its level on its own.", "purpose_function": "It packages a group of related sources as one controllable playback element, so the operator can balance and route that group live without rebuilding its individual tracks each performance.", "practical_application": "A sound designer imports the stems into the playback software as cues, then sets each stem's level and output routing so they combine correctly during tech and the run.", "category": "Playback audio", "related_terms": ["Stem", "Orchestra stem", "Playback computer", "Playback interface", "Click track", "Backing track"], "common_mistakes": ["Confusing a stem, which is a grouped submix, with a full multitrack or a single-instrument track.", "Treating a playback stem as an untouchable finished mix; stems are meant to be re-balanced against each other.", "Forgetting to check the stem's sync or tempo reference, so it drifts against a click track or conductor."], "scenario_contexts": ["Playing separate music and effects stems so the operator can level them independently during a scene.", "Loading vocal and band stems into QLab for a musical performed without a full live pit.", "Rebalancing playback stems against live mics from the mix position during tech."]}, "bbf7906e-1163-4b17-9b50-82c32336d5f8": {"definition": "Music played in the auditorium before a performance begins (and sometimes at intermission), while the house is open and the audience is being seated, ahead of the show's first cue. Often called preshow music, it is selected and played by the sound department to establish atmosphere and signal that the performance is about to start; it corresponds to the 'preset' state of the production before the show runs.", "plain_english": "Preset music is the music played before a show starts. It plays while the audience finds their seats. It sets the mood and hints that the show will soon begin.", "purpose_function": "It sets the mood and world of the piece for the arriving audience and provides an audible signal that the show is about to begin, while helping mask house noise as people settle.", "practical_application": "The sound operator starts the preset music as the house opens, holds it at a set level, and fades it out on the stage manager's cue as the show begins.", "category": "Playback audio", "related_terms": ["Preset", "Cue", "Playback computer", "Fade", "Underscore", "House open"], "common_mistakes": ["Setting preset music too loud, so it competes with audience conversation or startles people as they enter.", "Forgetting to start preset music when the house opens, leaving the auditorium flat and silent.", "Confusing preset music (before the show) with underscore or scene-change music played during the show."], "scenario_contexts": ["Starting atmospheric preset music as the house opens for a play, then fading it as the lights dim.", "Choosing period-appropriate preset music to set the world of a musical before curtain.", "Bringing preset music back at intermission and fading it out for the second act."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"ccff616b-7a2f-49d6-85e6-2e90cfbf5fa9": {"definition": "The main playback system that actually runs a show's audio (and often video and control) cues during performance, as opposed to a backup or redundant secondary system held in reserve. In a redundant setup the primary and backup systems are configured identically and often kept in sync, so operation can fail over to the backup if the primary stops working.", "plain_english": "This is the main system that plays a show's cues. It does the real work each night. A backup system waits in case the main one fails.", "purpose_function": "It is the system relied on to fire every cue in performance; naming a primary (with a backup) makes responsibilities and failover clear for high-stakes shows.", "practical_application": "The operator runs the show from the primary system while a mirrored backup stands ready, testing failover during tech so a crash mid-show can be recovered quickly.", "category": "Playback systems", "related_terms": ["Playback computer", "Playback rack", "Redundancy", "Backup playback system", "Failover", "QLab"], "common_mistakes": ["Running a critical show from a primary system with no backup or tested failover plan.", "Assuming a backup exists but never syncing or rehearsing the switch to it, so failover fails when needed.", "Confusing the primary playback system (the whole cue-firing system) with a single part like the computer or interface."], "scenario_contexts": ["Running a musical from the primary playback computer while a mirrored backup stands by.", "Testing failover from primary to backup during tech for a high-stakes broadcast or show.", "Labelling primary and backup systems clearly so any operator knows which one is live."]}, "c7df7664-ffc2-47ee-b82f-a9e3cf20ac44": {"definition": "In production intercom, a talk path used by technical and production crew that is separate (private) from program audio and from the audience—most precisely a point-to-point circuit connecting two parties directly, as distinct from a shared party-line channel. The abbreviation 'PL' most commonly denotes party-line, though 'private line' is sometimes confusingly abbreviated the same way; in matrix intercom a private line is a direct one-to-one talk path between two stations.", "plain_english": "A private line is a one-to-one talk path on an intercom. Only the two people on it can hear each other. It works like a private phone call between two crew members.", "purpose_function": "It gives two crew members a direct, dedicated talk path that does not clutter or get overheard on the shared channels, keeping one-to-one or sensitive coordination off the group line.", "practical_application": "An operator sets up a private line (a point-to-point key) on a matrix intercom panel to talk directly to one other position without the rest of the crew hearing.", "category": "Intercom systems", "related_terms": ["Partyline intercom", "Matrix intercom", "Intercom station", "IFB", "Beltpack", "Production channel"], "common_mistakes": ["Assuming 'PL' always means private line; in most party-line systems PL stands for party-line, a shared channel.", "Confusing a private line (one-to-one) with a party line (a shared channel everyone hears).", "Forgetting that a private line still needs both stations correctly keyed and routed to work."], "scenario_contexts": ["Setting a point-to-point key so the show caller can talk privately to the automation operator.", "Using a private line for a sensitive note between director and stage manager during tech.", "Configuring matrix panels so key positions have direct private lines to each other."]}, "714f6b50-b37e-4746-8adc-2c4321c1e991": {"definition": "A dedicated intercom talk channel used by the technical and production crew to coordinate a performance—carrying calls between the stage manager and operators (sound, lighting, automation, deck, and so on)—as distinct from channels reserved for other purposes such as a director's channel or a program feed. On party-line systems it is a shared channel; on matrix systems it is a configured conference or partyline that the production positions are keyed to.", "plain_english": "A production channel is a talk channel on the crew headset system. The stage manager and crew use it to run the show. It keeps their calls on one shared line.", "purpose_function": "It gives the running crew one common channel to hear the stage manager's calls and coordinate cues in real time, keeping show-running communication organised and separate from other traffic.", "practical_application": "The technician assigns the production positions to the production channel, sets levels, and runs a comms check so every operator can hear calls and reply during the show.", "category": "Intercom systems", "related_terms": ["Partyline intercom", "Matrix intercom", "Private line", "Production headset", "Intercom station", "Cue"], "common_mistakes": ["Putting too many positions on one production channel, so cross-talk buries the stage manager's calls.", "Confusing the production channel with a program or director channel and routing the wrong audio to it.", "Skipping a pre-show comms check, so a dead position on the production channel is found only mid-show."], "scenario_contexts": ["Running the stage manager's cue calls to sound, lights, and deck over the main production channel.", "Splitting deck and fly crews onto a second channel to keep the main production channel clear.", "Setting up the production channel on the matrix and keying each operator's panel to it."]}, "c9c20f8b-757e-433c-85d3-664abbc8ae46": {"definition": "A cue that signals a technical or production department to execute an action—such as sound, lighting, video, automation, or fly moves—as opposed to an actor's performance cue. Called or triggered at a scripted point (typically preceded by a warning/standby and executed on 'GO'), it is the instruction that makes a production element happen at the right moment in the show.", "plain_english": "A production cue is a signal to make something happen in a show. It might start music, move scenery, or change lights. The stage manager calls each cue at the right time.", "purpose_function": "It coordinates the timing of technical actions with the performance, so every department fires its element on the same agreed moment and the show runs consistently each night.", "practical_application": "The stage manager warns, stands by, and then calls the production cue on 'GO,' and the relevant operator executes it—firing a sound cue, a light change, or a scene move.", "category": "Cueing", "related_terms": ["Cue", "Standby", "Cue light", "Production channel", "Cue list", "GO"], "common_mistakes": ["Executing a production cue on the standby instead of waiting for the 'GO'.", "Missing the warning/standby step, so an operator is caught unready when the cue is called.", "Confusing a production/technical cue with the actor's line or visual cue that triggers it."], "scenario_contexts": ["The stage manager calling a sound production cue on 'GO' at a scripted moment.", "Numbering all production cues in the prompt book so each department follows the same list.", "Using cue lights to give a silent standby and GO for a production cue in a noisy wing."]}, "083f9271-0b0b-4973-a4c8-051ccc143c2e": {"definition": "The headset worn by a crew member to communicate on the production intercom—combining a headphone (single- or double-muff) with a boom microphone—so the wearer can hear the intercom channel(s) and talk hands-free. It connects to a beltpack or intercom station and typically follows the manufacturer's standard connector and impedance for the system in use.", "plain_english": "A production headset is what a crew member wears to talk on the intercom. It has an earpiece and a mic. It lets the crew hear calls and reply hands-free.", "purpose_function": "It lets crew hear the stage manager's calls and talk back while keeping both hands free for their work, forming the wearer's interface to the intercom system.", "practical_application": "A technician plugs the production headset into a beltpack or panel, sets mic and listen levels, and checks talk and listen on the assigned channel during the comms check.", "category": "Intercom systems", "related_terms": ["Partyline intercom", "Beltpack", "Intercom station", "Production channel", "Listen level", "Matrix intercom"], "common_mistakes": ["Using a headset with the wrong connector, impedance, or wiring for the system, giving weak or distorted audio.", "Leaving the mic live and talking over the channel, or setting listen level so high it causes feedback.", "UNSAFE: Setting intercom listen level dangerously high for long shifts, risking hearing damage over time."], "scenario_contexts": ["Issuing production headsets and beltpacks to the running crew before a show.", "Doing a comms check on each production headset before the house opens.", "Choosing single-muff headsets for deck crew who must also hear the stage."]}, "ec8e3af9-0c6a-45a3-b374-e4bb4d6ec947": {"definition": "In intercom and IFB (Interruptible Foldback) systems, a program interrupt is the momentary muting or ducking of the program (foldback) audio in a performer's earpiece so that a director or producer can insert a spoken instruction. It is the function that makes an IFB circuit 'interruptible': the program feed is the default in the ear, and talkback overrides it only while the interrupt key is active.", "plain_english": "A program interrupt lets a director talk into a performer's earpiece. Normally the earpiece plays the show audio. When the director presses a key, that audio drops and the performer hears the instruction instead.", "purpose_function": "It exists so production staff can cue or correct on-air talent privately, without the audience hearing, by overriding the program feed in the earpiece only when needed.", "practical_application": "A technician feeds talent earpieces from an IFB channel, then sets the interrupt so pressing the talk key ducks the program audio and passes the director's voice.", "category": "Communications", "related_terms": ["IFB", "Foldback", "Talkback", "Intercom", "Mix-minus", "Party-line intercom"], "common_mistakes": ["Confusing the program interrupt with the mix-minus itself; the interrupt only overrides the foldback momentarily, it does not create the feed.", "Assuming the performer always hears talkback, when in fact they hear it only while the interrupt key is active.", "Setting the interrupt to hard-mute rather than duck, which can leave talent with no program reference during the instruction."], "scenario_contexts": ["A floor director cueing a news anchor through an IFB earpiece.", "A producer counting a host down to a live segment.", "Interrupting a presenter's program feed to relay a last-minute script change."]}, "d89c4474-dad8-4d41-a8ae-bfa328f84643": {"definition": "Prop-triggered audio is sound playback started by a physical prop or set piece rather than by an operator pressing GO. A sensor, switch, or contact closure on the prop sends a trigger to a playback system or show controller, which fires the associated audio cue when the prop is touched, moved, lifted, or otherwise activated.", "plain_english": "Prop-triggered audio is sound that plays when someone touches or moves a prop. A hidden switch or sensor on the object sends a signal. That signal tells the player to start the sound. No one has to press a button.", "purpose_function": "It exists to tie a sound directly to an action on stage or in an attraction, so the audio fires exactly when a guest or actor uses the object, without an operator watching for the moment.", "practical_application": "A technician fits a prop with a switch or sensor wired to a contact-closure or MIDI input on a playback system, then maps that input to the sound cue.", "category": "Cueing & playback", "related_terms": ["Trigger", "Contact closure", "Cue", "Show control", "MIDI Show Control", "QLab"], "common_mistakes": ["Assuming any prop can trigger reliably, when contact bounce or a loose switch can cause missed or doubled triggers.", "Forgetting to debounce the input or add a lockout, so one action fires the sound many times.", "Not planning a manual backup, leaving no way to fire the sound if the prop sensor fails during a show."], "scenario_contexts": ["A haunted attraction where opening a coffin lid starts a scream.", "A museum exhibit that plays narration when a visitor lifts a handset.", "An immersive show where picking up a phone prop triggers a recorded voice."]}, "81963be0-f44f-4e19-8a5c-45664d17c17f": {"definition": "'Quiet on comms' is a verbal instruction on an intercom system directing all users to stop non-essential talk and keep the channel clear, typically because a critical cue sequence or standby is imminent. It is a discipline call, comparable to 'quiet on set,' that reserves the party-line for essential cueing traffic.", "plain_english": "'Quiet on comms' is a call that tells everyone on the headset system to stop chatting. The crew stays silent so important cues can be heard clearly. It is used just before a tricky or fast part of the show.", "purpose_function": "It exists to keep the intercom channel free of clutter during high-pressure moments, so standbys and GO cues are heard clearly and are not missed.", "practical_application": "A stage manager or caller says 'quiet on comms' before a complex sequence, and the crew hold non-urgent conversation until the sequence is done.", "category": "Communications", "related_terms": ["Intercom", "Party-line intercom", "Standby", "Stage manager", "Cue", "Talkback"], "common_mistakes": ["Treating the call as optional; ignoring it clutters the channel and can mask a GO cue.", "Confusing it with muting your own pack; it asks the whole channel to stay clear, not one user.", "Continuing side conversations on the same channel instead of moving them to another channel."], "scenario_contexts": ["A stage manager calling for quiet before a fast scene change.", "Clearing the channel ahead of a pyrotechnic or flying cue.", "Silencing crew chatter during the opening standby of a live broadcast."]}, "a6d1e6d0-1bc4-4ae9-b3fa-fc7cd1814ba3": {"definition": "Randomized scare audio is a show-control technique in which startle sound effects are selected and/or timed at random so that their occurrence is unpredictable from one cycle or guest to the next. A controller draws from a pool of effects, or randomizes the interval between them, to prevent guests from learning the pattern, which dulls a scare on repeat exposure.", "plain_english": "Randomized scare audio is scary sound that plays at random times or in a random order. Because it is unpredictable, guests cannot learn when the next noise is coming. This keeps a haunted attraction surprising, even for people who walk through many times.", "purpose_function": "It exists to keep startle effects effective over many repeats, since a sound that always plays at the same moment stops being scary once guests can predict it.", "practical_application": "A technician loads several effects into a random playlist, or sets a randomized timer on a show controller, so each cycle picks a different sound or interval.", "category": "Cueing & playback", "related_terms": ["Show control", "Randomization", "Trigger", "Cue", "Playback", "Prop-Triggered Audio"], "common_mistakes": ["Assuming 'random' means endless variety, when a small pool of sounds still repeats and becomes predictable.", "Overlapping random triggers without a lockout, so several scares stack into noise.", "UNSAFE: Letting a loud random effect run without a level limit, which can expose guests and staff to hazardous sound peaks."], "scenario_contexts": ["A haunted house where a corridor plays a different scare sound on each pass.", "A themed queue line that fires random ambient shrieks at varying intervals.", "An escape room that randomizes which unsettling sound plays when a drawer is opened."]}, "7511ad1b-ae32-451c-8355-18f518c273fb": {"definition": "In a cue-light system, a red cue light is the lamp used as the standby, or warning, signal to a crew member or performer. In the common convention the stage manager switches the red light on to mean 'stand by,' and the GO is given either by turning it off or by a separate GO lamp; the light lets a cue be passed silently, without speech on the intercom or within earshot of the audience.", "plain_english": "A red cue light is a small warning lamp used to signal a crew member. When the stage manager turns it on, it usually means 'get ready.' The GO signal is given by turning the light off, or by a second light. It lets people take a cue in silence.", "purpose_function": "It exists to give a silent, visual cue where talking on comms is impossible or would be overheard, warning the operator to stand by before the GO is given.", "practical_application": "A technician runs a cue-light head to a position such as a fly rail or a trap, and the stage manager drives the red lamp from the prompt desk to warn the operator to stand by.", "category": "Cueing & playback", "related_terms": ["Cue light", "Standby", "GO", "Stage manager", "Prompt desk", "Intercom"], "common_mistakes": ["Assuming the red always means stop or GO; color and on/off meaning vary between houses, so confirm the local convention before the show.", "Reading the light backwards; in the common single-lamp system the light ON is stand by and the light OFF is the GO.", "Relying only on the cue light with no backup, since a failed lamp can leave an operator with no cue."], "scenario_contexts": ["Warning a fly operator to stand by for a scenery move in a noisy loading position.", "Cueing a performer to enter from a spot where speech on comms would be heard by the audience.", "Giving a silent standby to a follow-spot operator in a booth."]}, "d933885e-030a-4184-b020-fc54fe1a3d32": {"definition": "Redundant playback is a reliability arrangement in which a backup playback system runs in parallel with the primary, mirroring its cue list and state, so that show audio or video continues if the primary fails. The systems are typically synchronized so the backup can take over automatically or on a manual switch with minimal interruption.", "plain_english": "Redundant playback means running a backup player alongside the main one. Both hold the same cues and stay in step. If the main system crashes, the backup keeps the sound going. It is a safety net so the show does not fall silent.", "purpose_function": "It exists to protect a live show from a single point of failure, keeping playback running through a crash, disk fault, or hardware failure of the primary system.", "practical_application": "A technician sets up a second playback machine mirroring the primary and links them so cues stay synchronized, then switches output to the backup if the main system fails.", "category": "Cueing & playback", "related_terms": ["Playback", "Failover", "QLab", "Show control", "Cue", "Redundancy"], "common_mistakes": ["Assuming redundancy is automatic; without proper syncing the backup may not sit at the same point in the cue list.", "Sharing one audio interface or one power source between both machines, which reinstates a single point of failure.", "Never testing failover, so the backup is untried when it is actually needed."], "scenario_contexts": ["A long-running musical using a primary and backup playback computer for the sound score.", "A theme-park attraction mirroring media servers so a crash does not stop the show.", "A corporate keynote running a duplicate playback rig ready to take over instantly."]}, "b312a11a-6f66-4637-a013-9eafea2a82e8": {"definition": "A reveal cue is a scripted cue - of lighting, sound, automation, or a combination - timed to disclose something to the audience for the first time, such as an actor, a set element, or a change of scene that has been hidden. It is defined by its dramatic intent: the cue is executed at the moment the concealed element is meant to be seen or heard.", "plain_english": "A reveal cue is a cue that shows the audience something for the first time. It might raise the lights on a hidden set, or open a curtain, at just the right moment. The whole point is the surprise of seeing it appear.", "purpose_function": "It exists to control the exact moment a hidden element is disclosed, so the surprise or dramatic impact lands on the beat the director wants.", "practical_application": "A technician programs the reveal cue - lights, curtain, or an automation move - and takes it on the stage manager's GO so the hidden element appears on cue.", "category": "Cueing & playback", "related_terms": ["Cue", "GO", "Standby", "Blackout", "Fade", "Automation cue"], "common_mistakes": ["Taking the reveal cue too early or too late, which spoils the surprise or leaves a dead moment.", "Forgetting to hide or pre-set the element before the reveal, so there is nothing concealed to reveal.", "Treating a reveal as one department's job when it often needs lights, sound, and automation to hit together."], "scenario_contexts": ["Raising lights to reveal a full set behind a scrim on cue.", "Opening a traveler curtain to disclose a surprise entrance.", "Flying in a piece of scenery to reveal a new location at a scene change."]}, "31f3f316-3cc1-482c-8e16-8f60d6718ef8": {"definition": "RTS is a manufacturer of professional intercom systems widely used in broadcast, live production, and theatre. The RTS line spans two-wire party-line systems, digital matrix intercoms such as the ADAM and ODIN frames, keypanels, belt packs, and interfaces; 'RTS intercom' generally refers to equipment or a system drawn from this range.", "plain_english": "RTS is a company that makes headset intercom gear for shows and broadcasts. Their equipment lets crew talk to each other over wired and wireless channels. It ranges from simple belt packs to large systems that route many talk paths at once.", "purpose_function": "RTS intercom equipment exists to give production crews reliable point-to-point and group communication, from small party-line setups to large matrix systems that route many talk paths.", "practical_application": "A technician patches RTS keypanels and belt packs into a matrix or party-line, assigns talk keys to channels, and traces the intercom signal path during setup and troubleshooting.", "category": "Communications", "related_terms": ["Intercom", "Party-line intercom", "Matrix intercom", "Keypanel", "Belt pack", "Clear-Com"], "common_mistakes": ["Assuming RTS and Clear-Com party-line packs interconnect directly, when the two-wire systems use different signaling and often need an interface.", "Confusing the two-wire party-line with the digital matrix; they are configured and cabled very differently.", "Forgetting to set channel or key assignments, so a panel is connected but cannot talk to the intended group."], "scenario_contexts": ["Building a matrix intercom for a broadcast truck using RTS keypanels.", "Running an RTS two-wire party-line for a theatre crew.", "Interfacing an RTS system with wireless belt packs for a live event."]}, "9ed20264-3763-4b11-8e46-cda236dd030a": {"definition": "'Say again' is a standard voice-procedure phrase (proword) meaning 'repeat all, or the specified portion, of your last transmission.' It is used on radio and intercom in place of the word 'repeat,' which in some procedures carries a different, specialized meaning; the request can be qualified, as in 'say again all after...'.", "plain_english": "'Say again' means 'please repeat what you just said.' It is used on radios and headsets when a message was not heard clearly. Crews say 'say again' instead of 'repeat,' because 'repeat' can mean something else in radio talk.", "purpose_function": "It exists to request a clear, unambiguous repeat of a missed or garbled message, using a fixed phrase everyone recognizes so the request itself is not misunderstood.", "practical_application": "A crew member who misses part of a cue or instruction on comms says 'say again' to have it repeated, adding 'all after...' to ask for only the missing part.", "category": "Communications", "related_terms": ["Proword", "Copy", "Roger", "Intercom", "Standby", "Radio procedure"], "common_mistakes": ["Using 'repeat' instead of 'say again', when in some voice procedures 'repeat' has a different, specialized meaning and can cause confusion.", "Asking to 'say again' a whole long message when only part was missed; 'say again all after...' asks for just the missing part.", "Mumbling the request on a busy channel instead of keying up clearly and waiting for the repeat."], "scenario_contexts": ["A follow-spot operator asking the caller to repeat a garbled cue number.", "A crew member on a noisy stage requesting a repeat of a standby.", "A radio user asking for only the missing portion of an instruction with 'say again all after...'."]}, "e487a834-8271-425f-b34a-05f5be1dc5e7": {"definition": "Scene-change music is music played to accompany and cover a change of scenery or setting during a stage production, bridging the interval between scenes so that dramatic pacing is maintained while the stage is reset.", "plain_english": "Scene-change music is music played while the crew changes the set between scenes. It fills the quiet gap so the show keeps flowing and the crowd stays interested.", "purpose_function": "It sustains dramatic pacing and masks the noise and visible activity of a scenery change, keeping the audience engaged during an otherwise dead moment on stage.", "practical_application": "A sound operator fires the scene-change music cue as the lights dim, then fades it out once the next scene is set and ready to begin.", "category": "Sound Cues", "related_terms": ["Cue", "Underscore", "Blackout", "Sound cue", "Fade"], "common_mistakes": ["Making the music too short so it ends before the scene change is finished, leaving an awkward silence.", "Playing scene-change music too loudly, which masks backstage cue calls or startles the audience.", "Failing to fade the music out cleanly, so it cuts off abruptly as the next scene begins."], "scenario_contexts": ["Covering a full set change between acts of a musical.", "Bridging a short transition while actors reset props in a play.", "Underscoring a blackout so the audience does not sit in silence."]}, "40f3cdcb-cb8b-4834-814b-a151d0d5b777": {"definition": "A session file is the project document that a digital audio workstation or show-control application saves; it stores references to media plus all track, cue, edit, mix, routing and automation data rather than the audio itself. Examples include a Pro Tools .ptx session or a QLab workspace, which point to external audio files instead of embedding them.", "plain_english": "A session file is the file your audio software saves. It holds your tracks, cues, edits, and mix settings. It only points to the sound files, so keep them together.", "purpose_function": "It lets a technician save, reopen and share an entire project in one document, preserving every setting so work resumes exactly where it stopped.", "practical_application": "An engineer opens the session file at the start of a shift to reload a mix, keeping its linked audio files in place so no tracks go offline.", "category": "Project Files", "related_terms": ["Cue", "QLab", "Digital audio workstation", "Timecode", "Backup"], "common_mistakes": ["Assuming the session file contains the audio itself, then moving it without the linked media so tracks go missing.", "Not saving or backing up the session file regularly, risking loss of all edit and mix work.", "Opening a session in a different software version and losing plug-in or format compatibility."], "scenario_contexts": ["Loading a Pro Tools .ptx session at the start of a mix.", "Opening a QLab workspace to run sound cues for a performance.", "Copying a session file plus its audio folder to move a project to another studio."]}, "64c0475f-4a43-45ab-9fef-0281ea2efab7": {"definition": "The executive 'GO' command that triggers a standing-by cue to execute; the stage manager delivers it verbally over the cue system after a standby, and show-control protocols such as MIDI Show Control carry an equivalent GO message that runs the targeted cue on a device.", "plain_english": "'Go' is the command that fires a cue. First the stage manager says 'standby' to warn the operator. Then 'go' tells them to run the cue right now. It works like a starter shouting 'go' at a race.", "purpose_function": "It gives one clear, agreed trigger word so every department starts its cue at the same instant, keeping the show tightly synchronized.", "practical_application": "A stage manager calls 'Lighting cue 5, go' over the headset, and the board operator presses go on the console the moment they hear it.", "category": "Cueing Command", "related_terms": ["Stand by", "Stage manager cue", "Show stop", "Cue light", "MIDI Show Control"], "common_mistakes": ["Placing the word 'go' anywhere but the very end of the call, since operators are trained to act on 'go' instantly and may fire early.", "Confusing the warning 'standby' with the execute command 'go' and running the cue too soon.", "Calling 'go' without first giving a standby, leaving the operator unprepared."], "scenario_contexts": ["A stage manager calls 'Sound cue 12, go' to start a musical number's playback.", "A show-control system sends a MIDI Show Control GO message to fire a lighting cue automatically.", "A caller runs a rapid sequence of 'go' commands during a fast scene change."]}, "0247e4f5-bbe4-4ff1-90ac-4e7f17d829cf": {"definition": "A halt to a running show, whether an unplanned stoppage of the live performance for safety or technical reasons, or the STOP command issued through cueing and show-control systems (such as MIDI Show Control) to freeze running cues and automated machinery.", "plain_english": "A show stop is when a performance is halted partway through. It may stop for a safety problem or a technical fault. A 'stop' command can also freeze cues and moving scenery. Everyone waits until it is safe to go on.", "purpose_function": "It provides an agreed way to freeze the action fast, protecting performers, crew, and audience and preventing damage when something goes wrong.", "practical_application": "If a performer is injured or scenery jams, the stage manager calls a show stop and holds all cues and automation until the problem is cleared.", "category": "Cueing Command", "related_terms": ["Show go", "Stand by", "Emergency stop", "Stage manager cue", "Automation"], "common_mistakes": ["UNSAFE: Continuing cues or scenery moves during a show stop instead of holding everything until the stage manager confirms it is safe.", "Treating a show stop as a failure to avoid, rather than a planned safety tool crews should use without hesitation.", "Confusing a show stop, which halts the running performance, with a scheduled hold or intermission."], "scenario_contexts": ["A stage manager stops the show when an audience member needs medical help.", "An automation operator hits emergency stop, triggering a show stop, when a moving deck jams.", "The show is stopped after a technical fault kills the sound system mid-scene."]}, "a34e9e6b-35d2-4443-b33c-924517586e37": {"definition": "A microphone at the stage manager's or prompt-corner position used to make spoken calls to the company over the backstage paging and show-relay system, delivering time calls, standbys, and pages to performers in dressing rooms and backstage areas.", "plain_english": "A show-call microphone lets the stage manager talk to the whole backstage. They use it for time calls like 'half hour' and to page actors. Speakers in dressing rooms and the wings carry the message. It works like a backstage announcer.", "purpose_function": "It gives the stage manager one microphone to reach every backstage and dressing-room speaker, so the company gets timing calls and cues wherever they are.", "practical_application": "From the prompt corner the stage manager keys the show-call mic to announce 'Act One beginners to the stage, please' over the paging speakers.", "category": "Communications Equipment", "related_terms": ["Stage announce microphone", "Show relay", "Paging system", "Prompt corner", "Stand by"], "common_mistakes": ["Confusing the show-call mic, which sends calls to the company, with the show-relay feed, which carries the live audio of the performance.", "Leaving the mic keyed open, so backstage chatter is broadcast to all dressing rooms.", "Assuming calls reach everyone without checking that all paging zones are switched on."], "scenario_contexts": ["A deputy stage manager gives the 'quarter-hour' call over the show-call mic before curtain.", "The stage manager pages a late performer to the stage during a scene change.", "Beginners are called to their places through the backstage paging speakers."]}, "d8de67bc-259a-4cd7-82f1-ca88d24a09e1": {"definition": "A data network, typically Ethernet-based, that interconnects show-control processors, consoles, and devices so control messages and cue-trigger protocols (such as sACN/E1.31, Art-Net, MIDI Show Control, OSC, and timecode) pass between them to run and synchronize a production.", "plain_english": "A show-control network is the data network that links show gear. Lighting, sound, video, and scenery systems all connect to it. Cue messages travel over it so devices fire together. It works like the nervous system of the show.", "purpose_function": "It lets separate control systems share triggers and status over one network, so cues across lighting, audio, video, and automation stay coordinated and can be run from a single controller.", "practical_application": "An integrator patches consoles and processors into managed switches and assigns them to the show-control network, keeping control traffic separate from other data.", "category": "Networking", "related_terms": ["sACN", "Art-Net", "MIDI Show Control", "Open Sound Control", "Show-control position", "Timecode"], "common_mistakes": ["Mixing show-control traffic with general office data on one flat network, risking latency and dropped cues.", "Ignoring protocol-specific settings like sACN universes or MIDI channels, so devices never receive their cues.", "UNSAFE: Trusting a single unmanaged network for life-safety automation, with no redundancy or isolation."], "scenario_contexts": ["A theme-park show links audio, lighting, and animatronics over one show-control network.", "A theatre routes sACN lighting data and MIDI Show Control cues across its show-control network.", "A technician troubleshoots a missed video cue by tracing packets on the show-control network."]}, "4283704e-5b52-4f0c-bd74-a00d0d9245ab": {"definition": "An intercom headset fitted with a single earcup covering one ear and a boom microphone, leaving the other ear uncovered so the wearer can hear the intercom and the surrounding environment at the same time.", "plain_english": "A single-muff headset covers just one ear. A boom mic is attached for talking on the intercom. The open ear still hears the room and the show. Crew who must stay aware of their surroundings pick this style.", "purpose_function": "It lets a user monitor the intercom while keeping one ear open for live sound, spoken warnings, or the performance, trading isolation for situational awareness.", "practical_application": "A stage manager or deck crew member wears a single-muff headset so they can take cues on comms yet still hear people and action on stage.", "category": "Communications Equipment", "related_terms": ["Double-muff headset", "Beltpack", "Intercom", "Boom microphone", "Partyline", "Spot channel"], "common_mistakes": ["Choosing a single-muff headset for a very loud pit or stage-side position where one open ear makes the intercom hard to hear.", "Assuming single- and double-muff headsets differ electrically, when the real difference is the number of earcups.", "Wearing the earcup on the wrong side, blocking the ear that needs to hear the stage."], "scenario_contexts": ["A deck carpenter uses a single-muff headset to hear both cues and nearby scenery moves.", "A followspot operator picks a single-muff headset to keep one ear on the live music.", "A stage manager calls the show on a single-muff headset while listening to the auditorium."]}, "dbaba881-a8b1-4404-b814-06aa2e763e85": {"definition": "A dedicated intercom channel (a partyline circuit or matrix talk path) reserved for communication with followspot operators, over which the caller gives spot pickups, sizing, colour, and timing cues.", "plain_english": "A spot channel is an intercom line just for the followspot operators. The person calling spots uses it to tell each operator what to light. Keeping spots on their own line stops chatter from other crew. It is like a private group call for the spotlight team.", "purpose_function": "It separates followspot cueing onto its own circuit so spot operators hear clear pickup instructions without traffic from lighting, sound, or stage-management channels.", "practical_application": "A spot caller sits on the spot channel and calls 'Spot 1, pick up the singer, half body, in three, two, one' to each operator.", "category": "Intercom Channel", "related_terms": ["Followspot", "Partyline", "Intercom", "Beltpack", "Single-muff headset", "Stage manager cue"], "common_mistakes": ["Putting followspot calls on the main lighting channel, cluttering it and confusing the board operator.", "Forgetting to assign every spot operator's beltpack to the spot channel, so some never hear pickups.", "Calling pickups without a countdown, so operators hit their targets at different times."], "scenario_contexts": ["A spot caller runs four followspots on the spot channel during a concert.", "The lighting designer listens to the spot channel to check pickup timing in tech.", "A musical assigns a separate spot channel so number cues do not crowd the stage-management channel."]}, "29ce0316-0caf-4e6d-83c1-ee490c0fb42e": {"definition": "A microphone that feeds the Stage Announce (SA) output of an intercom system, letting an operator broadcast speech over loudspeakers in backstage, dressing-room, and sometimes front-of-house areas, separate from the headset intercom circuits.", "plain_english": "A stage announce microphone sends the operator's voice to backstage speakers. It is used to make announcements everyone can hear out loud. This is different from the private headset intercom. Think of it as a backstage PA microphone.", "purpose_function": "It provides a loudspeaker paging path from the intercom system, so calls and announcements reach people who are not wearing a headset.", "practical_application": "An operator presses the SA (stage announce) key on the main station and speaks into the stage announce mic to page performers over backstage speakers.", "category": "Communications Equipment", "related_terms": ["Show-call microphone", "Intercom", "Paging system", "Program feed", "Stage manager cue"], "common_mistakes": ["Confusing stage announce, which is loudspeaker paging, with the headset intercom, which only reaches people wearing beltpacks.", "Leaving the SA key latched, broadcasting private talk over the backstage speakers.", "Setting stage-announce level so high it feeds back or bleeds onto the stage during a show."], "scenario_contexts": ["A stage manager pages the cast to places using the stage announce microphone.", "A crew chief makes a call over backstage speakers before a scene change.", "An operator uses stage announce to reach dressing rooms during a technical rehearsal."]}, "f4d0c7ca-d9f9-4609-959a-3e3ba7787c00": {"definition": "A signal given by the stage manager to trigger an action during a performance, delivered verbally as a 'standby' then 'go' over the cue and comms system, or by a cue light, directing a department (lighting, sound, flys, automation) or performers to execute their next move.", "plain_english": "A stage manager cue is a signal that tells a crew member or actor to act. The stage manager gives it by voice on the headset or with a cue light. First comes a warning, then the 'go'. This keeps the whole show in time.", "purpose_function": "It lets one person, the stage manager, coordinate every department from a single position, so all technical and performance actions happen in the right order at the right moment.", "practical_application": "The stage manager calls the show by giving each cue in sequence, warning operators with a standby and then releasing the action with 'go'.", "category": "Cueing", "related_terms": ["Stand by", "Show go", "Cue light", "Prompt book", "Show-call microphone"], "common_mistakes": ["Giving cues without a consistent standby, so operators are caught unready.", "Naming the department and cue number after the word 'go', when 'go' must always come last.", "Relying only on cue lights in a noisy space without confirming operators saw them."], "scenario_contexts": ["The stage manager cues a blackout by calling 'LX 20, go' at the end of a scene.", "A cue light turns off to give the fly crew their go for a scenery move.", "During tech the director asks the SM to hold the next cue to reset a moment."]}, "e128f618-f289-470d-93c1-b1ced47a11a3": {"definition": "The warning command a stage manager gives before a cue's 'go', alerting the named operator or performer to be ready to execute; it sets the readiness state that a following 'go' then releases.", "plain_english": "'Stand by' is a warning that a cue is coming. The stage manager says it to the right operator before the 'go'. It tells them to get ready and pay attention. Then 'go' tells them to act.", "purpose_function": "It primes the correct operator so that when 'go' is called the action happens instantly, preventing missed or late cues.", "practical_application": "The stage manager calls 'Standby lighting cue 8 and sound cue 4,' waits for the moment, then calls each 'go'.", "category": "Cueing Command", "related_terms": ["Show go", "Stage manager cue", "Cue light", "Show stop", "Prompt book"], "common_mistakes": ["Skipping the standby and jumping straight to 'go', leaving the operator unprepared.", "Standing by cues far too early, so operators lose focus before the go.", "Confusing 'standby', meaning get ready, with 'go', meaning act now, and firing on the warning."], "scenario_contexts": ["The stage manager calls 'Standby LX 12' a few lines before the cue.", "A cue light switched on tells an operator to stand by for their go.", "Several departments are put on standby before a big synchronized effect."]}, "25208a81-d64d-4e68-b759-a616301e2a3e": {"definition": "A warning call given by the stage manager to the sound operator or audio department, alerting them that an audio cue is approaching and to make ready; it precedes the executive 'GO' that fires the cue, following the standby-then-go cueing convention used throughout live performance.", "plain_english": "This is a warning the stage manager gives the sound operator. It means an audio cue is coming soon. The operator gets ready but waits. Then 'go' tells them to fire the cue. It works like 'on your marks' before 'go' in a race.", "purpose_function": "It gives the sound operator advance warning to focus and prepare, so the audio cue fires cleanly the instant 'GO' is called.", "practical_application": "Over the headset the stage manager says 'Stand by audio cue 12,' and the sound operator confirms and readies the cue on the playback system.", "category": "Cueing Command", "related_terms": ["Standby cue", "Show go", "Stand by", "Cue light", "Talk key"], "common_mistakes": ["Treating the standby as the trigger and firing the cue early instead of waiting for 'GO'.", "Not acknowledging the standby, so the caller does not know the operator is ready.", "Calling the standby too late, leaving the operator no time to prepare."], "scenario_contexts": ["A stage manager warns the sound operator before a large playback cue in a musical.", "An operator hears 'stand by audio' and cues up the next sound file.", "A caller gives standbys to lighting, sound, and fly before a fast scene change."]}, "75e06daa-8f19-4e9f-aaf7-5fec01f271cb": {"definition": "A preparatory instruction, placed before the execute cue, that alerts an operator or department that its next cue is imminent and to stand ready; in the standard cueing sequence the standby is always given first and is followed by the 'GO' that executes the cue.", "plain_english": "A standby cue is a warning that a cue is about to happen. The operator gets ready but does not act yet. The 'go' that follows fires the real cue. Think of a runner set in the blocks before the gun.", "purpose_function": "It separates preparation from execution, so operators stay alert and every department can act together the moment 'GO' is called.", "practical_application": "A stage manager reads the standbys from the calling script, warning each department before its cue, then calls 'GO' at the exact moment.", "category": "Cueing Command", "related_terms": ["Stand by audio", "Show go", "Cue light", "Visual cue", "Stage manager cue"], "common_mistakes": ["Confusing the standby with the go and executing the cue on the warning.", "Skipping the standby and calling 'go' cold, catching the operator unprepared.", "Standing by too many cues at once, so operators lose track of which is next."], "scenario_contexts": ["A stage manager gives 'Standby LX 5 and Sound 5' before a scene climax.", "A cue light turns on to signal a standby to a fly operator who cannot hear the headset clearly.", "A board operator holds ready after a standby until the 'go' arrives."]}, "39c2b764-9e1d-40be-a38b-165a13236f90": {"definition": "A short, sharp musical or sound-effect flourish (also called a 'sting') used to punctuate a dramatic moment, entrance, reveal, or transition; it is typically a brief, high-impact cue lasting only a second or a few seconds.", "plain_english": "A stinger is a short, sharp burst of sound or music. It marks a big moment, like a shock reveal or a punchline. You have heard the classic 'dun dun dunnn' chord. That quick jolt of sound is a stinger.", "purpose_function": "It grabs the audience's attention and emphasizes a key moment, adding punch or tension exactly where the story needs it.", "practical_application": "A sound operator fires a stinger the instant a villain appears or a reveal happens, timing it tightly to the stage action.", "category": "Sound Cues", "related_terms": ["Sound cue", "Underscore", "Scene-change music", "Vamp", "Show go"], "common_mistakes": ["Confusing the sound-effect stinger with a 'stinger' extension cable used by electricians and grips.", "Making the stinger too long, so it stops being a sharp punctuation.", "Firing the stinger slightly late, so it misses the visual moment it should mark."], "scenario_contexts": ["A short brass sting hits as the detective names the killer.", "A horror sound stinger punctuates a jump scare in a haunted attraction.", "A quick musical sting covers a fast blackout scene change."]}, "f2c6f462-d1a3-46cc-be35-f470806d2faf": {"definition": "A safety principle in entertainment automation and rigging holding that when any crew member calls or triggers a stop, all motion halts immediately and unconditionally, with no debate or delay, and movement does not resume until the person who called the stop and the operator agree it is safe.", "plain_english": "This safety rule says any crew member can call 'stop.' When they do, all moving scenery and flying halts at once. Nobody argues or asks why first. The show only continues when everyone agrees it is safe.", "purpose_function": "It gives everyone the power to halt dangerous movement instantly, protecting performers and crew because the person who spots a hazard may not be the operator.", "practical_application": "During a flying or automation sequence, if anyone shouts or triggers 'stop,' the operator freezes all motion at once and waits for the all-clear before continuing.", "category": "Safety Protocol", "related_terms": ["Stop-all command", "Emergency stop", "Show stop", "Taking weight", "Quiet on comms"], "common_mistakes": ["UNSAFE: Questioning or delaying a stop call to avoid interrupting the show instead of halting all motion immediately.", "UNSAFE: Restarting movement after a stop without confirmation from the person who called it.", "Assuming only the operator or stage manager may call a stop, when anyone who sees danger can and should."], "scenario_contexts": ["A crew member sees a performer's flying line fouling and calls 'stop,' halting the move.", "A rehearsal is paused instantly when someone spots a rigging problem.", "An automation operator hits stop the moment a stop is called over comms."]}, "dd7b99bf-7b87-436f-b09c-3a668ded7f19": {"definition": "A single control command that immediately halts every running cue, playback, or motorized movement in a system at once, rather than stopping items individually; examples include a show-control 'stop all' or 'panic' that ends all active cues, and an emergency stop that removes power from machinery.", "plain_english": "A stop-all command halts everything running at once. One button ends all playing cues or stops all moving scenery. Operators use it when something goes wrong and there is no time to stop items one by one.", "purpose_function": "It provides a fast, single action to shut down all activity in an emergency or reset, so an operator need not find and stop each cue separately.", "practical_application": "A sound operator hits the QLab 'stop all' (Escape) or panic to silence every running audio cue at once when a scene goes wrong.", "category": "Cueing Command", "related_terms": ["Stop means stop", "Emergency stop", "Show stop", "Show go", "Cue light"], "common_mistakes": ["UNSAFE: Relying on a software 'stop all' as a safety emergency stop, when moving machinery needs a hardware emergency stop that cuts power.", "Confusing 'stop all' (which halts everything) with stopping a single selected cue.", "Assuming 'stop all' also resets or rewinds cues, when it usually just halts them where they are."], "scenario_contexts": ["An operator presses Escape in QLab to stop all running sound cues during a false start.", "A stage manager calls for all cues to be stopped when the show is halted.", "An automation console's stop-all is used to freeze all moving scenery at once."]}, "347e999c-3116-4287-b7a1-65b15a43f729": {"definition": "A rigging and performer-flying call announcing that the flying line or hoist is beginning to bear the load - the point at which the system takes up the weight of a performer, scenery, or an arbor - so the crew knows the load has transferred to the flying system.", "plain_english": "'Taking weight' is a call used when flying scenery or performers. It means the line is now holding the load. The rope goes tight and the weight moves onto the flying system. The crew says it aloud so everyone knows.", "purpose_function": "It warns the crew at the critical moment the load transfers, a high-risk point where a fault would be dangerous, so everyone can watch and be ready to stop.", "practical_application": "As a flying operator hauls in, they call 'taking weight' the moment the performer's harness line goes taut and lifts them off the deck.", "category": "Rigging Call", "related_terms": ["Stop means stop", "Stop-all command", "Emergency stop", "Stand by", "Show go"], "common_mistakes": ["UNSAFE: Continuing to move the line after 'taking weight' without watching the performer and load for problems.", "Failing to call 'taking weight,' so the crew misses the critical load-transfer moment.", "Confusing 'taking weight' (load going onto the line) with unloading the arbor."], "scenario_contexts": ["A flying operator calls 'taking weight' as a performer is lifted into a flight.", "A fly crew announces taking weight when a heavy scenic piece leaves the deck.", "During a load-in, an operator calls taking weight while transferring a batten's load."]}, "a3ef815d-65c7-448e-a779-9b5b64a51448": {"definition": "The push-to-talk button on an intercom station or keypanel that activates the user's microphone onto a selected channel or destination; it may operate momentarily (active only while held) or latch on, and is usually paired with a listen level for that channel.", "plain_english": "A talk key is the button you press to speak on an intercom. Hold it and your microphone opens to that channel. Let go and you stop talking. Some can latch on so you need not keep holding. It works like a walkie-talkie button.", "purpose_function": "It lets a user control exactly when and to whom they talk, keeping channels clear until someone deliberately opens their microphone.", "practical_application": "A stage manager presses the talk key for the lighting channel to give a cue, then releases it so the channel stays quiet.", "category": "Communications", "related_terms": ["Talk to stage", "Talk to front of house", "Two-wire intercom", "Program interrupt", "Talkback microphone"], "common_mistakes": ["Leaving a talk key latched on, so background noise floods the channel and blocks others.", "Pressing the wrong channel's talk key and speaking to the wrong department.", "Forgetting to press the talk key at all, so no one hears the call."], "scenario_contexts": ["An operator holds the talk key to answer a call on the party-line intercom.", "A stage manager latches the talk key to make a long announcement.", "A crew member presses the talk key for stage to warn dancers of a set move."]}, "a0f2bfe2-c70b-46b8-990a-8132af90194d": {"definition": "An intercom routing or talk-key selection that opens the user's microphone to the front-of-house position - the FOH mix and control area in the auditorium - letting the stage manager or crew communicate directly with the sound or lighting operators stationed there.", "plain_english": "This means opening your intercom to the front-of-house team. Front of house is the mix position out in the audience seating. Pressing this talk route lets you speak straight to the operators there. It is like dialing one person.", "purpose_function": "It directs a call only to the FOH operators, so a message reaches the right people without tying up the whole intercom system.", "practical_application": "A stage manager selects the FOH channel's talk key to check a level with the front-of-house sound engineer before the house opens.", "category": "Communications", "related_terms": ["Talk to stage", "Talk key", "Two-wire intercom", "Talkback microphone", "Program interrupt"], "common_mistakes": ["Confusing 'front of house' (the audience-side mix and public areas) with backstage or the stage position.", "Talking to all channels when only the FOH operators needed the message.", "Selecting the FOH talk route but forgetting to press or hold the talk key."], "scenario_contexts": ["A stage manager talks to front of house to confirm the FOH engineer is ready.", "A show caller checks a spotlight cue with the FOH lighting operator.", "A technician contacts the front-of-house position to troubleshoot a feed."]}, "022936b0-b050-4996-bfef-31c8406412dc": {"definition": "An intercom routing or talk selection that sends the user's microphone to the stage - either to crew on a stage intercom channel or, via a Stage Announce (SA) output, to loudspeakers that address performers and crew on and around the stage.", "plain_english": "This opens your intercom so you can talk to the stage. It may reach crew wearing headsets on the stage channel. It can also feed loudspeakers on stage, called stage announce. That lets the whole stage area hear you at once.", "purpose_function": "It lets the stage manager or crew pass calls and warnings to people working on stage, either privately on headsets or aloud over stage loudspeakers.", "practical_application": "Before a set move, a stage manager selects talk to stage or triggers stage announce to warn everyone on stage to stand clear.", "category": "Communications", "related_terms": ["Talk to front of house", "Talk key", "Two-wire intercom", "Program interrupt", "Talkback microphone"], "common_mistakes": ["Confusing the private stage headset channel with stage announce loudspeakers heard by everyone.", "UNSAFE: Failing to warn the stage over talk-to-stage before moving scenery or flying a piece.", "Using stage announce during a performance, where it could be heard by the audience."], "scenario_contexts": ["A stage manager uses stage announce to call performers for beginners.", "A crew chief talks to stage crew on the intercom to coordinate a scene change.", "A caller warns the stage to stand clear before an automated set piece moves."]}, "19305bac-dd9e-4dd9-84c0-7f4d01a72539": {"definition": "A dedicated microphone that lets an operator speak to performers or crew over a separate communication path, routed to monitor, cue, or intercom buses rather than to the main program output.", "plain_english": "A special mic that lets the engineer talk to the band or crew. Its voice goes only to their headphones or speakers, not to the audience.", "purpose_function": "It provides a private voice channel so an operator can give directions and coordinate a session without that speech reaching the audience or the main mix.", "practical_application": "A recording engineer presses the talkback button to coach musicians through their headphones, and a front-of-house engineer uses it to talk to the monitor engineer or stage.", "category": "Communications", "related_terms": ["Two-wire intercom", "Monitor mix", "Cue send", "Intercom headset", "Foldback"], "common_mistakes": ["Leaving the talkback button or fader latched on, so private talk bleeds into the recording or the main PA.", "Assuming talkback audio is always recorded when it is normally routed only to cue and monitor buses.", "Confusing the talkback mic with a performance or measurement microphone."], "scenario_contexts": ["A tracking session where the engineer coaches a vocalist between takes over headphones.", "A live show where the front-of-house engineer coordinates with the monitor engineer.", "A broadcast studio where the director speaks to on-air talent."]}, "7bfedefe-3122-4ba0-a780-851600bf6c85": {"definition": "An automation event set to fire when an incoming timecode signal, such as SMPTE/EBU longitudinal timecode (LTC) or MIDI Time Code (MTC), reaches a specified frame value, locking playback or cues to a master clock.", "plain_english": "A setting that starts a cue at an exact moment on a running clock. When the timecode reaches that time, the sound or effect fires by itself.", "purpose_function": "It ties cues to a shared time reference so audio, lighting, and video stay in sync and repeat identically at every performance.", "practical_application": "A sound operator sets a playback system such as QLab to trigger a cue when timecode hits a chosen frame, aligning effects with recorded video or a click track.", "category": "Synchronisation", "related_terms": ["SMPTE timecode", "MIDI Time Code", "LTC", "MIDI Show Control", "Frame rate"], "common_mistakes": ["Mismatching the frame rate between the timecode source and receiver, causing drift or missed triggers.", "Confusing free-run timecode with record-run, so triggers fire at the wrong moment.", "Forgetting that dropped or noisy timecode stops triggers from firing reliably."], "scenario_contexts": ["Firing sound cues in sync with a pre-recorded video wall.", "Synchronising a live band's backing tracks and lighting to one SMPTE master.", "Automating a theme-park show so all systems start together each cycle."]}, "fe7d3096-52db-491a-8fa4-415516d7f4bc": {"definition": "In haunted attractions, audio content such as screams, stingers, ambience, or dialogue that is played on a preset schedule or timer so a sound effect coincides with a scripted scare moment.", "plain_english": "Sound in a haunted house that plays on a set timer. It is timed so a scary noise hits right when the scare happens.", "purpose_function": "It makes a scare's sound land at the right instant to heighten the startle effect and keep the effect repeatable across many cycles.", "practical_application": "A haunt technician programs a show-control player so a scream fires on a fixed interval or at a cue point, matching an animatronic or an actor's action.", "category": "Effects Timing", "related_terms": ["Trigger-to-Audio Latency", "Variable Scare Delay", "Timecode trigger", "Show control", "Sound effect cue"], "common_mistakes": ["Assuming a fixed timer will always line up with a live actor, whose timing varies.", "Setting the audio ahead of or behind the visual scare, which weakens the startle.", "UNSAFE: Running scare audio at sound levels that risk hearing damage to guests or staff without checking permissible noise exposure limits."], "scenario_contexts": ["A haunted-maze room where a scream plays at a fixed interval.", "A stinger synced to a drop-panel scare.", "A queue-line ambience loop that fires stingers on a schedule."]}, "dab2cfee-12e0-4136-9175-6100ea291e2f": {"definition": "The time delay between the moment a trigger event is received, such as a MIDI note, contact closure, OSC message, or timecode hit, and the moment the corresponding sound is actually heard from the loudspeakers.", "plain_english": "The short gap between pressing 'go' and hearing the sound. It covers the time the system needs to react and play the audio.", "purpose_function": "Knowing this delay lets designers offset the timing so a triggered sound lands exactly with the visual or physical action it accompanies.", "practical_application": "A technician measures the delay from trigger to audible output, then cues the sound earlier so it matches an animatronic move or a video frame.", "category": "Signal Timing", "related_terms": ["Latency", "Timecode trigger", "Buffer size", "MIDI Show Control", "Timed Scare Audio"], "common_mistakes": ["Ignoring buffer size and network delay, which add to the total latency.", "Assuming latency is zero, so the triggered sound arrives late against the action.", "Measuring only software latency and forgetting converter, DSP, and speaker-distance delay."], "scenario_contexts": ["Tuning a scare so the sound hits the same instant as a puppet lunge.", "Aligning a gunshot sound effect to a stage flash.", "Checking playback delay before locking a cue to video."]}, "386368af-a94c-4967-a578-14c415a4ed84": {"definition": "An analog party-line intercom in which one shared audio conductor carries full-duplex voice in both directions, with DC power and audio riding on a single cable pair, so every beltpack on the channel hears and speaks on a common bus.", "plain_english": "A shared talk line where everyone on the channel hears everyone else at once. One cable carries both the voices and the power for the beltpacks.", "purpose_function": "It gives a crew a simple, always-open group talk channel for live coordination, using minimal cabling because power and audio share one line.", "practical_application": "A stage manager and crew each wear a beltpack on the same two-wire channel to call cues during a show, daisy-chaining packs with standard mic cable.", "category": "Communications", "related_terms": ["Four-wire intercom", "Beltpack", "Party line", "Talkback microphone", "Intercom headset"], "common_mistakes": ["Confusing two-wire, a single shared channel, with four-wire, which uses separate send and receive paths.", "Using unshielded or wrong cable, which causes hum and power problems on the line.", "Shorting or mis-wiring an XLR connector, which can damage beltpacks and the main power supply."], "scenario_contexts": ["A theatre crew calling a show on a single Clear-Com channel.", "A small live event linking stage manager, spot operators, and audio.", "A house of worship coordinating volunteers on one talk line."]}, "5e33d7a9-5e61-430c-ace0-5d8d73c36633": {"definition": "Music played at low level beneath spoken dialogue, narration, or stage action to support mood and pacing without competing with the voices; in theatre and film it is scored or cued to run under a scene.", "plain_english": "Quiet background music played under talking or action on stage or screen. It sets the mood without covering the actors' words.", "purpose_function": "It shapes the emotional tone and continuity of a scene while keeping speech clear and easy to understand.", "practical_application": "A sound operator fades an underscore cue in beneath a monologue and rides its level so it never masks the dialogue.", "category": "Music Cueing", "related_terms": ["Vamp", "Sound cue", "Fade", "Ambience", "Visual cue"], "common_mistakes": ["Mixing the underscore too loud, so it masks dialogue and hurts intelligibility.", "Forgetting to fade it out cleanly at the end of the scene.", "Confusing underscore, music under a scene, with a stand-alone musical number."], "scenario_contexts": ["Music playing softly under a dramatic monologue.", "A tense cue running beneath a chase before the dialogue.", "Ambient music under a scene transition in a play."]}}$ape$::jsonb)) d WHERE g.id=d.id;
UPDATE glossary g SET definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END, plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END, purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END, practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END, category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END, related_terms = CASE WHEN d.p ? 'related_terms' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'related_terms')) ELSE g.related_terms END, common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'common_mistakes')) ELSE g.common_mistakes END, scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN ARRAY(SELECT jsonb_array_elements_text(d.p->'scenario_contexts')) ELSE g.scenario_contexts END FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($ape${"d1aefd5f-e067-4478-8c6f-fd602927725f": {"definition": "A short, repeated musical passage, usually a simple chord or accompaniment figure, that is looped an indefinite number of times until a cue or the next section begins ('vamp till ready').", "plain_english": "A short piece of music that repeats over and over until a signal to move on. Musicians 'vamp' to fill time until the next part starts.", "purpose_function": "It lets performers hold a musical section open for a variable length, so live action, dialogue, or a scene change can finish before the music continues.", "practical_application": "A music director or band loops a vamp while a scene change completes, then moves to the next number on the stage manager's cue.", "category": "Music Cueing", "related_terms": ["Underscore", "Sound cue", "Visual cue", "Click track", "Bar and beat"], "common_mistakes": ["Treating a vamp as a fixed length instead of an open loop that waits for a cue.", "Missing the cue to exit the vamp, so the music runs too long.", "Confusing a vamp, a repeated fill, with an intro or a full musical section."], "scenario_contexts": ["A pit band vamping while an actor crosses the stage.", "Holding a vamp until a lead performer is ready to enter.", "Looping an accompaniment until a scene change ends."]}, "df22c9b2-2da0-46b0-aafd-200b1bfd4271": {"definition": "In haunted attractions, an adjustable or randomised delay between a trigger and the firing of a scare effect, used so the timing changes between groups and the scare stays unpredictable.", "plain_english": "A changing wait time before a scare goes off. Because the delay varies, guests can't guess exactly when the scare will hit.", "purpose_function": "It stops guests from learning the timing, keeping repeat scares surprising and letting an operator tune the moment for each group.", "practical_application": "A haunt operator sets a random delay range in the show-control system so a triggered scare fires at a slightly different instant for every group.", "category": "Effects Timing", "related_terms": ["Timed Scare Audio", "Trigger-to-Audio Latency", "Timecode trigger", "Show control", "Sound effect cue"], "common_mistakes": ["Setting the delay range so wide that the scare misses the guest entirely.", "Confusing a variable delay with a fixed timer, then expecting identical timing each cycle.", "Forgetting that added delay stacks on top of the system's own trigger-to-audio latency."], "scenario_contexts": ["Randomising a jump-scare so returning guests cannot anticipate it.", "Tuning the delay to fire as a group reaches the scare zone.", "Varying a startle effect across successive tour groups."]}, "0b50d196-2781-47c4-b0ad-baceaf01a33d": {"definition": "A cue given or taken by sight rather than sound, such as a stage manager's cue light, a hand or baton gesture, or an on-stage action, signalling a performer or operator to execute a specific action at the right moment.", "plain_english": "A signal you watch for instead of hear. A light, a hand sign, or an action on stage tells you exactly when to do your part.", "purpose_function": "It coordinates timing silently when a spoken or audio cue would be heard by the audience or would be unreliable in a noisy space.", "practical_application": "A stage manager triggers a cue light to tell a flyman or actor to go, or an operator watches for a set on-stage move before firing a cue.", "category": "Cueing", "related_terms": ["Sound cue", "Cue light", "Standby", "Go", "Timecode trigger"], "common_mistakes": ["Relying on a visual cue the operator cannot clearly see from their position.", "Missing the cue by looking away at the critical moment.", "Confusing the standby signal with the actual go cue."], "scenario_contexts": ["A conductor's downbeat cueing a sound or lighting hit.", "A stage manager's cue light telling a performer to enter.", "An operator watching an actor reach a mark before firing an effect."]}, "7cd1fe50-e77d-4db8-91e3-38d1558a6244": {"definition": "A submix containing only the vocal elements of a production, typically lead and backing vocals combined, rendered as a single audio file or bus and kept separate from the instrumental parts for mixing, mastering, playback, or remixing.", "plain_english": "A vocal stem is all the singing mixed into one track, with no instruments. It lets you handle the voices on their own.", "purpose_function": "It groups the vocals into one manageable track so engineers can balance, process, or replace the voices without disturbing the instrumental mix.", "practical_application": "A playback operator loads separate vocal and band stems so a live engineer can lift the lead vocal, or drop it for a singalong, on demand.", "category": "Audio Stems", "related_terms": ["Stem", "Submix", "Backing track", "Playback", "Multitrack"], "common_mistakes": ["Confusing a vocal stem, a grouped submix, with a single isolated vocal channel.", "Assuming a stem can be split back into its separate channels; the balance inside it is baked in.", "Exporting stems from different start points or sample rates, so they no longer line up on playback."], "scenario_contexts": ["Delivering separate vocal and instrumental stems to a mastering engineer.", "Running a live show from stems so the engineer can ride the lead vocal level.", "Sending a vocal stem to a remixer who replaces the backing music."]}, "831d0d93-13a5-4b51-9964-136dfeab6581": {"definition": "In a cueing or show-control system, a programmed delay between triggering a cue and the start of its action, or the interval the system waits before automatically continuing to the next cue.", "plain_english": "Wait time is a set pause built into a cue. The system counts down that time before it acts or moves to the next cue.", "purpose_function": "It lets an operator time cues precisely and automate sequences, so effects fire at the right moment without a separate manual trigger.", "practical_application": "A QLab or lighting operator sets a pre-wait or post-wait so a cue starts a few seconds after Go, or auto-continues from the one before it.", "category": "Cue Timing", "related_terms": ["Cue", "Auto-follow", "Pre-wait", "Post-wait", "Go"], "common_mistakes": ["Confusing a pre-wait, the delay before a cue starts, with a post-wait, the delay before the next cue continues.", "Setting a wait time and forgetting it, so a cue seems to fire late or not at all.", "Assuming a wait time waits for the previous cue to finish; that behaviour is an auto-follow, not a wait."], "scenario_contexts": ["Delaying a sound effect two seconds after the light cue that precedes it.", "Building an automatic cue chain that runs a sequence hands-free.", "Timing a blackout to land a set interval after a music cue ends."]}, "15b95c5e-4574-4ea3-bb8b-3eb10cbc7799": {"definition": "Recorded or live music played over the house system while the audience arrives and takes their seats, before a performance or event begins.", "plain_english": "Walk-in music is the music playing while the crowd comes in and finds seats. It plays before the show actually starts.", "purpose_function": "It sets the mood, covers the noise of an arriving audience, and signals that the space is open while the show has not yet started.", "practical_application": "A sound operator starts a walk-in playlist as the house opens and fades it out at the top of the show on the stage manager's cue.", "category": "Music Cueing", "related_terms": ["Walk-out music", "House music", "Preshow", "Sound cue", "Fade"], "common_mistakes": ["Leaving walk-in music so loud that arriving patrons must shout over it.", "Forgetting to fade it out cleanly before the opening cue.", "Confusing walk-in music, played before the show, with underscore played during a scene."], "scenario_contexts": ["A playlist running as doors open before a concert.", "Ambient music covering audience chatter before a play begins.", "Branded music looping as guests enter a corporate event."]}, "76a44a17-1cab-49ac-9a46-084fa253a97f": {"definition": "Recorded or live music played over the house system as the audience leaves the venue after a performance or event has ended; also called play-off or exit music.", "plain_english": "Walk-out music is the music that plays as people leave at the end. It fills the room while the crowd heads for the doors.", "purpose_function": "It gives the ending an upbeat close, covers the sound of a departing crowd, and keeps the energy up as people exit.", "practical_application": "A sound operator brings up a walk-out track as the final bow or credits finish and runs it until the house has cleared.", "category": "Music Cueing", "related_terms": ["Walk-in music", "House music", "Play-off", "Sound cue", "Fade"], "common_mistakes": ["Starting walk-out music before the performance has truly ended, cutting off applause.", "Confusing walk-out music, played as the audience leaves, with walk-in music played as they arrive.", "Killing it too early, before the audience has actually cleared the room."], "scenario_contexts": ["Upbeat music playing as a theatre audience files out.", "Exit music after the final act of a concert.", "A closing playlist as guests leave a ceremony."]}, "9c3f6a50-bbd1-4113-a2bb-f467f581e7e6": {"definition": "A stage-management or crew communications call announced over the intercom to confirm that the performance has begun and show conditions, such as cue discipline and quiet on headset, are now in effect.", "plain_english": "'We are in show' is a call meaning the performance has started. From then on the crew follows strict show rules and stays quiet on headset.", "purpose_function": "It marks the switch from pre-show preparation to live running, so everyone on comms knows cues are live and casual chatter must stop.", "practical_application": "A stage manager announces 'we are in show' at the top of the performance, telling the crew to tighten headset discipline and stand ready for cues.", "category": "Communications", "related_terms": ["Standby", "Go", "Quiet on cans", "Places", "Cue light"], "common_mistakes": ["Continuing casual talk on headset after the call, breaking cue discipline.", "Confusing 'we are in show' with 'places', which calls performers to their start positions.", "Missing the call and treating a live show like a rehearsal."], "scenario_contexts": ["A stage manager opening a theatre performance on comms.", "A show caller marking the start of a live broadcast.", "A crew tightening headset discipline as the house lights fade."]}}$ape$::jsonb)) d WHERE g.id=d.id;
COMMIT;
